create or replace function public.log_dashboard_audit_event()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  audit_before jsonb;
  audit_after jsonb;
  audit_subject jsonb;
  audit_entity_id text;
  audit_entity_label text;
begin
  if tg_op = 'DELETE' then
    audit_before := to_jsonb(old);
    audit_after := null;
  elsif tg_op = 'UPDATE' then
    audit_before := to_jsonb(old);
    audit_after := to_jsonb(new);
  else
    audit_before := null;
    audit_after := to_jsonb(new);
  end if;

  audit_subject := coalesce(audit_after, audit_before, '{}'::jsonb);
  audit_entity_id := audit_subject ->> 'id';
  audit_entity_label := coalesce(
    audit_subject ->> 'name',
    audit_subject ->> 'title',
    audit_subject ->> 'email',
    audit_subject ->> 'login_id',
    audit_entity_id
  );

  insert into public.dashboard_audit_logs (
    actor_profile_id,
    actor_email,
    actor_role,
    action,
    entity_table,
    entity_id,
    entity_label,
    before_record,
    after_record
  )
  values (
    auth.uid(),
    lower(coalesce(auth.jwt() ->> 'email', '')),
    public.current_dashboard_role(),
    tg_op,
    tg_table_name,
    audit_entity_id,
    audit_entity_label,
    audit_before,
    audit_after
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;
