returns jsonb
language sql
security invoker
set search_path = ''
as $$
  select dashboard_private.create_registration_case_impl(
    p_student_name, p_school_grade, p_school_name, p_parent_phone,
    p_student_phone, p_campus, p_inquiry_at, p_subjects,
    p_request_note, p_priority, p_request_key
  );
$$;
