  p_status text,
  p_material_link text,
  p_request_key text
)
returns jsonb
language sql
security invoker
set search_path = ''
as $$
  select dashboard_private.complete_registration_level_test_attempt_impl(
    p_attempt_id, p_status, p_material_link, p_request_key
  );
