begin;
set local lock_timeout = '5s';
alter table public.classes
  add column if not exists subject_area_key text;
alter table public.textbooks
  add column if not exists subject_area_key text,
  add column if not exists subject_area_subject text
    generated always as (
      case when subject = 'science' then '과학'::text else null::text end
    ) stored;
alter table public.textbooks
  drop constraint if exists textbooks_subject_required;
alter table public.textbooks
  add constraint textbooks_subject_required
  check (
    subject is not null
    and subject in ('english', 'math', 'science', 'other')
  );
do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'classes_subject_area_fkey'
      and conrelid = 'public.classes'::regclass
  ) then
    alter table public.classes
      add constraint classes_subject_area_fkey
      foreign key (subject, subject_area_key)
      references public.academic_subject_areas(subject, area_key)
      not valid;
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'textbooks_subject_area_fkey'
      and conrelid = 'public.textbooks'::regclass
  ) then
    alter table public.textbooks
      add constraint textbooks_subject_area_fkey
      foreign key (subject_area_subject, subject_area_key)
      references public.academic_subject_areas(subject, area_key)
      not valid;
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'classes_science_taxonomy_check'
      and conrelid = 'public.classes'::regclass
  ) then
    alter table public.classes
      add constraint classes_science_taxonomy_check
      check (
        (
          subject = '과학'
          and grade is not null
          and grade in ('고1', '고2', '고3')
          and subject_area_key is not null
        )
        or (
          subject is distinct from '과학'
          and subject_area_key is null
        )
      ) not valid;
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'textbooks_science_taxonomy_check'
      and conrelid = 'public.textbooks'::regclass
  ) then
    alter table public.textbooks
      add constraint textbooks_science_taxonomy_check
      check (
        (
          subject = 'science'
          and school_levels = array['high']::text[]
          and grade_levels = array['h1', 'h2', 'h3']::text[]
          and subject_area_key is not null
        )
        or (
          subject is distinct from 'science'
          and subject_area_key is null
        )
      ) not valid;
  end if;
end
$$;
create or replace function dashboard_private.assert_science_subject_area_assignment_v1()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  mapped_subject text;
  subject_area_label text;
begin
  mapped_subject := case
    when tg_table_name = 'classes' and new.subject = '과학' then '과학'
    when tg_table_name = 'textbooks' and new.subject = 'science' then '과학'
    else null
  end;

  if mapped_subject is null then
    if new.subject_area_key is not null then
      raise exception 'science_subject_area_non_science_forbidden'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if new.subject_area_key is null then
    raise exception 'science_subject_area_required'
      using errcode = '23514';
  end if;

  select area.label
  into subject_area_label
    from public.academic_subject_areas as area
    where area.subject = mapped_subject
      and area.area_key = new.subject_area_key
      and area.is_active = true;

  if subject_area_label is null then
    raise exception 'science_subject_area_inactive_or_unknown'
      using errcode = '23514';
  end if;

  if tg_table_name = 'textbooks' then
    new.sub_subject := subject_area_label;
  end if;

  return new;
end;
$$;
drop trigger if exists enforce_science_subject_area_on_classes
  on public.classes;
create trigger enforce_science_subject_area_on_classes
before insert or update of subject, subject_area_key
on public.classes
for each row
execute function dashboard_private.assert_science_subject_area_assignment_v1();
drop trigger if exists enforce_science_subject_area_on_textbooks
  on public.textbooks;
create trigger enforce_science_subject_area_on_textbooks
before insert or update of subject, subject_area_key, sub_subject
on public.textbooks
for each row
execute function dashboard_private.assert_science_subject_area_assignment_v1();
create or replace function public.list_active_science_subject_areas_v1()
returns table (
  subject text,
  area_key text,
  label text,
  sort_order integer,
  is_active boolean
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'science_subject_areas_authentication_required'
      using errcode = '42501';
  end if;

  return query
  select
    area.subject,
    area.area_key,
    area.label,
    area.sort_order,
    area.is_active
  from public.academic_subject_areas as area
  where area.subject = '과학'
    and area.is_active = true
  order by area.sort_order, area.area_key;
end;
$$;
alter function dashboard_private.assert_science_subject_area_assignment_v1()
  owner to postgres;
alter function public.list_active_science_subject_areas_v1()
  owner to postgres;
revoke all on function dashboard_private.assert_science_subject_area_assignment_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.list_active_science_subject_areas_v1()
  from public, anon, authenticated, service_role;
grant execute on function public.list_active_science_subject_areas_v1()
  to authenticated;
commit;
begin;
set local lock_timeout = '5s';
alter table public.google_chat_webhook_settings
  drop constraint if exists google_chat_webhook_settings_channel_check;
alter table public.google_chat_webhook_settings
  add constraint google_chat_webhook_settings_channel_check
  check (channel in ('executive', 'admin', 'math', 'english', 'science'));
create or replace function dashboard_private.notification_google_chat_audience_ready_v1(
  p_audience_key text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_channels text[];
  v_channel text;
  v_row public.google_chat_webhook_settings%rowtype;
  v_expected_mask text;
begin
  v_channels := case p_audience_key
    when 'management_team' then array['admin']::text[]
    when 'executive_team' then array['executive']::text[]
    when 'subject_team' then array['english', 'math', 'science']::text[]
    else null
  end;
  if v_channels is null then
    return false;
  end if;

  foreach v_channel in array v_channels
  loop
    select connection_row.*
    into v_row
    from public.google_chat_webhook_settings connection_row
    where connection_row.channel = v_channel;
    if not found
      or v_row.connection_state not in ('legacy_active', 'encrypted_active')
      or v_row.last_error_code is not null
    then
      return false;
    end if;
    begin
      v_expected_mask := dashboard_private.notification_google_chat_webhook_mask_v1(
        v_row.webhook_url
      );
    exception
      when sqlstate '22023' then
        return false;
    end;
    if v_row.connection_state = 'encrypted_active' and (
      nullif(pg_catalog.btrim(v_row.webhook_url_ciphertext), '') is null
      or v_row.webhook_url_mask is distinct from v_expected_mask
    ) then
      return false;
    end if;
  end loop;
  return true;
end;
$$;
create or replace function dashboard_private.replace_google_chat_connection_v1_impl(
  p_actor uuid,
  p_channel text,
  p_webhook_url text,
  p_webhook_url_ciphertext text,
  p_webhook_url_mask text,
  p_expected_revision bigint,
  p_request_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_request_kind constant text := 'google_chat_connection_replace';
  v_fingerprint text;
  v_ledger_kind text;
  v_ledger_fingerprint text;
  v_ledger_response jsonb;
  v_ledger_found boolean := false;
  v_row public.google_chat_webhook_settings%rowtype;
  v_row_found boolean := false;
  v_before_summary jsonb;
  v_response jsonb;
  v_expected_mask text;
begin
  if p_actor is null or not exists (
    select 1
    from public.profiles profile
    where profile.id = p_actor
      and profile.role = 'admin'
  ) then
    raise exception 'notification_access_denied' using errcode = '42501';
  end if;
  if p_channel is null or p_channel not in ('admin', 'executive', 'math', 'english', 'science') then
    raise exception 'notification_connection_unknown' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 or p_request_id is null then
    raise exception 'notification_connection_invalid' using errcode = '22023';
  end if;
  if p_webhook_url_ciphertext is null
    or p_webhook_url_ciphertext !~ '^v1:[A-Za-z0-9_-]+:[A-Za-z0-9_-]+:[A-Za-z0-9_-]+$'
    or p_webhook_url_mask is null
  then
    raise exception 'notification_connection_invalid' using errcode = '22023';
  end if;
  v_expected_mask := dashboard_private.notification_google_chat_webhook_mask_v1(
    p_webhook_url
  );
  if p_webhook_url_mask <> v_expected_mask then
    raise exception 'notification_connection_invalid' using errcode = '22023';
  end if;

  v_fingerprint := pg_catalog.md5(
    pg_catalog.jsonb_build_object(
      'actor_id', p_actor,
      'channel', p_channel,
      'webhook_url', p_webhook_url,
      'webhook_url_mask', p_webhook_url_mask,
      'expected_revision', p_expected_revision::text
    )::text
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('notification-request:' || p_request_id::text, 0)
  );
  select
    ledger.request_kind,
    ledger.request_fingerprint,
    ledger.response_payload
  into v_ledger_kind, v_ledger_fingerprint, v_ledger_response
  from dashboard_private.notification_request_ledger ledger
  where ledger.request_id = p_request_id;
  v_ledger_found := found;
  if v_ledger_found then
    if v_ledger_kind <> v_request_kind or v_ledger_fingerprint <> v_fingerprint then
      raise exception 'idempotency_key_reused' using errcode = '22023';
    end if;
    return v_ledger_response;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('google-chat-connection:' || p_channel, 0)
  );
  select connection_row.*
  into v_row
  from public.google_chat_webhook_settings connection_row
  where connection_row.channel = p_channel
  for update of connection_row;
  v_row_found := found;
  if v_row_found then
    if v_row.revision <> p_expected_revision then
      raise exception 'notification_connection_revision_conflict' using errcode = '40001';
    end if;
    v_before_summary := pg_catalog.jsonb_build_object(
      'connection_state', v_row.connection_state,
      'revision', v_row.revision::text,
      'configured', v_row.connection_state <> 'disconnected'
    );
    update public.google_chat_webhook_settings connection_row
    set webhook_url = p_webhook_url,
        webhook_url_ciphertext = p_webhook_url_ciphertext,
        webhook_url_mask = p_webhook_url_mask,
        connection_state = 'encrypted_active',
        revision = connection_row.revision + 1,
        updated_by = p_actor,
        last_verified_at = null,
        last_error_code = null,
        updated_at = pg_catalog.clock_timestamp()
    where connection_row.channel = p_channel
    returning connection_row.* into v_row;
  else
    if p_expected_revision <> 0 then
      raise exception 'notification_connection_revision_conflict' using errcode = '40001';
    end if;
    v_before_summary := null;
    insert into public.google_chat_webhook_settings(
      channel,
      webhook_url,
      webhook_url_ciphertext,
      webhook_url_mask,
      connection_state,
      revision,
      updated_by,
      last_verified_at,
      last_error_code
    ) values (
      p_channel,
      p_webhook_url,
      p_webhook_url_ciphertext,
      p_webhook_url_mask,
      'encrypted_active',
      1,
      p_actor,
      null,
      null
    )
    returning * into v_row;
  end if;

  v_response := dashboard_private.notification_connection_safe_json_v1(v_row, true);
  insert into dashboard_private.notification_audit_logs(
    entity_kind,
    entity_id,
    action,
    actor_profile_id,
    actor_kind,
    request_id,
    before_summary,
    after_summary,
    reason_code
  ) values (
    'google_chat_connection',
    v_response ->> 'connection_key',
    'connection_replaced',
    p_actor,
    'user',
    p_request_id,
    v_before_summary,
    pg_catalog.jsonb_build_object(
      'connection_state', v_row.connection_state,
      'revision', v_row.revision::text,
      'configured', true
    ),
    'operator_connection_replace'
  );
  insert into dashboard_private.notification_request_ledger(
    request_id,
    request_kind,
    request_fingerprint,
    response_payload
  ) values (
    p_request_id,
    v_request_kind,
    v_fingerprint,
    v_response
  );
  return v_response;
end;
$$;
