begin;
set local lock_timeout = '5s';
create or replace function dashboard_private.notification_control_plane_snapshot_v1(
  p_workflow_key text,
  p_editable boolean
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'scope_key', 'global',
    'workflow_key', p_workflow_key,
    'rules', coalesce(
      (
        select pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'id', rule_row.id,
            'workflow_key', rule_row.workflow_key,
            'event_key', rule_row.event_key,
            'event_label', registry_row.event_label,
            'group_label', registry_row.group_label,
            'trigger_description', registry_row.trigger_description,
            'sort_order', registry_row.event_sort * 100 + registry_row.cell_sort,
            'audience_key', rule_row.audience_key,
            'audience_label', registry_row.audience_label,
            'channel_key', rule_row.channel_key,
            'channel_label', registry_row.channel_label,
            'connection_key', case
              when rule_row.channel_key <> 'google_chat' then null
              when rule_row.audience_key = 'management_team'
                then 'google_chat.management'
              when rule_row.audience_key = 'executive_team'
                then 'google_chat.executive'
              else null
            end,
            'rule_variant_key', rule_row.rule_variant_key,
            'delivery_mode', rule_row.delivery_mode,
            'schedule_key', rule_row.schedule_key,
            'schedule_config', rule_row.schedule_config,
            'enabled', rule_row.enabled,
            'active_template_id', rule_row.active_template_id,
            'revision', rule_row.revision::text,
            'updated_at', rule_row.updated_at,
            'template', pg_catalog.jsonb_build_object(
              'id', template_row.id,
              'rule_id', template_row.rule_id,
              'version', template_row.version::text,
              'title_template', template_row.title_template,
              'body_template', template_row.body_template,
              'allowed_variables', template_row.allowed_variables,
              'payload_schema_version', template_row.payload_schema_version,
              'checksum', template_row.checksum
            )
          )
          order by
            registry_row.event_sort,
            registry_row.cell_sort,
            rule_row.id
        )
        from dashboard_private.notification_settings_ui_registry registry_row
        join dashboard_private.notification_rules rule_row
          on rule_row.id = registry_row.rule_id
         and rule_row.scope_key = 'global'
         and rule_row.workflow_key = registry_row.workflow_key
         and rule_row.event_key = registry_row.event_key
         and rule_row.audience_key = registry_row.audience_key
         and rule_row.channel_key = registry_row.channel_key
         and rule_row.rule_variant_key = registry_row.rule_variant_key
        join dashboard_private.notification_templates template_row
          on template_row.rule_id = rule_row.id
         and template_row.id = rule_row.active_template_id
        where registry_row.workflow_key = p_workflow_key
      ),
      '[]'::jsonb
    ),
    'connections', (
      with connection_catalog(sort_order, channel, connection_key) as (
        values
          (1, 'admin'::text, 'google_chat.management'::text),
          (2, 'executive'::text, 'google_chat.executive'::text),
          (3, 'english'::text, 'google_chat.english'::text),
          (4, 'math'::text, 'google_chat.math'::text),
          (5, 'science'::text, 'google_chat.science'::text)
      )
      select pg_catalog.jsonb_agg(
        case
          when connection_row.channel is not null then
            dashboard_private.notification_connection_safe_json_v1(
              connection_row,
              p_editable
            )
          else pg_catalog.jsonb_build_object(
            'connection_key', catalog_row.connection_key,
            'connection_state', 'disconnected',
            'revision', '0',
            'configured', false,
            'webhook_url_mask', null,
            'last_verified_at', null,
            'last_error_code', null,
            'editable', coalesce(p_editable, false)
          )
        end
        order by catalog_row.sort_order
      )
      from connection_catalog catalog_row
      left join public.google_chat_webhook_settings connection_row
        on connection_row.channel = catalog_row.channel
    ),
    'delivery_summary', (
      with canonical_ranked as (
        select
          event_row.workflow_key,
          event_row.occurrence_key,
          delivery_row.rule_id,
          delivery_row.channel_key,
          delivery_row.target_key,
          delivery_row.target_generation,
          delivery_row.status as projected_status,
          delivery_row.updated_at as evidence_updated_at,
          pg_catalog.row_number() over (
            partition by
              event_row.workflow_key,
              event_row.occurrence_key,
              delivery_row.rule_id,
              delivery_row.channel_key,
              delivery_row.target_key,
              delivery_row.target_generation
            order by delivery_row.updated_at desc, delivery_row.id desc
          ) as identity_rank
        from dashboard_private.notification_deliveries delivery_row
        join dashboard_private.notification_events event_row
          on event_row.id = delivery_row.event_id
        left join dashboard_private.notification_dispatch_ownership_claims ownership_row
          on ownership_row.workflow_key = event_row.workflow_key
         and ownership_row.occurrence_key = event_row.occurrence_key
         and ownership_row.rule_id = delivery_row.rule_id
         and ownership_row.channel_key = delivery_row.channel_key
         and ownership_row.target_key = delivery_row.target_key
         and ownership_row.target_generation = delivery_row.target_generation
        where event_row.scope_key = 'global'
          and event_row.workflow_key = p_workflow_key
          and ownership_row.owner_kind is distinct from 'legacy'
      ),
      projected_evidence as (
        select
          canonical_row.projected_status,
          canonical_row.evidence_updated_at
        from canonical_ranked canonical_row
        where canonical_row.identity_rank = 1

        union all

        select
          case
            when ownership_row.terminal_outcome = 'sent' then 'sent'
            when ownership_row.terminal_outcome = 'failed' then 'failed'
            when ownership_row.terminal_outcome = 'delivery_unknown' then 'delivery_unknown'
            when ownership_row.state = 'reserved' then 'pending'
            else 'delivery_unknown'
          end as projected_status,
          ownership_row.updated_at as evidence_updated_at
        from dashboard_private.notification_dispatch_ownership_claims ownership_row
        where ownership_row.workflow_key = p_workflow_key
          and ownership_row.owner_kind = 'legacy'
      )
      select pg_catalog.jsonb_build_object(
        'pending_count', pg_catalog.count(*) filter (
          where evidence_row.projected_status in ('pending', 'claimed', 'sending', 'retry_wait')
        ),
        'sent_count', pg_catalog.count(*) filter (
          where evidence_row.projected_status = 'sent'
        ),
        'failed_count', pg_catalog.count(*) filter (
          where evidence_row.projected_status = 'failed'
        ),
        'unknown_count', pg_catalog.count(*) filter (
          where evidence_row.projected_status = 'delivery_unknown'
        ),
        'latest_delivery_at', pg_catalog.max(evidence_row.evidence_updated_at)
      )
      from projected_evidence evidence_row
    ),
    'loaded_at', pg_catalog.statement_timestamp()
  );
$$;
alter function dashboard_private.notification_control_plane_snapshot_v1(text, boolean)
  owner to postgres;
revoke all on function dashboard_private.notification_control_plane_snapshot_v1(text, boolean)
  from public, anon, authenticated, service_role;
commit;
begin;
set local lock_timeout = '5s';
alter table public.ops_registration_subject_tracks
  add column if not exists workflow_status text,
  add column if not exists workflow_revision integer,
  add column if not exists workflow_status_entered_at timestamptz;
alter table public.ops_registration_subject_tracks
  alter column workflow_status set default 'inquiry',
  alter column workflow_status set not null,
  alter column workflow_revision set default 1,
  alter column workflow_revision set not null,
  alter column workflow_status_entered_at set default now(),
  alter column workflow_status_entered_at set not null;
alter table public.ops_registration_subject_tracks
  drop constraint if exists ops_registration_subject_tracks_workflow_status_check,
  add constraint ops_registration_subject_tracks_workflow_status_check check (
    workflow_status in (
      'inquiry',
      'level_test_requested',
      'consultation_requested',
      'consultation_completed',
      'waiting_current_class',
      'waiting_new_class',
      'waiting_next_opening',
      'enrollment_requested',
      'payment_in_progress',
      'registered',
      'not_registered',
      'inquiry_only'
    )
  ),
  drop constraint if exists ops_registration_subject_tracks_workflow_revision_check,
  add constraint ops_registration_subject_tracks_workflow_revision_check check (
    workflow_revision > 0
  );
create index if not exists ops_registration_subject_tracks_workflow_status_idx
  on public.ops_registration_subject_tracks(workflow_status, workflow_status_entered_at);
create or replace view public.ops_registration_subject_track_summaries
with (security_invoker = true)
as
select
  track.id,
  track.task_id,
  track.subject,
  track.pipeline_status,
  track.director_profile_id,
  track.director_assignment_source,
  track.director_assignment_rule_key,
  track.waiting_kind,
  track.level_test_retake_decision,
  track.migration_review_required,
  track.stage_entered_at,
  track.updated_at,
  active_visit.scheduled_at as visit_scheduled_at,
  active_visit.place as visit_place,
  active_phone.ready_at as phone_ready_at,
  active_phone.ready_source as phone_ready_source,
  track.workflow_status,
  track.workflow_revision,
  track.workflow_status_entered_at
from public.ops_registration_subject_tracks track
left join lateral (
  select
    appointment.scheduled_at,
    appointment.place
  from public.ops_registration_consultations consultation
  join public.ops_registration_appointments appointment
    on appointment.id = consultation.appointment_id
  where consultation.track_id = track.id
    and consultation.mode = 'visit'
    and consultation.status = 'scheduled'
    and appointment.kind = 'visit_consultation'
    and appointment.status = 'scheduled'
  order by consultation.created_at desc, consultation.id desc
  limit 1
) active_visit on true
left join lateral (
  select
    consultation.ready_at,
    consultation.ready_source
  from public.ops_registration_consultations consultation
  where consultation.track_id = track.id
    and consultation.mode = 'phone'
    and consultation.status = 'waiting'
  order by consultation.created_at desc, consultation.id desc
  limit 1
) active_phone on true;
create or replace function dashboard_private.assert_registration_workflow_status_access(
  p_track_id uuid,
  p_workflow_status text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_role text := coalesce(public.current_dashboard_role(), '');
  v_track public.ops_registration_subject_tracks%rowtype;
begin
  if v_actor_id is null then
    raise exception 'registration_access_denied' using errcode = '42501';
  end if;

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  join public.ops_tasks task on task.id = track.task_id
  where track.id = p_track_id
    and task.type = 'registration';
  if not found then
    raise exception 'registration_access_denied' using errcode = '42501';
  end if;

  if v_role = 'admin' then
    return;
  end if;

  if v_role = 'staff'
    and p_workflow_status in (
      'inquiry',
      'level_test_requested',
      'consultation_requested',
      'payment_in_progress',
      'registered',
      'inquiry_only'
    )
  then
    return;
  end if;

  if p_workflow_status in (
    'consultation_completed',
    'waiting_current_class',
    'waiting_new_class',
    'waiting_next_opening',
    'enrollment_requested',
    'not_registered'
  )
    and v_track.director_profile_id = v_actor_id
    and dashboard_private.is_active_subject_director(v_actor_id, v_track.subject)
  then
    return;
  end if;

  raise exception 'registration_access_denied' using errcode = '42501';
end;
$$;
alter function dashboard_private.assert_registration_workflow_status_access(uuid, text)
  owner to postgres;
revoke all on function dashboard_private.assert_registration_workflow_status_access(uuid, text)
  from public, anon, authenticated, service_role;
create or replace function dashboard_private.set_registration_workflow_status_v1_impl(
  p_track_id uuid,
  p_workflow_status text,
  p_expected_workflow_revision integer,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_request_key text := nullif(pg_catalog.btrim(p_request_key), '');
  v_workflow_status text := nullif(pg_catalog.btrim(p_workflow_status), '');
  v_track public.ops_registration_subject_tracks%rowtype;
  v_target_fingerprint jsonb;
  v_response jsonb;
  v_receipt_matches boolean;
  v_receipt_found boolean := false;
  v_status_changed boolean;
  v_previous_workflow_status text;
begin
  if v_actor_id is null then
    raise exception 'registration_access_denied' using errcode = '42501';
  end if;
  if v_request_key is null then
    raise exception 'request_key_required' using errcode = '22023';
  end if;
  if p_expected_workflow_revision is null or p_expected_workflow_revision < 1 then
    raise exception 'registration_workflow_revision_invalid' using errcode = '22023';
  end if;
  if v_workflow_status not in (
    'inquiry',
    'level_test_requested',
    'consultation_requested',
    'consultation_completed',
    'waiting_current_class',
    'waiting_new_class',
    'waiting_next_opening',
    'enrollment_requested',
    'payment_in_progress',
    'registered',
    'not_registered',
    'inquiry_only'
  ) then
    raise exception 'registration_workflow_status_invalid' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor_id::text || ':' || v_request_key, 0)
  );

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = p_track_id
  for update;
  if not found then
    raise exception 'registration_track_not_found' using errcode = 'P0002';
  end if;

  perform dashboard_private.assert_registration_workflow_status_access(
    v_track.id,
    v_workflow_status
  );

  v_target_fingerprint := pg_catalog.jsonb_build_object(
    'trackId', v_track.id,
    'workflowStatus', v_workflow_status,
    'expectedWorkflowRevision', p_expected_workflow_revision
  );
  select
    mutation.response_payload,
    mutation.task_id = v_track.task_id
      and mutation.mutation_type = 'set_workflow_status'
      and mutation.target_fingerprint = v_target_fingerprint
  into v_response, v_receipt_matches
  from dashboard_private.ops_registration_mutations mutation
  where mutation.actor_id = v_actor_id
    and mutation.request_key = v_request_key;
  v_receipt_found := found;
  if v_receipt_found and not v_receipt_matches then
    raise exception 'idempotency_key_reused' using errcode = '22023';
  end if;
  if v_receipt_found then
    return v_response;
  end if;

  if v_track.workflow_revision <> p_expected_workflow_revision then
    raise exception 'registration_workflow_status_refresh_required' using errcode = '40001';
  end if;

  v_status_changed := v_track.workflow_status is distinct from v_workflow_status;
  if v_status_changed then
    v_previous_workflow_status := v_track.workflow_status;
    update public.ops_registration_subject_tracks track
    set
      workflow_status = v_workflow_status,
      workflow_revision = track.workflow_revision + 1,
      workflow_status_entered_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
    where track.id = v_track.id
    returning track.* into v_track;

    perform dashboard_private.write_registration_track_event_v2(
      v_track.task_id,
      v_track.id,
      'registration_workflow_status_changed',
      v_previous_workflow_status,
      v_workflow_status,
      'manual_status_change',
      pg_catalog.jsonb_build_object(
        'workflowStatus', v_workflow_status,
        'workflowRevision', v_track.workflow_revision
      ),
      'user',
      null
    );
  end if;

  v_response := pg_catalog.jsonb_build_object(
    'trackId', v_track.id,
    'workflowStatus', v_track.workflow_status,
    'workflowRevision', v_track.workflow_revision,
    'workflowStatusEnteredAt', v_track.workflow_status_entered_at
  );

  insert into dashboard_private.ops_registration_mutations(
    actor_id, request_key, task_id, mutation_type, target_fingerprint, response_payload
  ) values (
    v_actor_id,
    v_request_key,
    v_track.task_id,
    'set_workflow_status',
    v_target_fingerprint,
    v_response
  );

  return v_response;
end;
$$;
alter function dashboard_private.set_registration_workflow_status_v1_impl(uuid, text, integer, text)
  owner to postgres;
revoke all on function dashboard_private.set_registration_workflow_status_v1_impl(uuid, text, integer, text)
  from public, anon, authenticated, service_role;
grant execute on function dashboard_private.set_registration_workflow_status_v1_impl(uuid, text, integer, text)
  to authenticated;
create or replace function public.set_registration_workflow_status_v1(
  p_track_id uuid,
  p_workflow_status text,
  p_expected_workflow_revision integer,
  p_request_key text
)
returns jsonb
language sql
security invoker
set search_path = ''
as $$
  select dashboard_private.set_registration_workflow_status_v1_impl(
    p_track_id,
    p_workflow_status,
    p_expected_workflow_revision,
    p_request_key
  );
$$;
alter function public.set_registration_workflow_status_v1(uuid, text, integer, text)
  owner to postgres;
revoke all on function public.set_registration_workflow_status_v1(uuid, text, integer, text)
  from public, anon, authenticated, service_role;
grant execute on function public.set_registration_workflow_status_v1(uuid, text, integer, text)
  to authenticated;
commit;
begin;
set local lock_timeout = '5s';
create function dashboard_private.save_registration_appointment_details_impl(
  p_appointment_id uuid,
  p_task_id uuid,
  p_kind text,
  p_scheduled_at timestamptz,
  p_place text,
  p_track_ids uuid[],
  p_expected_notification_revision integer,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_request_key text := nullif(pg_catalog.btrim(p_request_key), '');
  v_place text := nullif(pg_catalog.btrim(p_place), '');
  v_track_ids uuid[];
  v_fingerprint jsonb;
  v_saved_fingerprint jsonb;
  v_saved_response jsonb;
  v_appointment public.ops_registration_appointments%rowtype;
  v_appointment_id uuid;
  v_activity_id uuid;
  v_activity_ids uuid[] := array[]::uuid[];
  v_track record;
  v_existing_track_ids uuid[];
  v_changed boolean := false;
begin
  if v_actor_id is null then raise exception 'registration_access_denied' using errcode = '42501'; end if;
  if v_request_key is null then raise exception 'request_key_required' using errcode = '22023'; end if;
  if p_kind not in ('level_test', 'visit_consultation') or p_scheduled_at is null or v_place is null then
    raise exception 'registration_appointment_details_invalid' using errcode = '22023';
  end if;
  select coalesce(array_agg(distinct item order by item), array[]::uuid[]) into v_track_ids
  from unnest(coalesce(p_track_ids, array[]::uuid[])) item where item is not null;
  if cardinality(v_track_ids) not between 1 and 2 then raise exception 'registration_appointment_tracks_required' using errcode = '22023'; end if;
  v_fingerprint := jsonb_build_object('appointmentId', p_appointment_id, 'taskId', p_task_id, 'kind', p_kind, 'scheduledAt', p_scheduled_at, 'place', v_place, 'trackIds', to_jsonb(v_track_ids), 'expectedNotificationRevision', p_expected_notification_revision);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor_id::text || ':' || v_request_key, 0));
  select mutation.target_fingerprint, mutation.response_payload into v_saved_fingerprint, v_saved_response
  from dashboard_private.ops_registration_mutations mutation where mutation.actor_id = v_actor_id and mutation.request_key = v_request_key;
  if found then
    if v_saved_fingerprint is distinct from v_fingerprint then raise exception 'registration_mutation_request_conflict' using errcode = '40001'; end if;
    return v_saved_response;
  end if;
  perform 1 from public.ops_tasks task where task.id = p_task_id and task.type = 'registration' for update;
  if not found then raise exception 'registration_appointment_task_mismatch' using errcode = '22023'; end if;
  perform dashboard_private.assert_registration_mutation_access(p_task_id, null, 'save_appointment');
  perform 1 from public.ops_registration_subject_tracks track where track.task_id = p_task_id order by track.id for update;
  if (select count(*) from public.ops_registration_subject_tracks track where track.task_id = p_task_id and track.id = any(v_track_ids)) <> cardinality(v_track_ids) then
    raise exception 'registration_appointment_task_mismatch' using errcode = '22023';
  end if;
  if p_appointment_id is not null then
    select appointment.* into v_appointment from public.ops_registration_appointments appointment
    where appointment.id = p_appointment_id and appointment.task_id = p_task_id for update;
    if not found or v_appointment.kind <> p_kind then raise exception 'registration_appointment_task_mismatch' using errcode = '22023'; end if;
    if v_appointment.notification_revision is distinct from p_expected_notification_revision then raise exception 'registration_appointment_revision_conflict' using errcode = '40001'; end if;
    select coalesce(array_agg(distinct activity.track_id order by activity.track_id), array[]::uuid[]) into v_existing_track_ids
    from (select attempt.track_id from public.ops_registration_level_tests attempt where p_kind = 'level_test' and attempt.appointment_id = p_appointment_id union all select consultation.track_id from public.ops_registration_consultations consultation where p_kind = 'visit_consultation' and consultation.appointment_id = p_appointment_id) activity;
    if v_existing_track_ids is distinct from v_track_ids then raise exception 'registration_appointment_participants_locked' using errcode = '23514'; end if;
    v_changed := v_appointment.scheduled_at is distinct from p_scheduled_at or v_appointment.place is distinct from v_place;
    update public.ops_registration_appointments appointment set scheduled_at = p_scheduled_at, place = v_place, notification_revision = case when v_changed then appointment.notification_revision + 1 else appointment.notification_revision end, updated_at = pg_catalog.now() where appointment.id = p_appointment_id returning * into v_appointment;
    v_appointment_id := v_appointment.id;
  else
    insert into public.ops_registration_appointments(task_id, kind, scheduled_at, place, status, notification_revision, created_by)
    values (p_task_id, p_kind, p_scheduled_at, v_place, 'scheduled', 1, v_actor_id) returning * into v_appointment;
    v_appointment_id := v_appointment.id;
    for v_track in select track.* from public.ops_registration_subject_tracks track where track.id = any(v_track_ids) order by track.id loop
      if p_kind = 'level_test' then
        insert into public.ops_registration_level_tests(track_id, appointment_id, attempt_number, status)
        values (v_track.id, v_appointment_id, coalesce((select max(attempt_number) + 1 from public.ops_registration_level_tests where track_id = v_track.id), 1), 'scheduled') returning id into v_activity_id;
      else
        perform dashboard_private.assert_registration_track_director_ready(v_track.id);
        insert into public.ops_registration_consultations(track_id, appointment_id, mode, status, director_profile_id)
        values (v_track.id, v_appointment_id, 'visit', 'scheduled', v_track.director_profile_id) returning id into v_activity_id;
      end if;
      v_activity_ids := array_append(v_activity_ids, v_activity_id);
    end loop;
  end if;
  for v_track in select track.* from public.ops_registration_subject_tracks track where track.id = any(v_track_ids) order by track.id loop
    perform dashboard_private.write_registration_track_event(p_task_id, v_track.id, 'registration_appointment_details_saved', v_track.pipeline_status, v_track.pipeline_status, null, jsonb_build_object('appointmentId', v_appointment_id, 'kind', p_kind, 'scheduledAt', p_scheduled_at, 'place', v_place, 'notificationRevision', v_appointment.notification_revision, 'changed', v_changed));
  end loop;
  v_saved_response := jsonb_build_object('taskId', p_task_id, 'appointmentId', v_appointment_id, 'notificationRevision', v_appointment.notification_revision, 'trackIds', to_jsonb(v_track_ids), 'activityIds', to_jsonb(v_activity_ids), 'requiresDirectorAssignmentTrackIds', '[]'::jsonb, 'notificationTargets', '[]'::jsonb);
  insert into dashboard_private.ops_registration_mutations(actor_id, request_key, task_id, mutation_type, target_fingerprint, response_payload) values (v_actor_id, v_request_key, p_task_id, 'save_registration_appointment_details', v_fingerprint, v_saved_response);
  return v_saved_response;
end;
$$;
create function public.save_registration_appointment_details_v1(
  p_appointment_id uuid,
  p_task_id uuid,
  p_kind text,
  p_scheduled_at timestamptz,
  p_place text,
  p_track_ids uuid[],
  p_expected_notification_revision integer,
  p_request_key text
)
returns jsonb language sql security invoker set search_path = '' as $$
  select dashboard_private.save_registration_appointment_details_impl($1, $2, $3, $4, $5, $6, $7, $8);
$$;
revoke execute on function public.save_registration_appointment_details_v1(uuid, uuid, text, timestamptz, text, uuid[], integer, text) from public, anon;
grant execute on function public.save_registration_appointment_details_v1(uuid, uuid, text, timestamptz, text, uuid[], integer, text) to authenticated;
create function dashboard_private.save_registration_level_test_result_impl(p_attempt_id uuid, p_status text, p_material_link text, p_request_key text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_attempt public.ops_registration_level_tests%rowtype; v_track public.ops_registration_subject_tracks%rowtype; v_link text := nullif(pg_catalog.btrim(p_material_link), ''); begin
  if auth.uid() is null then raise exception 'registration_access_denied' using errcode = '42501'; end if;
  if nullif(pg_catalog.btrim(p_request_key), '') is null or p_status not in ('completed', 'absent', 'canceled') or (p_status = 'completed' and v_link is null) then raise exception 'registration_level_test_result_invalid' using errcode = '22023'; end if;
  select attempt.* into v_attempt
  from public.ops_registration_level_tests attempt
  join public.ops_registration_subject_tracks track on track.id = attempt.track_id
  where attempt.id = p_attempt_id
  for update of attempt, track;
  if not found then raise exception 'registration_level_test_not_found' using errcode = 'P0002'; end if;
  select track.* into strict v_track
  from public.ops_registration_subject_tracks track
  where track.id = v_attempt.track_id;
  perform dashboard_private.assert_registration_mutation_access(v_track.task_id, v_track.id, 'complete_level_test');
  update public.ops_registration_level_tests set status = p_status, material_link = case when p_status = 'completed' then v_link else null end, completed_at = coalesce(completed_at, pg_catalog.now()), updated_at = pg_catalog.now() where id = p_attempt_id returning * into v_attempt;
  perform dashboard_private.write_registration_track_event(v_track.task_id, v_track.id, 'registration_level_test_result_saved', v_track.pipeline_status, v_track.pipeline_status, null, jsonb_build_object('attemptId', p_attempt_id, 'status', p_status));
  return jsonb_build_object('attemptId', v_attempt.id, 'trackId', v_track.id, 'status', v_attempt.status, 'materialLink', v_attempt.material_link);
end;
$$;
create function public.save_registration_level_test_result_v1(
  p_attempt_id uuid,
  p_status text,
  p_material_link text,
  p_request_key text
) returns jsonb language sql security invoker set search_path = '' as $$ select dashboard_private.save_registration_level_test_result_impl($1, $2, $3, $4); $$;
revoke execute on function public.save_registration_level_test_result_v1(uuid, text, text, text) from public, anon;
grant execute on function public.save_registration_level_test_result_v1(uuid, text, text, text) to authenticated;
create function dashboard_private.save_registration_consultation_details_impl(p_consultation_id uuid, p_status text, p_outcome text, p_request_key text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_consultation public.ops_registration_consultations%rowtype; v_track public.ops_registration_subject_tracks%rowtype; begin
  if auth.uid() is null then raise exception 'registration_access_denied' using errcode = '42501'; end if;
  if nullif(pg_catalog.btrim(p_request_key), '') is null or p_status not in ('waiting', 'scheduled', 'completed', 'canceled') or (p_status = 'completed' and p_outcome not in ('enrollment', 'waiting', 'not_registered')) or (p_status <> 'completed' and p_outcome is not null) then raise exception 'registration_consultation_details_invalid' using errcode = '22023'; end if;
  select consultation.* into v_consultation
  from public.ops_registration_consultations consultation
  join public.ops_registration_subject_tracks track on track.id = consultation.track_id
  where consultation.id = p_consultation_id
  for update of consultation, track;
  if not found then raise exception 'registration_consultation_not_found' using errcode = 'P0002'; end if;
  select track.* into strict v_track
  from public.ops_registration_subject_tracks track
  where track.id = v_consultation.track_id;
  perform dashboard_private.assert_registration_mutation_access(v_track.task_id, v_track.id, 'complete_consultation');
  update public.ops_registration_consultations set status = p_status, outcome = p_outcome, completed_at = case when p_status = 'completed' then coalesce(completed_at, pg_catalog.now()) else null end, updated_at = pg_catalog.now() where id = p_consultation_id returning * into v_consultation;
  perform dashboard_private.write_registration_track_event(v_track.task_id, v_track.id, 'registration_consultation_details_saved', v_track.pipeline_status, v_track.pipeline_status, null, jsonb_build_object('consultationId', p_consultation_id, 'status', p_status, 'outcome', p_outcome));
  return jsonb_build_object('consultationId', v_consultation.id, 'trackId', v_track.id, 'status', v_consultation.status, 'outcome', v_consultation.outcome);
end;
$$;
create function public.save_registration_consultation_details_v1(
  p_consultation_id uuid,
  p_status text,
  p_outcome text,
  p_request_key text
) returns jsonb language sql security invoker set search_path = '' as $$ select dashboard_private.save_registration_consultation_details_impl($1, $2, $3, $4); $$;
revoke execute on function public.save_registration_consultation_details_v1(uuid, text, text, text) from public, anon;
grant execute on function public.save_registration_consultation_details_v1(uuid, text, text, text) to authenticated;
commit;
begin;
set local lock_timeout = '5s';
alter table public.ops_registration_subject_tracks
  add column if not exists waiting_detail_kind text,
  add column if not exists waiting_detail_class_id uuid references public.classes(id) on delete restrict,
  add column if not exists waiting_detail_retake_decision text;
alter table public.ops_registration_subject_tracks
  add constraint ops_registration_subject_tracks_waiting_detail_kind_check
  check (waiting_detail_kind is null or waiting_detail_kind in ('current_class', 'current_term_opening', 'next_term_opening')) not valid,
  add constraint ops_registration_subject_tracks_waiting_detail_retake_check
  check (waiting_detail_retake_decision is null or waiting_detail_retake_decision in ('required', 'not_required')) not valid,
  add constraint ops_registration_subject_tracks_waiting_detail_class_check
  check ((waiting_detail_kind = 'current_class') = (waiting_detail_class_id is not null)) not valid;
create or replace view public.ops_registration_subject_track_summaries
with (security_invoker = true)
as
select
  track.id,
  track.task_id,
  track.subject,
  track.pipeline_status,
  track.director_profile_id,
  track.director_assignment_source,
  track.director_assignment_rule_key,
  track.waiting_kind,
  track.level_test_retake_decision,
  track.migration_review_required,
  track.stage_entered_at,
  track.updated_at,
  active_visit.scheduled_at as visit_scheduled_at,
  active_visit.place as visit_place,
  active_phone.ready_at as phone_ready_at,
  active_phone.ready_source as phone_ready_source,
  track.workflow_status,
  track.workflow_revision,
  track.workflow_status_entered_at,
  track.waiting_detail_kind,
  track.waiting_detail_class_id,
  track.waiting_detail_retake_decision
from public.ops_registration_subject_tracks track
left join lateral (
  select appointment.scheduled_at, appointment.place
  from public.ops_registration_consultations consultation
  join public.ops_registration_appointments appointment on appointment.id = consultation.appointment_id
  where consultation.track_id = track.id
    and consultation.mode = 'visit'
    and consultation.status = 'scheduled'
    and appointment.kind = 'visit_consultation'
    and appointment.status = 'scheduled'
  order by consultation.created_at desc, consultation.id desc
  limit 1
) active_visit on true
left join lateral (
  select consultation.ready_at, consultation.ready_source
  from public.ops_registration_consultations consultation
  where consultation.track_id = track.id
    and consultation.mode = 'phone'
    and consultation.status = 'waiting'
  order by consultation.created_at desc, consultation.id desc
  limit 1
) active_phone on true;
create function dashboard_private.save_registration_waiting_details_impl(
  p_track_id uuid,
  p_waiting_kind text,
  p_class_id uuid,
  p_retake_decision text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_request_key text := nullif(pg_catalog.btrim(p_request_key), '');
  v_track public.ops_registration_subject_tracks%rowtype;
  v_fingerprint jsonb;
  v_saved_fingerprint jsonb;
  v_response jsonb;
begin
  if v_actor_id is null or v_request_key is null then raise exception 'registration_access_denied' using errcode = '42501'; end if;
  if p_waiting_kind not in ('current_class', 'current_term_opening', 'next_term_opening')
    or (p_waiting_kind = 'current_class') is distinct from (p_class_id is not null)
    or p_retake_decision not in ('required', 'not_required') then raise exception 'registration_waiting_details_invalid' using errcode = '22023'; end if;
  v_fingerprint := pg_catalog.jsonb_build_object('trackId', p_track_id, 'waitingKind', p_waiting_kind, 'classId', p_class_id, 'retakeDecision', p_retake_decision);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor_id::text || ':' || v_request_key, 0));
  select mutation.target_fingerprint, mutation.response_payload into v_saved_fingerprint, v_response from dashboard_private.ops_registration_mutations mutation where mutation.actor_id = v_actor_id and mutation.request_key = v_request_key;
  if found then
    if v_saved_fingerprint is distinct from v_fingerprint then raise exception 'registration_mutation_request_conflict' using errcode = '40001'; end if;
    return v_response;
  end if;
  select track.* into v_track from public.ops_registration_subject_tracks track join public.ops_tasks task on task.id = track.task_id where track.id = p_track_id and task.type = 'registration' for update of track;
  if not found then raise exception 'registration_access_denied' using errcode = '42501'; end if;
  perform dashboard_private.assert_registration_mutation_access(v_track.task_id, v_track.id, 'change_waiting_kind');
  update public.ops_registration_subject_tracks set waiting_detail_kind = p_waiting_kind, waiting_detail_class_id = p_class_id, waiting_detail_retake_decision = p_retake_decision, updated_at = pg_catalog.now() where id = p_track_id;
  perform dashboard_private.write_registration_track_event(v_track.task_id, p_track_id, 'registration_waiting_details_saved', v_track.pipeline_status, v_track.pipeline_status, null, pg_catalog.jsonb_build_object('waitingKind', p_waiting_kind, 'classId', p_class_id, 'retakeDecision', p_retake_decision));
  v_response := pg_catalog.jsonb_build_object('trackId', p_track_id, 'waitingKind', p_waiting_kind, 'classId', p_class_id, 'retakeDecision', p_retake_decision);
  insert into dashboard_private.ops_registration_mutations(actor_id, request_key, task_id, mutation_type, target_fingerprint, response_payload) values (v_actor_id, v_request_key, v_track.task_id, 'save_registration_waiting_details', v_fingerprint, v_response);
  return v_response;
end;
$$;
create function public.save_registration_waiting_details_v1(
  p_track_id uuid,
  p_waiting_kind text,
  p_class_id uuid,
  p_retake_decision text,
  p_request_key text
)
returns jsonb language sql security invoker set search_path = '' as $$
  select dashboard_private.save_registration_waiting_details_impl($1, $2, $3, $4, $5);
$$;
revoke execute on function public.save_registration_waiting_details_v1(uuid, text, uuid, text, text) from public, anon;
grant execute on function public.save_registration_waiting_details_v1(uuid, text, uuid, text, text) to authenticated;
commit;
begin;
set local lock_timeout = '5s';
alter table public.ops_registration_subject_tracks
  add column if not exists enrollment_detail_rows jsonb not null default '[]'::jsonb,
  add constraint ops_registration_subject_tracks_enrollment_detail_rows_array_check
    check (pg_catalog.jsonb_typeof(enrollment_detail_rows) = 'array') not valid;
create function dashboard_private.save_registration_enrollment_details_impl(
  p_track_id uuid,
  p_rows jsonb,
  p_request_key text
)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_request_key text := nullif(pg_catalog.btrim(p_request_key), '');
  v_track public.ops_registration_subject_tracks%rowtype;
  v_fingerprint jsonb;
  v_saved_fingerprint jsonb;
  v_response jsonb;
begin
  if v_actor_id is null or v_request_key is null or p_rows is null or pg_catalog.jsonb_typeof(p_rows) <> 'array' then
    raise exception 'registration_enrollment_details_invalid' using errcode = '22023';
  end if;
  v_fingerprint := pg_catalog.jsonb_build_object('trackId', p_track_id, 'rows', p_rows);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor_id::text || ':' || v_request_key, 0));
  select mutation.target_fingerprint, mutation.response_payload into v_saved_fingerprint, v_response
  from dashboard_private.ops_registration_mutations mutation where mutation.actor_id = v_actor_id and mutation.request_key = v_request_key;
  if found then
    if v_saved_fingerprint is distinct from v_fingerprint then raise exception 'registration_mutation_request_conflict' using errcode = '40001'; end if;
    return v_response;
  end if;
  select track.* into v_track from public.ops_registration_subject_tracks track join public.ops_tasks task on task.id = track.task_id
  where track.id = p_track_id and task.type = 'registration' for update of track;
  if not found then raise exception 'registration_access_denied' using errcode = '42501'; end if;
  perform dashboard_private.assert_registration_mutation_access(v_track.task_id, v_track.id, 'save_enrollment_rows');
  update public.ops_registration_subject_tracks set enrollment_detail_rows = p_rows, updated_at = pg_catalog.now() where id = p_track_id;
  perform dashboard_private.write_registration_track_event(v_track.task_id, p_track_id, 'registration_enrollment_details_saved', v_track.pipeline_status, v_track.pipeline_status, null, pg_catalog.jsonb_build_object('rowCount', pg_catalog.jsonb_array_length(p_rows)));
  v_response := pg_catalog.jsonb_build_object('trackId', p_track_id, 'rows', p_rows);
  insert into dashboard_private.ops_registration_mutations(actor_id, request_key, task_id, mutation_type, target_fingerprint, response_payload)
  values (v_actor_id, v_request_key, v_track.task_id, 'save_registration_enrollment_details', v_fingerprint, v_response);
  return v_response;
end;
$$;
create function public.save_registration_enrollment_details_v1(p_track_id uuid, p_rows jsonb, p_request_key text)
returns jsonb language sql security invoker set search_path = '' as $$
  select dashboard_private.save_registration_enrollment_details_impl($1, $2, $3);
$$;
revoke execute on function public.save_registration_enrollment_details_v1(uuid, jsonb, text) from public, anon;
grant execute on function public.save_registration_enrollment_details_v1(uuid, jsonb, text) to authenticated;
commit;
begin;
-- A withdrawal task represents the selected class/subject. Other live subjects
-- remain enrolled or waitlisted, and the student becomes withdrawn only after
-- the selected class was their final live roster or registration claim.
create or replace function dashboard_private.complete_ops_withdrawal_roster_transition_impl(
  p_task_id uuid,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_request_key text := nullif(pg_catalog.btrim(p_request_key), '');
  v_task public.ops_tasks%rowtype;
  v_detail public.ops_withdrawal_details%rowtype;
  v_pre_student public.students%rowtype;
  v_student public.students%rowtype;
  v_class public.classes%rowtype;
  v_claim public.ops_registration_enrollments%rowtype;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_student_id uuid;
  v_source_class_id uuid;
  v_pre_parent_ids uuid[] := array[]::uuid[];
  v_current_parent_ids uuid[] := array[]::uuid[];
  v_affected_class_ids uuid[] := array[]::uuid[];
  v_released_enrollment_ids uuid[] := array[]::uuid[];
  v_canceled_waitlist_ids uuid[] := array[]::uuid[];
  v_recomputed_parent_ids uuid[] := array[]::uuid[];
  v_name_key text;
  v_parent_phone_key text;
  v_claim_id uuid;
  v_claim_count integer;
  v_parent_id uuid;
  v_remaining_live_roster_count integer := 0;
  v_next_student_status text;
  v_target_fingerprint jsonb;
  v_receipt_matches boolean;
  v_receipt_found boolean := false;
  v_response jsonb;
begin
  if v_actor_id is null or p_task_id is null then
    raise exception 'registration_access_denied' using errcode = '42501';
  end if;
  if v_request_key is null then
    raise exception 'request_key_required' using errcode = '22023';
  end if;

  -- withdrawal_preliminary_source
  select task.student_id, task.class_id
  into v_student_id, v_source_class_id
  from public.ops_tasks task
  where task.id = p_task_id
    and task.type = 'withdrawal';
  if v_student_id is null or v_source_class_id is null then
    raise exception 'ops_withdrawal_management_link_required' using errcode = '22023';
  end if;
  select student.*
  into v_pre_student
  from public.students student
  where student.id = v_student_id;
  if not found then
    raise exception 'registration_student_not_found' using errcode = 'P0002';
  end if;
  select coalesce(
    pg_catalog.array_agg(distinct track.task_id order by track.task_id),
    array[]::uuid[]
  )
  into v_pre_parent_ids
  from public.ops_registration_enrollments enrollment
  join public.ops_registration_subject_tracks track on track.id = enrollment.track_id
  where enrollment.student_id = v_student_id
    and enrollment.class_id = v_source_class_id
    and enrollment.roster_active;

  -- verification_checkpoint_withdrawal_after_parent_snapshot
  perform dashboard_private.await_registration_verification_checkpoint(
    'withdrawal_after_parent_snapshot', p_task_id, v_student_id
  );

  v_target_fingerprint := pg_catalog.jsonb_build_object(
    'taskId', p_task_id,
    'studentId', v_student_id,
    'sourceClassId', v_source_class_id
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor_id::text || ':' || v_request_key, 0)
  );

  -- withdrawal_parent_task_locks
  perform 1
  from public.ops_tasks task
  where task.id = p_task_id
    or task.id = any(v_pre_parent_ids)
  order by task.id
  for update;
  select task.*
  into v_task
  from public.ops_tasks task
  where task.id = p_task_id
    and task.type = 'withdrawal';
  if not found then
    raise exception 'registration_access_denied' using errcode = '42501';
  end if;
  select detail.*
  into v_detail
  from public.ops_withdrawal_details detail
  where detail.task_id = p_task_id
  for update;
  if not found then
    raise exception 'ops_withdrawal_detail_required' using errcode = '23514';
  end if;

  -- withdrawal_track_locks
  perform 1
  from public.ops_registration_subject_tracks track
  where track.task_id = any(v_pre_parent_ids)
  order by track.id
  for update;

  -- withdrawal_identity_lock
  v_name_key := pg_catalog.lower(
    pg_catalog.regexp_replace(coalesce(v_pre_student.name, ''), '\s+', '', 'g')
  );
  v_parent_phone_key := pg_catalog.regexp_replace(
    coalesce(v_pre_student.parent_contact, ''), '\D+', '', 'g'
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'registration-student:' || v_name_key || ':' || v_parent_phone_key,
      0
    )
  );

  -- withdrawal_student_lock
  select student.*
  into v_student
  from public.students student
  where student.id = v_student_id
  for update;
  if not found
    or v_task.student_id is distinct from v_student_id
    or v_task.class_id is distinct from v_source_class_id
    or pg_catalog.lower(
      pg_catalog.regexp_replace(coalesce(v_student.name, ''), '\s+', '', 'g')
    ) is distinct from v_name_key
    or pg_catalog.regexp_replace(
      coalesce(v_student.parent_contact, ''), '\D+', '', 'g'
    ) is distinct from v_parent_phone_key
  then
    raise exception 'registration_workflow_retry_required' using errcode = '40001';
  end if;

  -- withdrawal_parent_rescan
  select coalesce(
    pg_catalog.array_agg(distinct track.task_id order by track.task_id),
    array[]::uuid[]
  )
  into v_current_parent_ids
  from public.ops_registration_enrollments enrollment
  join public.ops_registration_subject_tracks track on track.id = enrollment.track_id
  where enrollment.student_id = v_student_id
    and enrollment.class_id = v_source_class_id
    and enrollment.roster_active;
  if v_current_parent_ids is distinct from v_pre_parent_ids then
    raise exception 'registration_workflow_retry_required' using errcode = '40001';
  end if;

  -- withdrawal_batch_locks
  perform 1
  from public.ops_registration_admission_batches batch
  where batch.task_id = any(v_current_parent_ids)
  order by batch.id
  for update;

  -- withdrawal_claim_locks
  perform 1
  from public.ops_registration_enrollments enrollment
  where enrollment.student_id = v_student_id
    and enrollment.class_id = v_source_class_id
    and enrollment.roster_active
  order by enrollment.id
  for update;

  v_affected_class_ids := array[v_source_class_id];

  -- withdrawal_class_locks
  select class.*
  into v_class
  from public.classes class
  where class.id = v_source_class_id
  for update;
  if not found then
    raise exception 'registration_class_not_found' using errcode = 'P0002';
  end if;

  perform dashboard_private.assert_registration_mutation_access(
    p_task_id, null, 'complete_withdrawal_roster_transition'
  );

  -- withdrawal_receipt_lookup
  select
    mutation.response_payload,
    mutation.task_id = p_task_id
      and mutation.mutation_type = 'complete_withdrawal_roster_transition'
      and mutation.target_fingerprint = v_target_fingerprint
  into v_response, v_receipt_matches
  from dashboard_private.ops_registration_mutations mutation
  where mutation.actor_id = v_actor_id
    and mutation.request_key = v_request_key;
  v_receipt_found := found;
  if v_receipt_found and not v_receipt_matches then
    raise exception 'idempotency_key_reused' using errcode = '22023';
  end if;
  if v_receipt_found then return v_response; end if;

  -- withdrawal_mutable_state_check
  if v_task.status in ('done', 'canceled')
    or v_detail.timetable_roster_updated
  then
    raise exception 'ops_withdrawal_completion_state_conflict' using errcode = '40001';
  end if;
  if not v_detail.makeedu_withdrawal_done
    or not v_detail.fee_processed
    or not v_detail.textbook_fee_processed
  then
    raise exception 'ops_withdrawal_checklist_incomplete' using errcode = '40001';
  end if;
  if v_student.status = '퇴원' then
    raise exception 'registration_student_reactivation_required' using errcode = '40001';
  end if;
  if pg_catalog.jsonb_typeof(coalesce(v_student.class_ids, '[]'::jsonb)) <> 'array'
    or pg_catalog.jsonb_typeof(coalesce(v_student.waitlist_class_ids, '[]'::jsonb)) <> 'array'
  then
    raise exception 'registration_roster_projection_invalid' using errcode = '23514';
  end if;
  if not (coalesce(v_student.class_ids, '[]'::jsonb) ? v_source_class_id::text)
    or coalesce(v_student.waitlist_class_ids, '[]'::jsonb) ? v_source_class_id::text
  then
    raise exception 'ops_withdrawal_source_roster_required' using errcode = '40001';
  end if;
  if exists (
    select 1
    from public.ops_registration_enrollments enrollment
    left join public.ops_registration_admission_batches batch
      on batch.id = enrollment.admission_batch_id
    where enrollment.student_id = v_student_id
      and enrollment.class_id = v_source_class_id
      and enrollment.roster_active
      and (
        enrollment.status = 'planned'
        or batch.status not in ('completed', 'canceled')
      )
  ) then
    raise exception 'registration_open_admission_batch' using errcode = '40001';
  end if;

  select
    pg_catalog.count(*),
    (pg_catalog.array_agg(enrollment.id order by enrollment.id))[1]
  into v_claim_count, v_claim_id
  from public.ops_registration_enrollments enrollment
  where enrollment.student_id = v_student_id
    and enrollment.class_id = v_source_class_id
    and enrollment.roster_active;
  if v_claim_count > 1 then
    raise exception 'registration_student_class_claim_invariant' using errcode = '23514';
  end if;
  if v_claim_count = 1 then
    select enrollment.*
    into v_claim
    from public.ops_registration_enrollments enrollment
    where enrollment.id = v_claim_id;
    if v_claim.status <> 'enrolled' then
      raise exception 'registration_student_class_claim_invariant' using errcode = '23514';
    end if;
  else
    v_claim_id := null;
  end if;

  -- verification_checkpoint_withdrawal_before_status_flip
  perform dashboard_private.await_registration_verification_checkpoint(
    'withdrawal_before_status_flip', p_task_id, v_student_id
  );

  perform dashboard_private.apply_student_class_roster_mode(
    v_student_id,
    v_source_class_id,
    'removed',
    'enrolled',
    v_claim_id,
    'withdrawal_completed',
    v_actor_id
  );

  if v_claim_id is not null then
    update public.ops_registration_enrollments enrollment
    set
      status = 'enrolled',
      roster_active = false,
      roster_released_at = pg_catalog.now(),
      roster_release_reason = 'withdrawal_completed',
      roster_release_source_task_id = p_task_id,
      roster_release_kind = 'withdrawal',
      updated_at = pg_catalog.now()
    where enrollment.id = v_claim_id
      and enrollment.status = 'enrolled'
      and enrollment.roster_active;
    if not found then
      raise exception 'registration_student_class_claim_invariant' using errcode = '23514';
    end if;
    v_released_enrollment_ids := pg_catalog.array_append(
      v_released_enrollment_ids, v_claim_id
    );
    select track.*
    into v_track
    from public.ops_registration_subject_tracks track
    where track.id = v_claim.track_id;
    if not found then
      raise exception 'registration_student_class_claim_invariant' using errcode = '23514';
    end if;
    perform dashboard_private.write_registration_track_event(
      v_track.task_id,
      v_track.id,
      'registration_enrollment_roster_released',
      v_track.pipeline_status,
      v_track.pipeline_status,
      'withdrawal_completed',
      pg_catalog.jsonb_build_object(
        'enrollmentId', v_claim_id,
        'sourceTaskId', p_task_id,
        'releaseKind', 'withdrawal',
        'enrollmentSnapshot', pg_catalog.jsonb_build_object(
          'id', v_claim.id,
          'classId', v_claim.class_id,
          'textbookId', v_claim.textbook_id,
          'admissionBatchId', v_claim.admission_batch_id,
          'classStartDate', v_claim.class_start_date,
          'classStartSessionKey', v_claim.class_start_session_key,
          'classStartSession', v_claim.class_start_session,
          'status', v_claim.status,
          'sortOrder', v_claim.sort_order
        )
      )
    );
    v_recomputed_parent_ids := pg_catalog.array_append(
      v_recomputed_parent_ids, v_track.task_id
    );
  end if;

  select student.*
  into v_student
  from public.students student
  where student.id = v_student_id;
  if pg_catalog.jsonb_typeof(coalesce(v_student.class_ids, '[]'::jsonb)) <> 'array'
    or pg_catalog.jsonb_typeof(coalesce(v_student.waitlist_class_ids, '[]'::jsonb)) <> 'array'
  then
    raise exception 'registration_roster_projection_invalid' using errcode = '23514';
  end if;
  v_remaining_live_roster_count :=
    pg_catalog.jsonb_array_length(coalesce(v_student.class_ids, '[]'::jsonb))
    + pg_catalog.jsonb_array_length(coalesce(v_student.waitlist_class_ids, '[]'::jsonb))
    + (
      select pg_catalog.count(*)::integer
      from public.ops_registration_enrollments enrollment
      where enrollment.student_id = v_student_id
        and enrollment.roster_active
    );
  v_next_student_status := case when v_remaining_live_roster_count = 0 then '퇴원' else '재원' end;

  if v_next_student_status = '퇴원' then
    update public.students
    set status = '퇴원'
    where id = v_student_id
      and status = '재원';
    if not found then
      raise exception 'ops_withdrawal_completion_state_conflict' using errcode = '40001';
    end if;
  elsif v_student.status <> '재원' then
    raise exception 'ops_withdrawal_completion_state_conflict' using errcode = '40001';
  end if;

  update public.ops_withdrawal_details
  set
    timetable_roster_updated = true,
    updated_at = pg_catalog.now()
  where task_id = p_task_id
    and not timetable_roster_updated;
  if not found then
    raise exception 'ops_withdrawal_completion_state_conflict' using errcode = '40001';
  end if;
  update public.ops_tasks
  set
    status = 'done',
    completed_at = pg_catalog.now(),
    updated_at = pg_catalog.now()
  where id = p_task_id
    and type = 'withdrawal'
    and status not in ('done', 'canceled');
  if not found then
    raise exception 'ops_withdrawal_completion_state_conflict' using errcode = '40001';
  end if;

  insert into public.ops_task_events(
    task_id, actor_id, event_type, field_name, before_value, after_value
  ) values
    (p_task_id, v_actor_id, 'auto_checked', '시간표 명단 변경', '', '완료'),
    (
      p_task_id, v_actor_id, 'auto_synced', '수업명단', '',
      coalesce(v_class.name, v_task.class_name, v_source_class_id::text)
        || ' 제거 · withdrawal_completed'
    ),
    (
      p_task_id, v_actor_id, 'auto_synced', '학생 상태', '재원',
      v_next_student_status
    );

  select coalesce(
    pg_catalog.array_agg(distinct parent_id order by parent_id),
    array[]::uuid[]
  )
  into v_recomputed_parent_ids
  from pg_catalog.unnest(v_recomputed_parent_ids) parent_id;
  foreach v_parent_id in array v_recomputed_parent_ids
  loop
    perform dashboard_private.recompute_registration_parent(v_parent_id);
  end loop;

  v_response := pg_catalog.jsonb_build_object(
    'taskId', p_task_id,
    'studentId', v_student_id,
    'sourceClassId', v_source_class_id,
    'affectedClassIds', pg_catalog.to_jsonb(v_affected_class_ids),
    'releasedEnrollmentIds', pg_catalog.to_jsonb(v_released_enrollment_ids),
    'canceledWaitlistEnrollmentIds', pg_catalog.to_jsonb(v_canceled_waitlist_ids),
    'studentStatus', v_next_student_status,
    'taskStatus', 'done',
    'timetableRosterUpdated', true
  );
  insert into dashboard_private.ops_registration_mutations(
    actor_id, request_key, task_id, mutation_type, target_fingerprint, response_payload
  ) values (
    v_actor_id, v_request_key, p_task_id,
    'complete_withdrawal_roster_transition', v_target_fingerprint, v_response
  );
  return v_response;
end;
$$;
