create or replace function public.get_registration_notification_processing_readiness_v1()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_registration_runtime_version integer := 0;
  v_adapters_runtime_version integer := 0;
  v_worker_heartbeat jsonb := null;
  v_watchdog_heartbeat jsonb := null;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'notification_access_denied' using errcode = '42501';
  end if;

  if pg_catalog.to_regprocedure(
    'public.registration_appointment_reminders_runtime_version()'
  ) is not null then
    begin
      execute 'select public.registration_appointment_reminders_runtime_version()'
        into v_registration_runtime_version;
    exception
      when others then
        v_registration_runtime_version := 0;
    end;
  end if;

  if pg_catalog.to_regprocedure(
    'public.notification_workflow_adapters_runtime_version()'
  ) is not null then
    begin
      execute 'select public.notification_workflow_adapters_runtime_version()'
        into v_adapters_runtime_version;
    exception
      when others then
        v_adapters_runtime_version := 0;
    end;
  end if;

  if pg_catalog.to_regclass(
    'dashboard_private.notification_worker_heartbeats'
  ) is not null then
    execute $query$
      select pg_catalog.jsonb_build_object(
        'kind', 'worker',
        'phase', heartbeat.phase,
        'created_at', heartbeat.created_at
      )
      from dashboard_private.notification_worker_heartbeats heartbeat
      where heartbeat.worker_id = 'notification-worker-route-v1'
      order by heartbeat.created_at desc, heartbeat.id desc
      limit 1
    $query$ into v_worker_heartbeat;
  end if;

  if pg_catalog.to_regclass(
    'dashboard_private.notification_watchdog_heartbeats'
  ) is not null then
    execute $query$
      select pg_catalog.jsonb_build_object(
        'kind', 'watchdog',
        'phase', heartbeat.phase,
        'created_at', heartbeat.created_at
      )
      from dashboard_private.notification_watchdog_heartbeats heartbeat
      order by heartbeat.created_at desc, heartbeat.id desc
      limit 1
    $query$ into v_watchdog_heartbeat;
  end if;

  return pg_catalog.jsonb_build_object(
    'registration_runtime_version', case
      when v_registration_runtime_version = 1 then 1 else 0 end,
    'adapters_runtime_version', case
      when v_adapters_runtime_version = 1 then 1 else 0 end,
    'worker_heartbeat', v_worker_heartbeat,
    'watchdog_heartbeat', v_watchdog_heartbeat
  );
end;
$$;
revoke all on function public.get_registration_notification_processing_readiness_v1()
  from public, anon, authenticated;
grant execute on function public.get_registration_notification_processing_readiness_v1()
  to service_role;
begin;
set local lock_timeout = '5s';
set local statement_timeout = '30s';
create or replace function dashboard_private.registration_render_fixed_template_v2(
  p_template text,
  p_payload jsonb,
  p_allowed_variables jsonb
)
returns text
language plpgsql
immutable
strict
security definer
set search_path = ''
as $$
declare
  v_rendered text := p_template;
  v_variable record;
  v_match text[];
  v_value text;
begin
  if pg_catalog.jsonb_typeof(p_payload) <> 'object'
    or pg_catalog.jsonb_typeof(p_allowed_variables) <> 'array'
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_allowed_variables) variable(item)
      where pg_catalog.jsonb_typeof(variable.item) <> 'object'
        or coalesce(variable.item ->> 'key', '') !~ '^[a-z][a-z0-9_]{0,63}$'
        or nullif(variable.item ->> 'token', '') is null
        or (variable.item ->> 'token') ~ '[{}[:cntrl:]]'
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_allowed_variables)
        with ordinality left_variable(item, ordinality)
      join pg_catalog.jsonb_array_elements(p_allowed_variables)
        with ordinality right_variable(item, ordinality)
        on left_variable.ordinality < right_variable.ordinality
      where left_variable.item ->> 'key' = right_variable.item ->> 'key'
        or left_variable.item ->> 'token' = right_variable.item ->> 'token'
        or left_variable.item ->> 'key' = right_variable.item ->> 'token'
        or left_variable.item ->> 'token' = right_variable.item ->> 'key'
    )
  then
    raise exception 'registration_notification_template_allowlist_invalid'
      using errcode = '22023';
  end if;

  for v_match in
    select match_row
    from pg_catalog.regexp_matches(p_template, '\{([^{}]+)\}', 'g') match_row
  loop
    if not exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_allowed_variables) variable(item)
      where variable.item ->> 'key' = v_match[1]
        or variable.item ->> 'token' = v_match[1]
    ) then
      raise exception 'registration_notification_template_token_not_allowed:%', v_match[1]
        using errcode = '22023';
    end if;
  end loop;

  for v_variable in
    select
      variable.item ->> 'key' as key,
      variable.item ->> 'token' as token
    from pg_catalog.jsonb_array_elements(p_allowed_variables) variable(item)
    order by variable.item ->> 'key'
  loop
    if pg_catalog.jsonb_typeof(p_payload -> v_variable.key) = 'array' then
      select coalesce(
        pg_catalog.string_agg(value.item #>> '{}', ' · ' order by value.ordinality),
        ''
      )
      into v_value
      from pg_catalog.jsonb_array_elements(p_payload -> v_variable.key)
        with ordinality value(item, ordinality);
    else
      v_value := coalesce(p_payload ->> v_variable.key, '');
    end if;
    v_rendered := pg_catalog.replace(
      v_rendered,
      '{' || v_variable.key || '}',
      v_value
    );
    v_rendered := pg_catalog.replace(
      v_rendered,
      '{' || v_variable.token || '}',
      v_value
    );
  end loop;
  return v_rendered;
end;
$$;
