create policy profiles_select_v2 on public.profiles for select to authenticated
using (
  id = (select auth.uid())
  or lower(email) = lower(coalesce((select auth.jwt()) ->> 'email', ''))
  or (
    lower(coalesce((select auth.jwt()) ->> 'email', '')) like '%@tipsedu.co.kr'
    and lower(login_id) = split_part(lower(coalesce((select auth.jwt()) ->> 'email', '')), '@', 1)
  )
  or (select public.current_dashboard_role()) in ('admin', 'staff')
);
create policy profiles_insert_v2 on public.profiles for insert to authenticated
with check (
  (select public.current_dashboard_role()) in ('admin', 'staff')
  or (id = (select auth.uid()) and role = 'viewer')
);
create policy profiles_update_v2 on public.profiles for update to authenticated
using (id = (select auth.uid()) or (select public.current_dashboard_role()) in ('admin', 'staff'))
with check (id = (select auth.uid()) or (select public.current_dashboard_role()) in ('admin', 'staff'));
create policy profiles_delete_v2 on public.profiles for delete to authenticated
using ((select public.current_dashboard_role()) in ('admin', 'staff'));
drop policy if exists ops_tasks_select on public.ops_tasks;
drop policy if exists ops_tasks_insert on public.ops_tasks;
drop policy if exists ops_tasks_update on public.ops_tasks;
drop policy if exists ops_tasks_delete on public.ops_tasks;
create policy ops_tasks_select_v2 on public.ops_tasks for select to authenticated
using (
  (select public.current_dashboard_role()) in ('admin', 'staff', 'assistant')
  or requested_by = (select auth.uid())
  or assignee_id = (select auth.uid())
  or secondary_assignee_id = (select auth.uid())
  or dashboard_private.is_ops_word_retest_teacher(id)
);
create policy ops_tasks_insert_v2 on public.ops_tasks for insert to authenticated
with check (
  type <> 'registration'
  and (
    requested_by is null
    or requested_by = (select auth.uid())
    or (select public.current_dashboard_role()) in ('admin', 'staff', 'assistant')
  )
);
create policy ops_tasks_update_v2 on public.ops_tasks for update to authenticated
using (
  not dashboard_private.registration_task_has_subject_tracks(id)
  and (
    (select public.current_dashboard_role()) in ('admin', 'staff', 'assistant')
    or requested_by = (select auth.uid())
    or assignee_id = (select auth.uid())
    or secondary_assignee_id = (select auth.uid())
    or dashboard_private.is_ops_word_retest_teacher(id)
  )
)
with check (
  not dashboard_private.registration_task_has_subject_tracks(id)
  and (
    (select public.current_dashboard_role()) in ('admin', 'staff', 'assistant')
    or requested_by = (select auth.uid())
    or assignee_id = (select auth.uid())
    or secondary_assignee_id = (select auth.uid())
    or dashboard_private.is_ops_word_retest_teacher(id)
  )
);
create policy ops_tasks_delete_v2 on public.ops_tasks for delete to authenticated
using (
  not dashboard_private.registration_task_has_subject_tracks(id)
  and (
    (select public.current_dashboard_role()) = 'admin'
    or (
      type = 'general'
      and (
        requested_by = (select auth.uid())
        or assignee_id = (select auth.uid())
        or secondary_assignee_id = (select auth.uid())
      )
    )
    or (
      requested_by = (select auth.uid())
      and status not in ('done', 'canceled')
    )
    or (
      (select public.current_dashboard_role()) = 'staff'
      and (type = 'general' or status not in ('done', 'canceled'))
    )
  )
);
create or replace function dashboard_private.can_read_ops_task_v1(
  p_task_id uuid
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_role text := public.current_dashboard_role();
begin
  if p_task_id is null or v_actor is null then
    return false;
  end if;

  return exists (
    select 1
    from public.ops_tasks task
    where task.id = p_task_id
      and (
        v_role in ('admin', 'staff', 'assistant')
        or task.requested_by = v_actor
        or task.assignee_id = v_actor
        or task.secondary_assignee_id = v_actor
        or dashboard_private.is_ops_word_retest_teacher(task.id)
      )
  );
end;
$$;
alter function dashboard_private.can_read_ops_task_v1(uuid) owner to postgres;
revoke all on function dashboard_private.can_read_ops_task_v1(uuid)
  from public, anon, authenticated, service_role;
grant execute on function dashboard_private.can_read_ops_task_v1(uuid) to authenticated;
create or replace function dashboard_private.can_read_registration_track_v1(
  p_track_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (
      select dashboard_private.can_read_ops_task_v1(track.task_id)
      from public.ops_registration_subject_tracks track
      where track.id = p_track_id
    ),
    false
  );
$$;
alter function dashboard_private.can_read_registration_track_v1(uuid) owner to postgres;
revoke all on function dashboard_private.can_read_registration_track_v1(uuid)
  from public, anon, authenticated, service_role;
grant execute on function dashboard_private.can_read_registration_track_v1(uuid) to authenticated;
drop policy if exists ops_task_events_select on public.ops_task_events;
create policy ops_task_events_select_v2 on public.ops_task_events for select to authenticated
using (dashboard_private.can_read_ops_task_v1(task_id));
drop policy if exists ops_registration_subject_tracks_authenticated_select
  on public.ops_registration_subject_tracks;
create policy ops_registration_subject_tracks_select_v2
  on public.ops_registration_subject_tracks for select to authenticated
using (dashboard_private.can_read_ops_task_v1(task_id));
drop policy if exists ops_registration_appointments_authenticated_select
  on public.ops_registration_appointments;
create policy ops_registration_appointments_select_v2
  on public.ops_registration_appointments for select to authenticated
using (dashboard_private.can_read_ops_task_v1(task_id));
drop policy if exists ops_registration_admission_batches_authenticated_select
  on public.ops_registration_admission_batches;
create policy ops_registration_admission_batches_select_v2
  on public.ops_registration_admission_batches for select to authenticated
using (dashboard_private.can_read_ops_task_v1(task_id));
drop policy if exists ops_registration_details_select
  on public.ops_registration_details;
create policy ops_registration_details_select_v2
  on public.ops_registration_details for select to authenticated
using (dashboard_private.can_read_ops_task_v1(task_id));
drop policy if exists ops_registration_level_tests_authenticated_select
  on public.ops_registration_level_tests;
create policy ops_registration_level_tests_select_v2
  on public.ops_registration_level_tests for select to authenticated
using (dashboard_private.can_read_registration_track_v1(track_id));
drop policy if exists ops_registration_consultations_authenticated_select
  on public.ops_registration_consultations;
create policy ops_registration_consultations_select_v2
  on public.ops_registration_consultations for select to authenticated
using (dashboard_private.can_read_registration_track_v1(track_id));
drop policy if exists ops_registration_enrollments_authenticated_select
  on public.ops_registration_enrollments;
create policy ops_registration_enrollments_select_v2
  on public.ops_registration_enrollments for select to authenticated
using (dashboard_private.can_read_registration_track_v1(track_id));
begin;
create or replace function public.get_dashboard_summary_sources_v1()
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'classes', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(row_data) order by row_data.id)
      from (
        select
          class.id,
          class.name,
          class.subject,
          class.grade,
          class.teacher,
          class.room,
          class.schedule,
          class.status,
          class.start_date,
          class.end_date,
          class.student_ids,
          class.waitlist_ids,
          class.schedule_storage_mode
        from public.classes class
      ) row_data
    ), '[]'::jsonb),
    'students', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(row_data) order by row_data.id)
      from (
        select
          student.id,
          student.name,
          student.school,
          student.grade,
          student.status,
          student.class_ids,
          student.waitlist_class_ids
        from public.students student
      ) row_data
    ), '[]'::jsonb)
  );
$$;
create or replace function public.get_dashboard_conflict_sources_v1(
  p_date_from date,
  p_date_to date
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  result jsonb;
begin
  if p_date_from is null
    or p_date_to is null
    or p_date_to < p_date_from
    or (p_date_to - p_date_from) > 400 then
    raise exception 'dashboard_conflict_source_date_range_invalid'
      using errcode = '22023';
  end if;

  select pg_catalog.jsonb_build_object(
    'sessionDates', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.class_id, row_data.session_date, row_data.schedule_state
      )
      from (
        select
          session.class_id,
          session.session_date,
          session.schedule_state,
          session.storage_mode
        from public.list_dashboard_class_session_dates_v1(p_date_from, p_date_to) session
      ) row_data
    ), '[]'::jsonb),
    'classTerms', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.sort_order, row_data.academic_year, row_data.id
      )
      from (
        select
          term.id,
          term.academic_year,
          term.name,
          term.status,
          term.start_date,
          term.end_date,
          term.sort_order
        from public.class_terms term
      ) row_data
    ), '[]'::jsonb),
    'classGroups', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.sort_order, row_data.id
      )
      from (
        select
          sync_group.id,
          sync_group.term_id,
          sync_group.name,
          sync_group.subject,
          sync_group.sort_order,
          sync_group.is_default
        from public.class_schedule_sync_groups sync_group
      ) row_data
    ), '[]'::jsonb),
    'classGroupMembers', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.group_id, row_data.sort_order, row_data.class_id
      )
      from (
        select
          member.group_id,
          member.class_id,
          member.sort_order
        from public.class_schedule_sync_group_members member
      ) row_data
    ), '[]'::jsonb),
    'teacherCatalogs', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.name, row_data.id
      )
      from (
        select
          teacher.id,
          teacher.name,
          teacher.profile_id,
          teacher.subjects,
          teacher.is_visible
        from public.teacher_catalogs teacher
      ) row_data
    ), '[]'::jsonb),
    'classroomCatalogs', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.name, row_data.id
      )
      from (
        select
          classroom.id,
          classroom.name,
          classroom.subjects,
          classroom.is_visible
        from public.classroom_catalogs classroom
      ) row_data
    ), '[]'::jsonb),
    'academicSchools', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.name, row_data.id
      )
      from (
        select
          school.id,
          school.name,
          school.category
        from public.academic_schools school
      ) row_data
    ), '[]'::jsonb),
    'academicExamDays', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.exam_date, row_data.school_id, row_data.grade, row_data.subject, row_data.id
      )
      from (
        select
          exam_day.id,
          exam_day.school_id,
          exam_day.grade,
          exam_day.subject,
          exam_day.exam_date
        from public.academic_exam_days exam_day
      ) row_data
    ), '[]'::jsonb),
    'academicEventExamDetails', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.exam_date, row_data.academic_event_id, row_data.id
      )
      from (
        select
          detail.id,
          detail.academic_event_id,
          detail.school_id,
          detail.grade,
          detail.subject,
          detail.exam_date
        from public.academic_event_exam_details detail
      ) row_data
    ), '[]'::jsonb),
    'academicEvents', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(row_data)
        order by row_data.date, row_data.id
      )
      from (
        select
          event.id,
          event.title,
          event.date,
          event.type,
          event.school_id,
          event.grade,
          event.note
        from public.academic_events event
      ) row_data
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;
alter function public.get_dashboard_summary_sources_v1()
  owner to postgres;
alter function public.get_dashboard_conflict_sources_v1(date, date)
  owner to postgres;
revoke all on function public.get_dashboard_summary_sources_v1()
  from public, anon;
revoke all on function public.get_dashboard_conflict_sources_v1(date, date)
  from public, anon;
grant execute on function public.get_dashboard_summary_sources_v1()
  to authenticated;
grant execute on function public.get_dashboard_conflict_sources_v1(date, date)
  to authenticated;
comment on function public.get_dashboard_summary_sources_v1() is
  'Returns the RLS-visible class and student fields needed by the dashboard summary.';
comment on function public.get_dashboard_conflict_sources_v1(date, date) is
  'Returns the bounded RLS-visible source rows needed by dashboard conflict metrics.';
commit;
begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
alter table public.ops_registration_subject_tracks
  add column observation_return_workflow_status text,
  add column observation_attempt_count bigint not null default 0;
alter table public.ops_registration_subject_tracks
  drop constraint if exists ops_registration_subject_tracks_workflow_status_check,
  add constraint ops_registration_subject_tracks_workflow_status_check check (
    workflow_status in (
      'inquiry',
      'level_test_requested',
      'consultation_requested',
      'consultation_completed',
      'observation_requested',
      'observation_feedback_pending',
      'observation_completed',
      'waiting_current_class',
      'waiting_new_class',
      'waiting_next_opening',
      'enrollment_requested',
      'payment_in_progress',
      'registered',
      'not_registered',
      'inquiry_only'
    )
  ),
  add constraint ops_registration_subject_tracks_observation_return_workflow_status_check
    check (
      observation_return_workflow_status is null
      or observation_return_workflow_status in (
        'consultation_completed',
        'waiting_current_class',
        'waiting_new_class',
        'waiting_next_opening'
      )
    ),
  add constraint ops_registration_subject_tracks_observation_return_workflow_pair_check
    check (
      (workflow_status in (
        'observation_requested',
        'observation_feedback_pending',
        'observation_completed'
      )) = (observation_return_workflow_status is not null)
    ),
  add constraint ops_registration_subject_tracks_observation_attempt_count_check
    check (observation_attempt_count >= 0);
alter table public.ops_registration_appointments
  drop constraint if exists ops_registration_appointments_kind_check,
  add constraint ops_registration_appointments_kind_check
    check (kind in ('level_test', 'visit_consultation', 'observation_class'));
alter table public.classroom_catalogs
  add column campus text,
  add constraint classroom_catalogs_campus_check
    check (campus is null or campus in ('본관', '별관'));
create table dashboard_private.registration_observation_runtime_settings (
  singleton boolean primary key default true check (singleton),
  activation_version integer not null default 0 check (activation_version in (0, 1)),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles(id) on delete set null
);
create table public.ops_registration_observations (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.ops_tasks(id) on delete cascade,
  track_id uuid not null references public.ops_registration_subject_tracks(id) on delete cascade,
  appointment_id uuid not null unique references public.ops_registration_appointments(id) on delete restrict,
  class_id uuid not null references public.classes(id) on delete restrict,
  session_authority text not null,
  class_lesson_session_id uuid references public.class_lesson_sessions(id) on delete restrict,
  legacy_session_key text,
  session_date date not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  session_schedule_state text not null,
  session_source_revision bigint,
  legacy_session_source_hash text,
  source_revision jsonb not null,
  booking_fact_hash text not null,
  teacher_catalog_id uuid not null references public.teacher_catalogs(id) on delete restrict,
  teacher_profile_id uuid not null references public.profiles(id) on delete restrict,
  classroom_catalog_id uuid not null references public.classroom_catalogs(id) on delete restrict,
  subject text not null,
  class_name_snapshot text not null,
  teacher_name_snapshot text not null,
  classroom_name_snapshot text not null,
  campus text not null,
  textbook_snapshot jsonb not null default '[]'::jsonb,
  progress_snapshot text not null default '',
  status text not null default 'scheduled',
  attendance text,
  attendance_recorded_by uuid references public.profiles(id) on delete set null,
  attendance_recorded_at timestamptz,
  suitability_result text,
  feedback_reason text,
  feedback_submitted_by uuid references public.profiles(id) on delete set null,
  feedback_submitted_at timestamptz,
  feedback_revision bigint not null default 0,
  decision_kind text,
  decided_by uuid references public.profiles(id) on delete set null,
  decided_at timestamptz,
  revision bigint not null default 1,
  created_by uuid references public.profiles(id) on delete set null default auth.uid(),
  updated_by uuid references public.profiles(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint ops_registration_observations_session_authority_check
    check (session_authority in ('normalized', 'legacy')),
  constraint ops_registration_observations_session_source_columns_check
    check (
      (
        session_authority = 'normalized'
        and class_lesson_session_id is not null
        and session_source_revision is not null
        and legacy_session_key is null
        and legacy_session_source_hash is null
      )
      or
      (
        session_authority = 'legacy'
        and class_lesson_session_id is null
        and session_source_revision is null
        and nullif(pg_catalog.btrim(legacy_session_key), '') is not null
        and nullif(pg_catalog.btrim(legacy_session_source_hash), '') is not null
      )
    ),
  constraint ops_registration_observations_source_revision_shape_check
    check (
      (
        source_revision = pg_catalog.jsonb_build_object(
          'authority', 'normalized',
          'sessionId', source_revision ->> 'sessionId',
          'revision', (source_revision ->> 'revision')::bigint
        )
        and source_revision ->> 'authority' = 'normalized'
        and (source_revision ->> 'sessionId')::uuid is not null
        and pg_catalog.jsonb_typeof(source_revision -> 'revision') = 'number'
        and (source_revision ->> 'revision')::bigint >= 0
      )
      or
      (
        source_revision = pg_catalog.jsonb_build_object(
          'authority', 'legacy',
          'sessionKey', source_revision ->> 'sessionKey',
          'contentHash', source_revision ->> 'contentHash'
        )
        and source_revision ->> 'authority' = 'legacy'
        and nullif(pg_catalog.btrim(source_revision ->> 'sessionKey'), '') is not null
        and nullif(pg_catalog.btrim(source_revision ->> 'contentHash'), '') is not null
      )
    ),
  constraint ops_registration_observations_source_revision_columns_check
    check (
      (
        session_authority = 'normalized'
        and source_revision ->> 'authority' = 'normalized'
        and source_revision ->> 'sessionId' = class_lesson_session_id::text
        and (source_revision ->> 'revision')::bigint = session_source_revision
      )
      or
      (
        session_authority = 'legacy'
        and source_revision ->> 'authority' = 'legacy'
        and source_revision ->> 'sessionKey' = legacy_session_key
        and source_revision ->> 'contentHash' = legacy_session_source_hash
      )
    ),
  constraint ops_registration_observations_time_order_check
    check (starts_at < ends_at),
  constraint ops_registration_observations_schedule_state_check
    check (nullif(pg_catalog.btrim(session_schedule_state), '') is not null),
  constraint ops_registration_observations_status_check
    check (status in (
      'scheduled',
      'attended_feedback_pending',
      'completed',
      'no_show',
      'canceled'
    )),
  constraint ops_registration_observations_attendance_check
    check (attendance is null or attendance in ('attended', 'no_show')),
  constraint ops_registration_observations_attendance_actor_check
    check (
      (
        attendance is null
        and attendance_recorded_by is null
        and attendance_recorded_at is null
      )
      or
      (
        attendance is not null
        and attendance_recorded_by is not null
        and attendance_recorded_at is not null
      )
    ),
  constraint ops_registration_observations_status_facts_check
    check (
      (
        status = 'scheduled'
        and attendance is null
        and suitability_result is null
        and feedback_reason is null
        and feedback_submitted_by is null
        and feedback_submitted_at is null
      )
      or
      (
        status = 'attended_feedback_pending'
        and attendance is not null
        and attendance = 'attended'
        and suitability_result is null
        and feedback_reason is null
        and feedback_submitted_by is null
        and feedback_submitted_at is null
      )
      or
      (
        status = 'completed'
        and attendance is not null
        and attendance = 'attended'
        and suitability_result is not null
        and suitability_result in ('fit', 'unfit')
        and nullif(pg_catalog.btrim(feedback_reason), '') is not null
        and feedback_submitted_by is not null
        and feedback_submitted_at is not null
      )
      or
      (
        status = 'no_show'
        and attendance is not null
        and attendance = 'no_show'
        and suitability_result is null
        and feedback_reason is null
        and feedback_submitted_by is null
        and feedback_submitted_at is null
      )
      or
      (
        status = 'canceled'
        and attendance is null
        and suitability_result is null
        and feedback_reason is null
        and feedback_submitted_by is null
        and feedback_submitted_at is null
      )
    ),
  constraint ops_registration_observations_decision_kind_check
    check (
      decision_kind is null
      or decision_kind in (
        'enrollment',
        'waiting_current_class',
        'waiting_new_class',
        'waiting_next_opening',
        'not_registered',
        're_observation'
      )
    ),
  constraint ops_registration_observations_decision_actor_check
    check (
      (
        decision_kind is null
        and decided_by is null
        and decided_at is null
      )
      or
      (
        decision_kind is not null
        and decided_by is not null
        and decided_at is not null
      )
    ),
  constraint ops_registration_observations_revisions_check
    check (
      revision > 0
      and feedback_revision >= 0
      and (session_source_revision is null or session_source_revision >= 0)
    ),
  constraint ops_registration_observations_text_facts_check
    check (
      nullif(pg_catalog.btrim(subject), '') is not null
      and nullif(pg_catalog.btrim(class_name_snapshot), '') is not null
      and nullif(pg_catalog.btrim(teacher_name_snapshot), '') is not null
      and nullif(pg_catalog.btrim(classroom_name_snapshot), '') is not null
      and nullif(pg_catalog.btrim(booking_fact_hash), '') is not null
      and campus in ('본관', '별관')
    ),
  constraint ops_registration_observations_textbook_snapshot_check
    check (pg_catalog.jsonb_typeof(textbook_snapshot) = 'array')
);
create unique index ops_registration_observations_open_track_key
  on public.ops_registration_observations(track_id)
  where decision_kind is null
    and status in ('scheduled', 'attended_feedback_pending', 'completed', 'no_show');
create index ops_registration_observations_track_decision_status_idx
  on public.ops_registration_observations(track_id, decision_kind, status, created_at desc, id desc);
create index ops_registration_observations_teacher_status_idx
  on public.ops_registration_observations(teacher_profile_id, status, starts_at, id);
create index ops_registration_observations_task_idx
  on public.ops_registration_observations(task_id);
create index ops_registration_observations_class_idx
