create or replace function dashboard_private.registration_observation_booking_fact_hash_v1(
  p_fact jsonb
)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select dashboard_private.continuous_class_schedule_hash_v1(
    pg_catalog.jsonb_build_object(
      'classId', p_fact -> 'classId',
      'subject', p_fact -> 'subject',
      'sessionAuthority', p_fact -> 'sessionAuthority',
      'classLessonSessionId', p_fact -> 'classLessonSessionId',
      'legacySessionKey', p_fact -> 'legacySessionKey',
      'sessionKey', p_fact -> 'sessionKey',
      'scheduleState', p_fact -> 'scheduleState',
      'sessionDate', p_fact -> 'sessionDate',
      'startsAt', p_fact -> 'startsAt',
      'endsAt', p_fact -> 'endsAt',
      'teacherCatalogId', p_fact -> 'teacherCatalogId',
      'teacherProfileId', p_fact -> 'teacherProfileId',
      'teacherName', p_fact -> 'teacherName',
      'classroomCatalogId', p_fact -> 'classroomCatalogId',
      'classroomName', p_fact -> 'classroomName',
      'campus', p_fact -> 'campus'
    )
  );
$$;
create or replace function dashboard_private.registration_observation_legacy_session_content_hash_v1(
  p_schedule_plan jsonb,
  p_session_key text
)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sessions jsonb;
  v_row record;
  v_row_key text;
  v_seen_keys text[] := array[]::text[];
  v_selected_count integer := 0;
  v_selected_session jsonb;
  v_canonical_session_key text;
  v_envelope jsonb;
begin
  if nullif(pg_catalog.btrim(p_session_key), '') is null then
    raise exception 'registration_observation_legacy_session_invalid'
      using errcode = '22023';
  end if;

  v_sessions := case
    when pg_catalog.jsonb_typeof(p_schedule_plan -> 'sessions') = 'array'
      then p_schedule_plan -> 'sessions'
    when pg_catalog.jsonb_typeof(p_schedule_plan -> 'session_list') = 'array'
      then p_schedule_plan -> 'session_list'
    else '[]'::jsonb
  end;

  for v_row in
    select session.value
    from pg_catalog.jsonb_array_elements(v_sessions) session(value)
  loop
    v_row_key := coalesce(
      nullif(pg_catalog.btrim(v_row.value ->> 'sessionKey'), ''),
      nullif(pg_catalog.btrim(v_row.value ->> 'session_key'), ''),
      nullif(pg_catalog.btrim(v_row.value ->> 'id'), '')
    );
    if v_row_key is null or v_row_key = any(v_seen_keys) then
      raise exception 'registration_observation_legacy_session_invalid'
        using errcode = '22023';
    end if;
    v_seen_keys := pg_catalog.array_append(v_seen_keys, v_row_key);
    if v_row_key = p_session_key then
      v_selected_count := v_selected_count + 1;
      v_selected_session := v_row.value;
    end if;
  end loop;

  if v_selected_count <> 1 then
    raise exception 'registration_observation_legacy_session_invalid'
      using errcode = '22023';
  end if;

  v_canonical_session_key := p_session_key;
  v_envelope := pg_catalog.jsonb_build_object(
    'textbooks',
    coalesce((
      select pg_catalog.jsonb_agg(book.value order by book.ordinality)
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(p_schedule_plan -> 'textbooks') = 'array'
            then p_schedule_plan -> 'textbooks'
          else '[]'::jsonb
        end
      ) with ordinality book(value, ordinality)
      where nullif(pg_catalog.btrim(book.value ->> 'textbookId'), '') in (
        select nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), '')
        from pg_catalog.jsonb_array_elements(
          case
            when pg_catalog.jsonb_typeof(v_selected_session -> 'textbookEntries') = 'array'
              then v_selected_session -> 'textbookEntries'
            else '[]'::jsonb
          end
        ) entry(value)
      )
    ), '[]'::jsonb),
    'sessions',
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'sessionKey', v_canonical_session_key,
      'textbookEntries',
      case
        when pg_catalog.jsonb_typeof(v_selected_session -> 'textbookEntries') = 'array'
          then v_selected_session -> 'textbookEntries'
        else '[]'::jsonb
      end
    ))
  );

  return dashboard_private.continuous_class_schedule_content_hash_v1(v_envelope);
end;
$$;
create or replace function dashboard_private.resolve_registration_observation_session_v1(
  p_track_id uuid,
  p_class_id uuid,
  p_session_authority text,
  p_class_lesson_session_id uuid,
  p_legacy_session_key text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_track public.ops_registration_subject_tracks%rowtype;
  v_class public.classes%rowtype;
  v_lesson public.class_lesson_sessions%rowtype;
  v_slot public.class_schedule_slots%rowtype;
  v_teacher public.teacher_catalogs%rowtype;
  v_classroom public.classroom_catalogs%rowtype;
  v_sessions jsonb;
  v_row record;
  v_row_key text;
  v_seen_keys text[] := array[]::text[];
  v_selected_count integer := 0;
  v_selected_session jsonb := '{}'::jsonb;
  v_session_key text;
  v_schedule_state text;
  v_session_date date;
  v_start_time time;
  v_end_time time;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_session_source_revision bigint;
  v_legacy_session_source_hash text;
  v_source_revision jsonb;
  v_teacher_catalog_id uuid;
  v_classroom_catalog_id uuid;
  v_teacher_name_fallback text;
  v_classroom_name_fallback text;
  v_catalog_count integer;
  v_slot_count integer;
  v_textbook_entries jsonb;
  v_textbooks jsonb;
  v_progress_value text;
  v_progress text;
  v_booking_fact jsonb;
  v_booking_fact_hash text;
begin
  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  join public.ops_tasks task
    on task.id = track.task_id
   and task.type = 'registration'
  where track.id = p_track_id;

  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select class.*
  into v_class
  from public.classes class
  where class.id = p_class_id
    and class.subject = v_track.subject
    and class.closed_at is null;

  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  if p_session_authority = 'normalized' then
    if public.continuous_class_schedule_runtime_version() <> 1
      or not (v_class.schedule_storage_mode = 'normalized')
      or p_class_lesson_session_id is null
      or p_legacy_session_key is not null
    then
      raise exception 'registration_observation_session_invalid'
        using errcode = '22023';
    end if;

    select lesson.*
    into v_lesson
    from public.class_lesson_sessions lesson
    where lesson.id = p_class_lesson_session_id
      and lesson.class_id = p_class_id
      and lesson.schedule_state in ('active', 'makeup')
      and lesson.start_time is not null
      and lesson.end_time is not null
      and lesson.start_time < lesson.end_time;

    if not found or nullif(pg_catalog.btrim(v_lesson.session_key), '') is null then
      raise exception 'registration_observation_session_invalid'
        using errcode = '22023';
    end if;

    v_session_key := v_lesson.session_key;
    v_schedule_state := v_lesson.schedule_state;
    v_session_date := v_lesson.session_date;
    v_start_time := v_lesson.start_time;
    v_end_time := v_lesson.end_time;
    v_session_source_revision := v_lesson.revision;
    v_teacher_catalog_id := v_lesson.teacher_catalog_id;
    v_classroom_catalog_id := v_lesson.classroom_catalog_id;
    v_teacher_name_fallback := nullif(pg_catalog.btrim(v_lesson.teacher_name_snapshot), '');
    v_classroom_name_fallback := nullif(pg_catalog.btrim(v_lesson.classroom_name_snapshot), '');

    v_sessions := case
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'sessions') = 'array'
        then v_class.schedule_plan -> 'sessions'
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'session_list') = 'array'
        then v_class.schedule_plan -> 'session_list'
      else '[]'::jsonb
    end;
    for v_row in
      select session.value
      from pg_catalog.jsonb_array_elements(v_sessions) session(value)
    loop
      v_row_key := coalesce(
        nullif(pg_catalog.btrim(v_row.value ->> 'sessionKey'), ''),
        nullif(pg_catalog.btrim(v_row.value ->> 'session_key'), ''),
        nullif(pg_catalog.btrim(v_row.value ->> 'id'), '')
      );
      if v_row_key = v_session_key then
        v_selected_count := v_selected_count + 1;
        v_selected_session := v_row.value;
      end if;
    end loop;
    if v_selected_count > 1 then
      raise exception 'registration_observation_session_invalid'
        using errcode = '22023';
    end if;

    v_source_revision := pg_catalog.jsonb_build_object(
      'authority', 'normalized',
      'sessionId', p_class_lesson_session_id,
      'revision', v_session_source_revision
    );
  elsif p_session_authority = 'legacy' then
    if not (v_class.schedule_storage_mode in ('legacy', 'shadow'))
      or p_class_lesson_session_id is not null
      or nullif(pg_catalog.btrim(p_legacy_session_key), '') is null
    then
      raise exception 'registration_observation_legacy_session_invalid'
        using errcode = '22023';
    end if;

    v_sessions := case
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'sessions') = 'array'
        then v_class.schedule_plan -> 'sessions'
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'session_list') = 'array'
        then v_class.schedule_plan -> 'session_list'
      else '[]'::jsonb
    end;

    for v_row in
      select session.value
      from pg_catalog.jsonb_array_elements(v_sessions) session(value)
    loop
      v_row_key := coalesce(
        nullif(pg_catalog.btrim(v_row.value ->> 'sessionKey'), ''),
        nullif(pg_catalog.btrim(v_row.value ->> 'session_key'), ''),
        nullif(pg_catalog.btrim(v_row.value ->> 'id'), '')
      );
      if v_row_key is null or v_row_key = any(v_seen_keys) then
        raise exception 'registration_observation_legacy_session_invalid'
          using errcode = '22023';
      end if;
      v_seen_keys := pg_catalog.array_append(v_seen_keys, v_row_key);
      if v_row_key = p_legacy_session_key then
        v_selected_count := v_selected_count + 1;
        v_selected_session := v_row.value;
      end if;
    end loop;

    if v_selected_count <> 1 then
      raise exception 'registration_observation_legacy_session_invalid'
        using errcode = '22023';
    end if;

    v_session_key := p_legacy_session_key;
    begin
      v_session_date := coalesce(
        nullif(pg_catalog.btrim(v_selected_session ->> 'date'), ''),
        nullif(pg_catalog.btrim(v_selected_session ->> 'sessionDate'), ''),
        nullif(pg_catalog.btrim(v_selected_session ->> 'session_date'), '')
      )::date;
    exception
      when invalid_datetime_format or datetime_field_overflow then
        raise exception 'registration_observation_legacy_session_invalid'
          using errcode = '22023';
    end;
    if v_session_date is null then
      raise exception 'registration_observation_legacy_session_invalid'
        using errcode = '22023';
    end if;

    v_schedule_state := pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_selected_session ->> 'scheduleState'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'schedule_state'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'state'), ''),
      'active'
    ));
    v_schedule_state := case v_schedule_state
      when 'normal' then 'active'
      else v_schedule_state
    end;
    if v_schedule_state not in ('active', 'makeup') then
      raise exception 'registration_observation_legacy_session_invalid'
        using errcode = '22023';
    end if;

    select count(*)
    into v_slot_count
    from public.class_schedule_slots slot
    where slot.class_id = p_class_id
      and slot.weekday = extract(dow from v_session_date)::smallint;
    if v_slot_count <> 1 then
      raise exception 'registration_observation_session_time_ambiguous'
        using errcode = '22023';
    end if;

    select slot.*
    into v_slot
    from public.class_schedule_slots slot
    where slot.class_id = p_class_id
      and slot.weekday = extract(dow from v_session_date)::smallint
    limit 1;
    v_start_time := v_slot.start_time;
    v_end_time := v_slot.end_time;

    begin
      v_teacher_catalog_id := coalesce(
        nullif(pg_catalog.btrim(v_selected_session ->> 'teacherCatalogId'), '')::uuid,
        nullif(pg_catalog.btrim(v_selected_session ->> 'teacher_catalog_id'), '')::uuid,
        v_slot.teacher_catalog_id
      );
      v_classroom_catalog_id := coalesce(
        nullif(pg_catalog.btrim(v_selected_session ->> 'classroomCatalogId'), '')::uuid,
        nullif(pg_catalog.btrim(v_selected_session ->> 'classroom_catalog_id'), '')::uuid,
        v_slot.classroom_catalog_id
      );
    exception
      when invalid_text_representation then
        raise exception 'registration_observation_legacy_session_invalid'
          using errcode = '22023';
    end;
    v_teacher_name_fallback := coalesce(
      nullif(pg_catalog.btrim(v_selected_session ->> 'teacherName'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'teacher_name'), ''),
      nullif(pg_catalog.btrim(v_slot.teacher_name), ''),
      nullif(pg_catalog.btrim(v_class.teacher), '')
    );
    v_classroom_name_fallback := coalesce(
      nullif(pg_catalog.btrim(v_selected_session ->> 'classroomName'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'classroom_name'), ''),
      nullif(pg_catalog.btrim(v_slot.classroom_name), ''),
      nullif(pg_catalog.btrim(v_class.room), '')
    );

    v_legacy_session_source_hash :=
      dashboard_private.registration_observation_legacy_session_content_hash_v1(
        v_class.schedule_plan,
        v_session_key
      );
    v_source_revision := pg_catalog.jsonb_build_object(
      'authority', 'legacy',
      'sessionKey', v_session_key,
      'contentHash', v_legacy_session_source_hash
    );
  else
    raise exception 'registration_observation_session_invalid'
      using errcode = '22023';
  end if;

  v_starts_at := (v_session_date + v_start_time) at time zone 'Asia/Seoul';
  v_ends_at := (v_session_date + v_end_time) at time zone 'Asia/Seoul';
  if v_start_time is null
    or v_end_time is null
    or v_start_time >= v_end_time
    or v_starts_at <= pg_catalog.now()
  then
    raise exception 'registration_observation_session_invalid'
      using errcode = '22023';
  end if;

  if v_teacher_catalog_id is not null then
    select teacher.*
    into v_teacher
    from public.teacher_catalogs teacher
    where teacher.id = v_teacher_catalog_id
      and teacher.is_visible = true
      and teacher.profile_id is not null
      and (pg_catalog.cardinality(teacher.subjects) = 0 or v_track.subject = any(teacher.subjects));
  elsif p_session_authority = 'legacy' then
    select count(*)
    into v_catalog_count
    from public.teacher_catalogs teacher
    where teacher.is_visible = true
      and teacher.profile_id is not null
      and pg_catalog.lower(teacher.name) = pg_catalog.lower(v_teacher_name_fallback)
      and (pg_catalog.cardinality(teacher.subjects) = 0 or v_track.subject = any(teacher.subjects));
    if v_catalog_count = 1 then
      select teacher.*
      into v_teacher
      from public.teacher_catalogs teacher
      where teacher.is_visible = true
        and teacher.profile_id is not null
        and pg_catalog.lower(teacher.name) = pg_catalog.lower(v_teacher_name_fallback)
        and (pg_catalog.cardinality(teacher.subjects) = 0 or v_track.subject = any(teacher.subjects));
    end if;
  end if;
  if v_teacher.id is null
    or not dashboard_private.notification_profile_is_active_v1(v_teacher.profile_id)
  then
    raise exception 'registration_observation_session_invalid'
      using errcode = '22023';
  end if;

  if v_classroom_catalog_id is not null then
    select classroom.*
    into v_classroom
    from public.classroom_catalogs classroom
    where classroom.id = v_classroom_catalog_id
      and classroom.is_visible = true
      and classroom.campus in ('본관', '별관')
      and (pg_catalog.cardinality(classroom.subjects) = 0 or v_track.subject = any(classroom.subjects));
  elsif p_session_authority = 'legacy' then
    select count(*)
    into v_catalog_count
    from public.classroom_catalogs classroom
    where classroom.is_visible = true
      and classroom.campus in ('본관', '별관')
      and pg_catalog.lower(classroom.name) = pg_catalog.lower(v_classroom_name_fallback)
      and (pg_catalog.cardinality(classroom.subjects) = 0 or v_track.subject = any(classroom.subjects));
    if v_catalog_count = 1 then
      select classroom.*
      into v_classroom
      from public.classroom_catalogs classroom
      where classroom.is_visible = true
        and classroom.campus in ('본관', '별관')
        and pg_catalog.lower(classroom.name) = pg_catalog.lower(v_classroom_name_fallback)
        and (pg_catalog.cardinality(classroom.subjects) = 0 or v_track.subject = any(classroom.subjects));
    end if;
  end if;
  if v_classroom.id is null then
    raise exception 'registration_observation_session_invalid'
      using errcode = '22023';
  end if;

  v_textbook_entries := case
    when pg_catalog.jsonb_typeof(v_selected_session -> 'textbookEntries') = 'array'
      then v_selected_session -> 'textbookEntries'
    else '[]'::jsonb
  end;
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'textbookId', nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), ''),
        'title', coalesce(
          nullif(pg_catalog.btrim(book.value ->> 'title'), ''),
          nullif(pg_catalog.btrim(book.value ->> 'name'), ''),
          nullif(pg_catalog.btrim(entry.value ->> 'textbookTitle'), ''),
          '교재 ' || entry.ordinality::text
        ),
        'planLabel', coalesce(
          nullif(pg_catalog.btrim(entry.value -> 'plan' ->> 'label'), ''),
          nullif(pg_catalog.btrim(entry.value ->> 'planLabel'), ''),
          ''
        ),
        'memo', coalesce(
          nullif(pg_catalog.btrim(entry.value -> 'plan' ->> 'memo'), ''),
          nullif(pg_catalog.btrim(entry.value ->> 'memo'), ''),
          ''
        )
      )
      order by entry.ordinality
    ),
    '[]'::jsonb
  )
  into v_textbooks
  from pg_catalog.jsonb_array_elements(v_textbook_entries)
    with ordinality entry(value, ordinality)
  left join lateral (
    select textbook.value
    from pg_catalog.jsonb_array_elements(
      case
        when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'textbooks') = 'array'
          then v_class.schedule_plan -> 'textbooks'
        else '[]'::jsonb
      end
    ) textbook(value)
    where nullif(pg_catalog.btrim(textbook.value ->> 'textbookId'), '')
      = nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), '')
    limit 1
  ) book on true;

  select nullif(pg_catalog.btrim(coalesce(
    nullif(progress.range_label, ''),
    nullif(progress.content, ''),
    nullif(progress.public_note, '')
  )), '')
  into v_progress_value
  from public.progress_logs progress
  where progress.class_id = p_class_id
    and progress.session_id in (
      v_session_key,
      coalesce(p_class_lesson_session_id::text, v_session_key)
    )
  order by progress.updated_at desc nulls last, progress.id desc
  limit 1;

  if v_progress_value is null then
    v_progress_value := case
      when p_session_authority = 'normalized' then coalesce(
        nullif(pg_catalog.btrim(v_lesson.public_note), ''),
        nullif(pg_catalog.btrim(v_lesson.memo), '')
      )
      else coalesce(
        nullif(pg_catalog.btrim(v_selected_session ->> 'publicNote'), ''),
        nullif(pg_catalog.btrim(v_selected_session ->> 'public_note'), ''),
        nullif(pg_catalog.btrim(v_selected_session ->> 'memo'), '')
      )
    end;
  end if;
  v_progress := case
    when v_progress_value is null then '진도: 미입력'
    else '진도: ' || v_progress_value
  end;

  v_booking_fact := pg_catalog.jsonb_build_object(
    'classId', p_class_id,
    'subject', v_track.subject,
    'sessionAuthority', p_session_authority,
    'classLessonSessionId', p_class_lesson_session_id,
    'legacySessionKey', p_legacy_session_key,
    'sessionKey', v_session_key,
    'scheduleState', v_schedule_state,
    'sessionDate', v_session_date,
    'startsAt', v_starts_at,
    'endsAt', v_ends_at,
    'teacherCatalogId', v_teacher.id,
    'teacherProfileId', v_teacher.profile_id,
    'teacherName', v_teacher.name,
    'classroomCatalogId', v_classroom.id,
    'classroomName', v_classroom.name,
    'campus', v_classroom.campus
  );
  v_booking_fact_hash :=
    dashboard_private.registration_observation_booking_fact_hash_v1(v_booking_fact);

  return pg_catalog.jsonb_build_object(
    'classId', p_class_id,
    'subject', v_track.subject,
    'sessionAuthority', p_session_authority,
    'classLessonSessionId', p_class_lesson_session_id,
    'legacySessionKey', p_legacy_session_key,
    'sessionKey', v_session_key,
    'scheduleState', v_schedule_state,
    'sessionDate', v_session_date,
    'startsAt', v_starts_at,
    'endsAt', v_ends_at,
    'sessionSourceRevision', v_session_source_revision,
    'legacySessionSourceHash', v_legacy_session_source_hash,
    'sourceRevision', v_source_revision,
    'teacherCatalogId', v_teacher.id,
    'teacherProfileId', v_teacher.profile_id,
    'teacherName', v_teacher.name,
    'classroomCatalogId', v_classroom.id,
    'classroomName', v_classroom.name,
    'campus', v_classroom.campus,
    'className', v_class.name,
    'textbooks', v_textbooks,
    'progress', v_progress,
    'bookingFactHash', v_booking_fact_hash
  );
end;
$$;
alter function dashboard_private.registration_observation_booking_fact_hash_v1(jsonb)
  owner to postgres;
alter function dashboard_private.registration_observation_legacy_session_content_hash_v1(jsonb, text)
  owner to postgres;
alter function dashboard_private.resolve_registration_observation_session_v1(uuid, uuid, text, uuid, text)
  owner to postgres;
revoke all on function dashboard_private.registration_observation_booking_fact_hash_v1(jsonb)
  from public, anon, authenticated, service_role;
revoke all on function dashboard_private.registration_observation_legacy_session_content_hash_v1(jsonb, text)
  from public, anon, authenticated, service_role;
revoke all on function dashboard_private.resolve_registration_observation_session_v1(uuid, uuid, text, uuid, text)
  from public, anon, authenticated, service_role;
commit;
begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
create or replace function dashboard_private.registration_observation_active_actor_v1()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
begin
  if v_actor is null
    or not exists (
      select 1
      from public.profiles profile
      join auth.users account on account.id = profile.id
      where profile.id = v_actor
        and account.deleted_at is null
        and (account.banned_until is null or account.banned_until <= pg_catalog.now())
    )
  then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  return v_actor;
end;
$$;
create or replace function dashboard_private.registration_observation_request_fingerprint_v1(
  p_semantic_input jsonb
)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select dashboard_private.continuous_class_schedule_hash_v1(
    p_semantic_input
  );
$$;
create or replace function dashboard_private.registration_observation_response_v1(
  p_operation text,
  p_request_key text,
  p_track public.ops_registration_subject_tracks,
  p_observation public.ops_registration_observations,
  p_appointment public.ops_registration_appointments,
  p_changed boolean
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'operation', p_operation,
    'requestKey', p_request_key,
    'trackId', p_track.id,
    'workflowStatus', p_track.workflow_status,
    'workflowRevision', p_track.workflow_revision,
    'observation', case
      when p_observation.id is null then null::jsonb
      else dashboard_private.registration_observation_attempt_payload_v1(
        p_observation,
        p_appointment,
        case p_observation.session_authority
          when 'normalized' then (
            select lesson.session_key
            from public.class_lesson_sessions lesson
            where lesson.id = p_observation.class_lesson_session_id
              and lesson.class_id = p_observation.class_id
          )
          when 'legacy' then p_observation.legacy_session_key
          else null
        end
      )
    end,
    'appointment', case
      when p_appointment.id is null then null::jsonb
      else pg_catalog.jsonb_build_object(
        'appointmentId', p_appointment.id,
        'status', p_appointment.status,
        'scheduledAt', p_appointment.scheduled_at,
        'place', p_appointment.place,
        'notificationRevision', p_appointment.notification_revision
      )
    end,
    'changed', p_changed
  );
$$;
create or replace function dashboard_private.enter_registration_observation_v1_impl(
  p_track_id uuid,
  p_expected_workflow_revision integer,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := dashboard_private.registration_observation_active_actor_v1();
  v_fingerprint text;
  v_existing dashboard_private.registration_observation_mutation_requests%rowtype;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_source_status text;
  v_source_revision integer;
  v_response jsonb;
begin
  if p_track_id is null
    or p_expected_workflow_revision is null
    or p_expected_workflow_revision < 1
    or nullif(pg_catalog.btrim(p_request_key), '') is null
  then
    raise exception 'registration_observation_enter_invalid'
      using errcode = '22023';
  end if;

  v_fingerprint :=
    dashboard_private.registration_observation_request_fingerprint_v1(
      pg_catalog.jsonb_build_object(
        'operation', 'enter',
        'trackId', p_track_id,
        'expectedWorkflowRevision', p_expected_workflow_revision
      )
    );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || p_request_key, 0)
  );

  select request.*
  into v_existing
  from dashboard_private.registration_observation_mutation_requests request
  where request.actor_profile_id = v_actor
    and request.request_key = p_request_key;
  if found then
    if v_existing.operation <> 'enter'
      or v_existing.request_fingerprint <> v_fingerprint
    then
      raise exception 'registration_observation_request_key_conflict'
        using errcode = '23505';
    end if;
    return v_existing.response_payload;
  end if;

  perform dashboard_private.assert_registration_observation_runtime_v1();

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = p_track_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  perform dashboard_private.assert_registration_observation_manager_access_v1(
    v_track.id
  );

  if v_track.workflow_revision <> p_expected_workflow_revision then
    raise exception 'registration_observation_stale_revision'
      using errcode = '40001';
  end if;
  if v_track.workflow_status not in (
    'consultation_completed',
    'waiting_current_class',
    'waiting_new_class',
    'waiting_next_opening'
  ) or exists (
    select 1
    from public.ops_registration_observations observation
    where observation.track_id = v_track.id
      and observation.decision_kind is null
      and observation.status in (
        'scheduled', 'attended_feedback_pending', 'completed', 'no_show'
      )
  ) then
    raise exception 'registration_observation_transition_rejected'
      using errcode = '55000';
  end if;

  v_source_status := v_track.workflow_status;
  v_source_revision := v_track.workflow_revision;
  update public.ops_registration_subject_tracks track
  set workflow_status = 'observation_requested',
      workflow_revision = track.workflow_revision + 1,
      workflow_status_entered_at = pg_catalog.now(),
      observation_return_workflow_status = v_source_status,
      updated_at = pg_catalog.now()
  where track.id = v_track.id
  returning track.* into v_track;

  perform dashboard_private.write_registration_track_event_v2(
    v_track.task_id,
    v_track.id,
    'registration_observation_entered',
    v_source_status,
    v_track.workflow_status,
    null,
    pg_catalog.jsonb_build_object(
      'trackId', v_track.id,
      'workflowRevisionBefore', v_source_revision,
      'workflowRevisionAfter', v_track.workflow_revision
    ),
    'user',
    null
  );

  v_response := dashboard_private.registration_observation_response_v1(
    'enter', p_request_key, v_track, null, null, true
  );
  insert into dashboard_private.registration_observation_mutation_requests(
    actor_profile_id, operation, request_key, track_id,
    request_fingerprint, response_payload
  ) values (
    v_actor, 'enter', p_request_key, v_track.id,
    v_fingerprint, v_response
  );
  return v_response;
end;
$$;
create or replace function dashboard_private.save_registration_observation_booking_v1_impl(
  p_track_id uuid,
  p_observation_id uuid,
  p_class_id uuid,
  p_session_authority text,
  p_class_lesson_session_id uuid,
  p_legacy_session_key text,
  p_expected_workflow_revision integer,
  p_expected_appointment_notification_revision integer,
  p_expected_observation_revision bigint,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := dashboard_private.registration_observation_active_actor_v1();
  v_operation text;
  v_fingerprint text;
  v_existing dashboard_private.registration_observation_mutation_requests%rowtype;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_observation public.ops_registration_observations%rowtype;
  v_appointment public.ops_registration_appointments%rowtype;
  v_resolved jsonb;
  v_response jsonb;
  v_changed boolean;
  v_attempt_count_before bigint;
  v_observation_revision_before bigint;
  v_notification_revision_before integer;
begin
  if p_track_id is null
    or p_class_id is null
    or nullif(pg_catalog.btrim(p_session_authority), '') is null
    or nullif(pg_catalog.btrim(p_request_key), '') is null
  then
    raise exception 'registration_observation_booking_invalid'
      using errcode = '22023';
  end if;

  if p_observation_id is null then
    if p_expected_workflow_revision is null
      or p_expected_workflow_revision < 1
      or p_expected_appointment_notification_revision is not null
      or p_expected_observation_revision is not null
    then
      raise exception 'registration_observation_revision_combination_invalid'
        using errcode = '22023';
    end if;
    v_operation := 'book';
    v_fingerprint :=
      dashboard_private.registration_observation_request_fingerprint_v1(
        pg_catalog.jsonb_build_object(
          'operation', 'book',
          'trackId', p_track_id,
          'observationId', p_observation_id,
          'classId', p_class_id,
          'sessionAuthority', p_session_authority,
          'classLessonSessionId', p_class_lesson_session_id,
          'legacySessionKey', p_legacy_session_key,
          'expectedWorkflowRevision', p_expected_workflow_revision,
          'expectedAppointmentNotificationRevision',
            p_expected_appointment_notification_revision,
          'expectedObservationRevision', p_expected_observation_revision
        )
      );
  else
    if p_expected_workflow_revision is not null
      or p_expected_appointment_notification_revision is null
      or p_expected_appointment_notification_revision < 1
      or p_expected_observation_revision is null
      or p_expected_observation_revision < 1
    then
      raise exception 'registration_observation_revision_combination_invalid'
        using errcode = '22023';
    end if;
    v_operation := 'reschedule';
    v_fingerprint :=
      dashboard_private.registration_observation_request_fingerprint_v1(
        pg_catalog.jsonb_build_object(
          'operation', 'reschedule',
          'trackId', p_track_id,
          'observationId', p_observation_id,
          'classId', p_class_id,
          'sessionAuthority', p_session_authority,
          'classLessonSessionId', p_class_lesson_session_id,
          'legacySessionKey', p_legacy_session_key,
          'expectedWorkflowRevision', p_expected_workflow_revision,
          'expectedAppointmentNotificationRevision',
            p_expected_appointment_notification_revision,
          'expectedObservationRevision', p_expected_observation_revision
        )
      );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || p_request_key, 0)
  );
  select request.*
  into v_existing
  from dashboard_private.registration_observation_mutation_requests request
  where request.actor_profile_id = v_actor
    and request.request_key = p_request_key;
  if found then
    if v_existing.operation <> v_operation
      or v_existing.request_fingerprint <> v_fingerprint
    then
      raise exception 'registration_observation_request_key_conflict'
        using errcode = '23505';
    end if;
    return v_existing.response_payload;
  end if;

  perform dashboard_private.assert_registration_observation_runtime_v1();

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = p_track_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  perform dashboard_private.assert_registration_observation_manager_access_v1(
    v_track.id
  );

  if v_operation = 'book' then
    if v_track.workflow_revision <> p_expected_workflow_revision then
      raise exception 'registration_observation_stale_revision'
        using errcode = '40001';
    end if;
    if v_track.workflow_status <> 'observation_requested'
      or exists (
        select 1
        from public.ops_registration_observations observation
        where observation.track_id = v_track.id
          and observation.decision_kind is null
          and observation.status in (
            'scheduled', 'attended_feedback_pending', 'completed', 'no_show'
          )
      )
      or exists (
        select 1
        from public.ops_registration_observations observation
        join public.ops_registration_appointments appointment
          on appointment.id = observation.appointment_id
        where observation.track_id = v_track.id
          and observation.status = 'scheduled'
          and appointment.status = 'scheduled'
      )
    then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;

    v_resolved := dashboard_private.resolve_registration_observation_session_v1(
      v_track.id,
      p_class_id,
      p_session_authority,
      p_class_lesson_session_id,
      p_legacy_session_key
    );

    insert into public.ops_registration_appointments(
      task_id, kind, scheduled_at, place, status,
      notification_revision, created_by
    ) values (
      v_track.task_id,
      'observation_class',
      (v_resolved ->> 'startsAt')::timestamptz,
      v_resolved ->> 'campus',
      'scheduled',
      1,
      v_actor
    )
    returning * into v_appointment;

    insert into public.ops_registration_observations(
      task_id, track_id, appointment_id, class_id,
      session_authority, class_lesson_session_id, legacy_session_key,
      session_date, starts_at, ends_at, session_schedule_state,
      session_source_revision, legacy_session_source_hash, source_revision,
      booking_fact_hash, teacher_catalog_id, teacher_profile_id,
      classroom_catalog_id, subject, class_name_snapshot,
      teacher_name_snapshot, classroom_name_snapshot, campus,
      textbook_snapshot, progress_snapshot, status, feedback_revision,
      revision, created_by, updated_by
    ) values (
      v_track.task_id,
      v_track.id,
      v_appointment.id,
      (v_resolved ->> 'classId')::uuid,
      v_resolved ->> 'sessionAuthority',
      nullif(v_resolved ->> 'classLessonSessionId', '')::uuid,
      nullif(v_resolved ->> 'legacySessionKey', ''),
      (v_resolved ->> 'sessionDate')::date,
      (v_resolved ->> 'startsAt')::timestamptz,
      (v_resolved ->> 'endsAt')::timestamptz,
      v_resolved ->> 'scheduleState',
      nullif(v_resolved ->> 'sessionSourceRevision', '')::bigint,
      nullif(v_resolved ->> 'legacySessionSourceHash', ''),
      v_resolved -> 'sourceRevision',
      v_resolved ->> 'bookingFactHash',
      (v_resolved ->> 'teacherCatalogId')::uuid,
      (v_resolved ->> 'teacherProfileId')::uuid,
      (v_resolved ->> 'classroomCatalogId')::uuid,
      v_resolved ->> 'subject',
      v_resolved ->> 'className',
      v_resolved ->> 'teacherName',
      v_resolved ->> 'classroomName',
      v_resolved ->> 'campus',
      coalesce(v_resolved -> 'textbooks', '[]'::jsonb),
      coalesce(v_resolved ->> 'progress', ''),
      'scheduled',
      0,
      1,
      v_actor,
      v_actor
    )
    returning * into v_observation;

    v_attempt_count_before := v_track.observation_attempt_count;
    update public.ops_registration_subject_tracks track
    set observation_attempt_count = track.observation_attempt_count + 1,
        updated_at = pg_catalog.now()
    where track.id = v_track.id
    returning track.* into v_track;

    insert into dashboard_private.registration_observation_domain_events(
      observation_id, appointment_id, notification_revision,
      event_kind, booking_fact_hash, source_revision
    ) values (
      v_observation.id,
      v_appointment.id,
      v_appointment.notification_revision,
      'observation_scheduled',
      v_observation.booking_fact_hash,
      v_observation.source_revision
    );

    perform dashboard_private.write_registration_track_event_v2(
      v_track.task_id,
      v_track.id,
      'registration_observation_scheduled',
      v_track.workflow_status,
      v_track.workflow_status,
      null,
      pg_catalog.jsonb_build_object(
        'trackId', v_track.id,
        'observationId', v_observation.id,
        'appointmentId', v_appointment.id,
        'observationRevisionBefore', null,
        'observationRevisionAfter', v_observation.revision,
        'appointmentNotificationRevisionBefore', null,
        'appointmentNotificationRevisionAfter',
          v_appointment.notification_revision,
        'observationAttemptCountBefore', v_attempt_count_before,
        'observationAttemptCountAfter', v_track.observation_attempt_count
      ),
      'user',
      null
    );
    v_changed := true;
  else
    select observation.*
    into v_observation
    from public.ops_registration_observations observation
    where observation.id = p_observation_id
      and observation.track_id = v_track.id
    for update;
    if not found then
      raise exception 'registration_observation_not_found'
        using errcode = 'P0002';
    end if;
    if v_observation.revision <> p_expected_observation_revision then
      raise exception 'registration_observation_stale_revision'
        using errcode = '40001';
    end if;
    if v_observation.status <> 'scheduled'
      or v_observation.decision_kind is not null
    then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;

    select appointment.*
    into v_appointment
    from public.ops_registration_appointments appointment
    where appointment.id = v_observation.appointment_id
      and appointment.task_id = v_track.task_id
    for update;
    if not found then
      raise exception 'registration_observation_not_found'
        using errcode = 'P0002';
    end if;
    if v_appointment.notification_revision
      <> p_expected_appointment_notification_revision
    then
      raise exception 'registration_observation_stale_revision'
        using errcode = '40001';
    end if;
    if v_appointment.kind <> 'observation_class'
      or v_appointment.status <> 'scheduled'
    then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;

    v_resolved := dashboard_private.resolve_registration_observation_session_v1(
      v_track.id,
      p_class_id,
      p_session_authority,
      p_class_lesson_session_id,
      p_legacy_session_key
    );
    v_changed := v_observation.booking_fact_hash
      <> (v_resolved ->> 'bookingFactHash');

    if v_changed then
      v_observation_revision_before := v_observation.revision;
      v_notification_revision_before := v_appointment.notification_revision;

      update public.ops_registration_appointments appointment
      set scheduled_at = (v_resolved ->> 'startsAt')::timestamptz,
          place = v_resolved ->> 'campus',
          notification_revision = appointment.notification_revision + 1,
          updated_at = pg_catalog.now()
      where appointment.id = v_appointment.id
      returning appointment.* into v_appointment;

      update public.ops_registration_observations observation
      set class_id = (v_resolved ->> 'classId')::uuid,
          session_authority = v_resolved ->> 'sessionAuthority',
          class_lesson_session_id =
            nullif(v_resolved ->> 'classLessonSessionId', '')::uuid,
          legacy_session_key = nullif(v_resolved ->> 'legacySessionKey', ''),
          session_date = (v_resolved ->> 'sessionDate')::date,
          starts_at = (v_resolved ->> 'startsAt')::timestamptz,
          ends_at = (v_resolved ->> 'endsAt')::timestamptz,
          session_schedule_state = v_resolved ->> 'scheduleState',
          session_source_revision =
            nullif(v_resolved ->> 'sessionSourceRevision', '')::bigint,
          legacy_session_source_hash =
            nullif(v_resolved ->> 'legacySessionSourceHash', ''),
          source_revision = v_resolved -> 'sourceRevision',
          booking_fact_hash = v_resolved ->> 'bookingFactHash',
          teacher_catalog_id = (v_resolved ->> 'teacherCatalogId')::uuid,
          teacher_profile_id = (v_resolved ->> 'teacherProfileId')::uuid,
          classroom_catalog_id = (v_resolved ->> 'classroomCatalogId')::uuid,
          subject = v_resolved ->> 'subject',
          class_name_snapshot = v_resolved ->> 'className',
          teacher_name_snapshot = v_resolved ->> 'teacherName',
          classroom_name_snapshot = v_resolved ->> 'classroomName',
          campus = v_resolved ->> 'campus',
          textbook_snapshot = coalesce(v_resolved -> 'textbooks', '[]'::jsonb),
          progress_snapshot = coalesce(v_resolved ->> 'progress', ''),
          revision = observation.revision + 1,
          updated_by = v_actor,
          updated_at = pg_catalog.now()
      where observation.id = v_observation.id
      returning observation.* into v_observation;

      insert into dashboard_private.registration_observation_domain_events(
        observation_id, appointment_id, notification_revision,
        event_kind, booking_fact_hash, source_revision
      ) values (
        v_observation.id,
        v_appointment.id,
        v_appointment.notification_revision,
        'observation_rescheduled',
        v_observation.booking_fact_hash,
        v_observation.source_revision
      );

      perform dashboard_private.write_registration_track_event_v2(
        v_track.task_id,
        v_track.id,
        'registration_observation_rescheduled',
        v_track.workflow_status,
        v_track.workflow_status,
        null,
        pg_catalog.jsonb_build_object(
          'trackId', v_track.id,
          'observationId', v_observation.id,
          'appointmentId', v_appointment.id,
          'observationRevisionBefore', v_observation_revision_before,
          'observationRevisionAfter', v_observation.revision,
          'appointmentNotificationRevisionBefore',
            v_notification_revision_before,
          'appointmentNotificationRevisionAfter',
            v_appointment.notification_revision
        ),
        'user',
        null
      );
    end if;
  end if;

  v_response := dashboard_private.registration_observation_response_v1(
    v_operation,
    p_request_key,
    v_track,
    v_observation,
    v_appointment,
    v_changed
  );
  insert into dashboard_private.registration_observation_mutation_requests(
    actor_profile_id, operation, request_key, track_id,
    request_fingerprint, response_payload
  ) values (
    v_actor, v_operation, p_request_key, v_track.id,
    v_fingerprint, v_response
  );
  return v_response;
end;
$$;
create or replace function dashboard_private.cancel_registration_observation_v1_impl(
  p_observation_id uuid,
  p_expected_appointment_notification_revision integer,
  p_expected_observation_revision bigint,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := dashboard_private.registration_observation_active_actor_v1();
  v_fingerprint text;
  v_existing dashboard_private.registration_observation_mutation_requests%rowtype;
  v_track_id uuid;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_observation public.ops_registration_observations%rowtype;
  v_appointment public.ops_registration_appointments%rowtype;
  v_observation_revision_before bigint;
  v_notification_revision_before integer;
  v_response jsonb;
begin
  if p_observation_id is null
    or p_expected_appointment_notification_revision is null
    or p_expected_appointment_notification_revision < 1
    or p_expected_observation_revision is null
    or p_expected_observation_revision < 1
    or nullif(pg_catalog.btrim(p_request_key), '') is null
  then
    raise exception 'registration_observation_cancel_invalid'
      using errcode = '22023';
  end if;

  v_fingerprint :=
    dashboard_private.registration_observation_request_fingerprint_v1(
      pg_catalog.jsonb_build_object(
        'operation', 'cancel',
        'observationId', p_observation_id,
        'expectedAppointmentNotificationRevision',
          p_expected_appointment_notification_revision,
        'expectedObservationRevision', p_expected_observation_revision
      )
    );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || p_request_key, 0)
  );
  select request.*
  into v_existing
  from dashboard_private.registration_observation_mutation_requests request
  where request.actor_profile_id = v_actor
    and request.request_key = p_request_key;
  if found then
    if v_existing.operation <> 'cancel'
      or v_existing.request_fingerprint <> v_fingerprint
    then
      raise exception 'registration_observation_request_key_conflict'
        using errcode = '23505';
    end if;
    return v_existing.response_payload;
  end if;

  perform dashboard_private.assert_registration_observation_runtime_v1();

  select observation.track_id
  into v_track_id
  from public.ops_registration_observations observation
  where observation.id = p_observation_id;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = v_track_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  perform dashboard_private.assert_registration_observation_manager_access_v1(
    v_track.id
  );

  select observation.*
  into v_observation
  from public.ops_registration_observations observation
  where observation.id = p_observation_id
    and observation.track_id = v_track.id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  if v_observation.revision <> p_expected_observation_revision then
    raise exception 'registration_observation_stale_revision'
      using errcode = '40001';
  end if;

  select appointment.*
  into v_appointment
  from public.ops_registration_appointments appointment
  where appointment.id = v_observation.appointment_id
    and appointment.task_id = v_track.task_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  if v_appointment.notification_revision
    <> p_expected_appointment_notification_revision
  then
    raise exception 'registration_observation_stale_revision'
      using errcode = '40001';
  end if;
  if v_track.workflow_status <> 'observation_requested'
    or v_observation.status <> 'scheduled'
    or v_observation.decision_kind is not null
    or v_appointment.kind <> 'observation_class'
    or v_appointment.status <> 'scheduled'
  then
    raise exception 'registration_observation_transition_rejected'
      using errcode = '55000';
  end if;

  v_observation_revision_before := v_observation.revision;
  v_notification_revision_before := v_appointment.notification_revision;
  update public.ops_registration_observations observation
  set status = 'canceled',
      revision = observation.revision + 1,
      updated_by = v_actor,
      updated_at = pg_catalog.now()
  where observation.id = v_observation.id
  returning observation.* into v_observation;
  update public.ops_registration_appointments appointment
  set status = 'canceled',
      notification_revision = appointment.notification_revision + 1,
      updated_at = pg_catalog.now()
  where appointment.id = v_appointment.id
  returning appointment.* into v_appointment;

  insert into dashboard_private.registration_observation_domain_events(
    observation_id, appointment_id, notification_revision,
    event_kind, booking_fact_hash, source_revision
  ) values (
    v_observation.id,
    v_appointment.id,
    v_appointment.notification_revision,
    'observation_canceled',
    v_observation.booking_fact_hash,
    v_observation.source_revision
  );

  perform dashboard_private.write_registration_track_event_v2(
    v_track.task_id,
    v_track.id,
    'registration_observation_canceled',
    v_track.workflow_status,
    v_track.workflow_status,
    null,
    pg_catalog.jsonb_build_object(
      'trackId', v_track.id,
      'observationId', v_observation.id,
      'appointmentId', v_appointment.id,
      'observationRevisionBefore', v_observation_revision_before,
      'observationRevisionAfter', v_observation.revision,
      'appointmentNotificationRevisionBefore',
        v_notification_revision_before,
      'appointmentNotificationRevisionAfter',
        v_appointment.notification_revision
    ),
    'user',
    null
  );

  v_response := dashboard_private.registration_observation_response_v1(
    'cancel', p_request_key, v_track, v_observation, v_appointment, true
  );
  insert into dashboard_private.registration_observation_mutation_requests(
    actor_profile_id, operation, request_key, track_id,
    request_fingerprint, response_payload
  ) values (
    v_actor, 'cancel', p_request_key, v_track.id,
    v_fingerprint, v_response
  );
  return v_response;
end;
$$;
create or replace function dashboard_private.withdraw_registration_observation_v1_impl(
  p_track_id uuid,
  p_exit_kind text,
  p_target_workflow_status text,
  p_decision_observation_id uuid,
  p_expected_workflow_revision integer,
  p_expected_decision_observation_revision bigint,
  p_expected_decision_feedback_revision bigint,
  p_reason text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := dashboard_private.registration_observation_active_actor_v1();
  v_exit_kind text := nullif(pg_catalog.btrim(p_exit_kind), '');
  v_target_status text := nullif(pg_catalog.btrim(p_target_workflow_status), '');
  v_reason text := nullif(pg_catalog.btrim(p_reason), '');
  v_fingerprint text;
  v_existing dashboard_private.registration_observation_mutation_requests%rowtype;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_decision_observation public.ops_registration_observations%rowtype;
  v_decision_appointment public.ops_registration_appointments%rowtype;
  v_has_decision boolean := false;
  v_is_correction boolean := false;
  v_target_decision text;
  v_source_status text;
  v_workflow_revision_before integer;
  v_observation_revision_before bigint;
  v_decision_before text;
  v_metadata jsonb;
  v_response jsonb;
begin
  if p_track_id is null
    or v_exit_kind is null
    or v_exit_kind not in ('return_to_previous', 'director_decision')
    or v_target_status is null
    or p_expected_workflow_revision is null
    or p_expected_workflow_revision < 1
    or nullif(pg_catalog.btrim(p_request_key), '') is null
  then
    raise exception 'registration_observation_withdraw_invalid'
      using errcode = '22023';
  end if;
  if v_exit_kind = 'return_to_previous'
    and (
      p_decision_observation_id is not null
      or p_expected_decision_observation_revision is not null
      or p_expected_decision_feedback_revision is not null
    )
  then
    raise exception 'registration_observation_revision_combination_invalid'
      using errcode = '22023';
  end if;
  if v_exit_kind = 'director_decision'
    and not (
      (
        p_decision_observation_id is null
        and p_expected_decision_observation_revision is null
        and p_expected_decision_feedback_revision is null
      )
      or
      (
        p_decision_observation_id is not null
        and p_expected_decision_observation_revision is not null
        and p_expected_decision_observation_revision > 0
        and p_expected_decision_feedback_revision is not null
        and p_expected_decision_feedback_revision >= 0
      )
    )
  then
    raise exception 'registration_observation_revision_combination_invalid'
      using errcode = '22023';
  end if;

  v_fingerprint :=
    dashboard_private.registration_observation_request_fingerprint_v1(
      pg_catalog.jsonb_build_object(
        'operation', 'withdraw',
        'trackId', p_track_id,
        'exitKind', v_exit_kind,
        'targetWorkflowStatus', v_target_status,
        'decisionObservationId', p_decision_observation_id,
        'expectedWorkflowRevision', p_expected_workflow_revision,
        'expectedDecisionObservationRevision',
          p_expected_decision_observation_revision,
        'expectedDecisionFeedbackRevision',
          p_expected_decision_feedback_revision,
        'reason', v_reason
      )
    );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || p_request_key, 0)
  );
  select request.*
  into v_existing
  from dashboard_private.registration_observation_mutation_requests request
  where request.actor_profile_id = v_actor
    and request.request_key = p_request_key;
  if found then
    if v_existing.operation <> 'withdraw'
      or v_existing.request_fingerprint <> v_fingerprint
    then
      raise exception 'registration_observation_request_key_conflict'
        using errcode = '23505';
    end if;
    return v_existing.response_payload;
  end if;

  perform dashboard_private.assert_registration_observation_runtime_v1();

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = p_track_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  perform dashboard_private.assert_registration_observation_manager_access_v1(
    v_track.id
  );

  if v_track.workflow_revision <> p_expected_workflow_revision then
    raise exception 'registration_observation_stale_revision'
      using errcode = '40001';
  end if;
  if v_track.workflow_status <> 'observation_requested'
    or exists (
      select 1
      from public.ops_registration_observations observation
      where observation.track_id = v_track.id
        and observation.decision_kind is null
        and observation.status in (
          'scheduled', 'attended_feedback_pending', 'completed', 'no_show'
        )
    )
    or exists (
      select 1
      from public.ops_registration_observations observation
      join public.ops_registration_appointments appointment
        on appointment.id = observation.appointment_id
      where observation.track_id = v_track.id
        and appointment.kind = 'observation_class'
        and appointment.status = 'scheduled'
    )
  then
    raise exception 'registration_observation_transition_rejected'
      using errcode = '55000';
  end if;

  select observation.*
  into v_decision_observation
  from public.ops_registration_observations observation
  where observation.track_id = v_track.id
    and observation.decision_kind is not null
  order by observation.created_at desc, observation.id desc
  limit 1
  for update;
  v_has_decision := found;

  if v_has_decision then
    select appointment.*
    into v_decision_appointment
    from public.ops_registration_appointments appointment
    where appointment.id = v_decision_observation.appointment_id
      and appointment.task_id = v_track.task_id
    for update;
    if not found then
      raise exception 'registration_observation_not_found'
        using errcode = 'P0002';
    end if;
  end if;

  if v_exit_kind = 'return_to_previous' then
    if v_target_status is distinct from v_track.observation_return_workflow_status
    then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;
  else
    if v_target_status not in (
      'enrollment_requested',
      'waiting_current_class',
      'waiting_new_class',
      'waiting_next_opening',
      'not_registered'
    ) then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;
    v_target_decision := case v_target_status
      when 'enrollment_requested' then 'enrollment'
      else v_target_status
    end;

    if v_has_decision
      and v_decision_observation.decision_kind = 're_observation'
    then
      if p_decision_observation_id is null
        or p_decision_observation_id <> v_decision_observation.id
      then
        raise exception 'registration_observation_transition_rejected'
          using errcode = '55000';
      end if;
      if v_decision_observation.revision
        <> p_expected_decision_observation_revision
        or v_decision_observation.feedback_revision
        <> p_expected_decision_feedback_revision
      then
        raise exception 'registration_observation_stale_revision'
          using errcode = '40001';
      end if;
      if v_reason is null then
        raise exception 'registration_observation_correction_reason_required'
          using errcode = '22023';
      end if;
      if exists (
        select 1
        from public.ops_registration_observations later
        where later.track_id = v_track.id
          and (
            later.created_at > v_decision_observation.created_at
            or (
              later.created_at = v_decision_observation.created_at
              and later.id > v_decision_observation.id
            )
          )
          and not (
            later.decision_kind is null
            and later.status = 'canceled'
          )
      ) then
        raise exception 'registration_observation_transition_rejected'
          using errcode = '55000';
      end if;

      v_is_correction := true;
      v_observation_revision_before := v_decision_observation.revision;
      v_decision_before := v_decision_observation.decision_kind;
      update public.ops_registration_observations observation
      set decision_kind = v_target_decision,
          decided_by = v_actor,
          decided_at = pg_catalog.now(),
          revision = observation.revision + 1,
          updated_by = v_actor,
          updated_at = pg_catalog.now()
      where observation.id = v_decision_observation.id
      returning observation.* into v_decision_observation;
    elsif p_decision_observation_id is not null
      or p_expected_decision_observation_revision is not null
      or p_expected_decision_feedback_revision is not null
    then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;
  end if;

  v_source_status := v_track.workflow_status;
  v_workflow_revision_before := v_track.workflow_revision;
  update public.ops_registration_subject_tracks track
  set workflow_status = v_target_status,
      workflow_revision = track.workflow_revision + 1,
      workflow_status_entered_at = pg_catalog.now(),
      observation_return_workflow_status = null,
      updated_at = pg_catalog.now()
  where track.id = v_track.id
  returning track.* into v_track;

  v_metadata := pg_catalog.jsonb_build_object(
    'trackId', v_track.id,
    'decisionObservationId', case
      when v_is_correction then v_decision_observation.id
      else null
    end,
    'workflowRevisionBefore', v_workflow_revision_before,
    'workflowRevisionAfter', v_track.workflow_revision,
    'exitKind', v_exit_kind,
    'targetWorkflowStatus', v_target_status
  );
  if v_is_correction then
    v_metadata := v_metadata || pg_catalog.jsonb_build_object(
      'observationRevisionBefore', v_observation_revision_before,
      'observationRevisionAfter', v_decision_observation.revision,
      'beforeDecision', v_decision_before,
      'afterDecision', v_decision_observation.decision_kind,
      'reason', v_reason
    );
  end if;
  perform dashboard_private.write_registration_track_event_v2(
    v_track.task_id,
    v_track.id,
    'registration_observation_withdrawn',
    v_source_status,
    v_track.workflow_status,
    null,
    v_metadata,
    'user',
    null
  );

  if v_is_correction then
    v_response := dashboard_private.registration_observation_response_v1(
      'withdraw', p_request_key, v_track,
      v_decision_observation, v_decision_appointment, true
    );
  else
    v_response := dashboard_private.registration_observation_response_v1(
      'withdraw', p_request_key, v_track, null, null, true
    );
  end if;
  insert into dashboard_private.registration_observation_mutation_requests(
    actor_profile_id, operation, request_key, track_id,
    request_fingerprint, response_payload
  ) values (
    v_actor, 'withdraw', p_request_key, v_track.id,
    v_fingerprint, v_response
  );
  return v_response;
end;
$$;
create or replace function dashboard_private.set_registration_workflow_status_v1_impl(
  p_track_id uuid,
  p_workflow_status text,
  p_expected_workflow_revision integer,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_request_key text := nullif(pg_catalog.btrim(p_request_key), '');
  v_workflow_status text := nullif(pg_catalog.btrim(p_workflow_status), '');
  v_track public.ops_registration_subject_tracks%rowtype;
  v_target_fingerprint jsonb;
  v_response jsonb;
  v_receipt_matches boolean;
  v_receipt_found boolean := false;
  v_status_changed boolean;
  v_previous_workflow_status text;
begin
  if v_actor_id is null then
    raise exception 'registration_access_denied' using errcode = '42501';
  end if;
  if v_request_key is null then
    raise exception 'request_key_required' using errcode = '22023';
  end if;
  if p_expected_workflow_revision is null or p_expected_workflow_revision < 1 then
    raise exception 'registration_workflow_revision_invalid' using errcode = '22023';
  end if;
  if v_workflow_status in (
    'observation_requested',
    'observation_feedback_pending',
    'observation_completed'
  ) then
    raise exception 'registration_observation_transition_requires_action'
      using errcode = '55000';
  end if;
  if v_workflow_status not in (
    'inquiry',
    'level_test_requested',
    'consultation_requested',
    'consultation_completed',
    'waiting_current_class',
    'waiting_new_class',
    'waiting_next_opening',
    'enrollment_requested',
    'payment_in_progress',
    'registered',
    'not_registered',
    'inquiry_only'
  ) then
    raise exception 'registration_workflow_status_invalid' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor_id::text || ':' || v_request_key, 0)
  );

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = p_track_id
  for update;
  if not found then
    raise exception 'registration_track_not_found' using errcode = 'P0002';
  end if;

  perform dashboard_private.assert_registration_workflow_status_access(
    v_track.id,
    v_workflow_status
  );

  v_target_fingerprint := pg_catalog.jsonb_build_object(
    'trackId', v_track.id,
    'workflowStatus', v_workflow_status,
    'expectedWorkflowRevision', p_expected_workflow_revision
  );
  select
    mutation.response_payload,
    mutation.task_id = v_track.task_id
      and mutation.mutation_type = 'set_workflow_status'
      and mutation.target_fingerprint = v_target_fingerprint
  into v_response, v_receipt_matches
  from dashboard_private.ops_registration_mutations mutation
  where mutation.actor_id = v_actor_id
    and mutation.request_key = v_request_key;
  v_receipt_found := found;
  if v_receipt_found and not v_receipt_matches then
    raise exception 'idempotency_key_reused' using errcode = '22023';
  end if;
  if v_receipt_found then
    return v_response;
  end if;

  if v_track.workflow_status in (
    'observation_requested',
    'observation_feedback_pending',
    'observation_completed'
  ) or exists (
    select 1
    from public.ops_registration_observations observation
    where observation.track_id = v_track.id
      and observation.decision_kind is null
      and observation.status in (
        'scheduled', 'attended_feedback_pending', 'completed', 'no_show'
      )
  ) then
    raise exception 'registration_observation_transition_requires_action'
      using errcode = '55000';
  end if;

  if v_track.workflow_revision <> p_expected_workflow_revision then
    raise exception 'registration_workflow_status_refresh_required' using errcode = '40001';
  end if;

  v_status_changed := v_track.workflow_status is distinct from v_workflow_status;
  if v_status_changed then
    v_previous_workflow_status := v_track.workflow_status;
    update public.ops_registration_subject_tracks track
    set workflow_status = v_workflow_status,
        workflow_revision = track.workflow_revision + 1,
        workflow_status_entered_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where track.id = v_track.id
    returning track.* into v_track;

    perform dashboard_private.write_registration_track_event_v2(
      v_track.task_id,
      v_track.id,
      'registration_workflow_status_changed',
      v_previous_workflow_status,
      v_workflow_status,
      'manual_status_change',
      pg_catalog.jsonb_build_object(
        'workflowStatus', v_workflow_status,
        'workflowRevision', v_track.workflow_revision
      ),
      'user',
      null
    );
  end if;

  v_response := pg_catalog.jsonb_build_object(
    'trackId', v_track.id,
    'workflowStatus', v_track.workflow_status,
    'workflowRevision', v_track.workflow_revision,
    'workflowStatusEnteredAt', v_track.workflow_status_entered_at
  );

  insert into dashboard_private.ops_registration_mutations(
    actor_id, request_key, task_id, mutation_type,
    target_fingerprint, response_payload
  ) values (
    v_actor_id,
    v_request_key,
    v_track.task_id,
    'set_workflow_status',
    v_target_fingerprint,
    v_response
  );
  return v_response;
end;
$$;
create or replace function public.enter_registration_observation_v1(
