  to authenticated;
create or replace function dashboard_private.list_registration_observation_sessions_v1_impl(
  p_track_id uuid,
  p_class_id uuid,
  p_date_from date,
  p_date_to date
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_track public.ops_registration_subject_tracks%rowtype;
  v_class public.classes%rowtype;
  v_sessions jsonb;
  v_textbooks jsonb;
  v_legacy_invalid boolean := false;
  v_time_ambiguous boolean := false;
  v_session_invalid boolean := false;
  v_result jsonb;
begin
  v_track := dashboard_private.assert_registration_observation_manager_access_v1(
    p_track_id
  );
  if p_class_id is null
    or p_date_from is null
    or p_date_to is null
    or p_date_from < current_date
    or p_date_to < p_date_from
    or p_date_to - p_date_from > 120
  then
    raise exception 'registration_observation_date_range_invalid'
      using errcode = '22023';
  end if;

  select class.*
  into v_class
  from public.classes class
  where class.id = p_class_id
    and class.subject = v_track.subject
    and class.closed_at is null;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  if v_class.schedule_storage_mode = 'normalized'
    and public.continuous_class_schedule_runtime_version() = 1
  then
    with candidates as materialized (
      select
        lesson.id,
        lesson.session_date,
        lesson.start_time
      from public.class_lesson_sessions lesson
      where lesson.class_id = p_class_id
        and lesson.session_date between p_date_from and p_date_to
        and lesson.schedule_state in ('active', 'makeup')
        and lesson.start_time is not null
        and lesson.end_time is not null
        and lesson.start_time < lesson.end_time
        and (lesson.session_date + lesson.start_time) at time zone 'Asia/Seoul'
          > pg_catalog.now()
      order by lesson.session_date, lesson.start_time, lesson.id
      limit 240
    ),
    resolved as materialized (
      select
        candidate.session_date,
        candidate.start_time,
        candidate.id,
        dashboard_private.resolve_registration_observation_session_v1(
          p_track_id,
          p_class_id,
          'normalized',
          candidate.id,
          null
        ) as payload
      from candidates candidate
    )
    select coalesce(
      pg_catalog.jsonb_agg(
        resolved.payload
        order by resolved.session_date, resolved.start_time, resolved.id
      ),
      '[]'::jsonb
    )
    into v_result
    from resolved;
  elsif v_class.schedule_storage_mode in ('legacy', 'shadow') then
    v_sessions := case
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'sessions') = 'array'
        then v_class.schedule_plan -> 'sessions'
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'session_list') = 'array'
        then v_class.schedule_plan -> 'session_list'
      else '[]'::jsonb
    end;
    v_textbooks := case
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'textbooks') = 'array'
        then v_class.schedule_plan -> 'textbooks'
      else '[]'::jsonb
    end;

    with source_sessions as materialized (
      select session.value, session.ordinality
      from pg_catalog.jsonb_array_elements(v_sessions)
        with ordinality session(value, ordinality)
    ),
    canonical as materialized (
      select
        source.value,
        source.ordinality,
        coalesce(
          nullif(pg_catalog.btrim(source.value ->> 'sessionKey'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'session_key'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'id'), '')
        ) as session_key,
        coalesce(
          nullif(pg_catalog.btrim(source.value ->> 'date'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'sessionDate'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'session_date'), '')
        ) as session_date_text,
        case pg_catalog.lower(coalesce(
          nullif(pg_catalog.btrim(source.value ->> 'scheduleState'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'schedule_state'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'state'), ''),
          'active'
        ))
          when 'normal' then 'active'
          else pg_catalog.lower(coalesce(
            nullif(pg_catalog.btrim(source.value ->> 'scheduleState'), ''),
            nullif(pg_catalog.btrim(source.value ->> 'schedule_state'), ''),
            nullif(pg_catalog.btrim(source.value ->> 'state'), ''),
            'active'
          ))
        end as schedule_state
      from source_sessions source
    ),
    duplicate_keys as materialized (
      select canonical.session_key
      from canonical
      where canonical.session_key is not null
      group by canonical.session_key having count(*) > 1
    ),
    validation as materialized (
      select
        exists(select 1 from canonical where canonical.session_key is null)
        or exists(select 1 from duplicate_keys) as legacy_invalid
    ),
    dated as materialized (
      select
        canonical.value,
        canonical.ordinality,
        canonical.session_key,
        canonical.schedule_state,
        case
          when canonical.session_date_text ~ '^\d{4}-\d{2}-\d{2}$'
            then canonical.session_date_text::date
          else null
        end as session_date
      from canonical
      where canonical.session_key is not null
        and canonical.schedule_state in ('active', 'makeup')
    ),
    candidates as materialized (
      select
        dated.*,
        slot_fact.slot_count,
        slot_fact.start_time,
        slot_fact.end_time,
        slot_fact.teacher_catalog_id,
        slot_fact.teacher_name,
        slot_fact.classroom_catalog_id,
        slot_fact.classroom_name
      from dated
      cross join lateral (
        select
          pg_catalog.count(*)::integer as slot_count,
          pg_catalog.min(slot.start_time) as start_time,
          pg_catalog.min(slot.end_time) as end_time,
          (pg_catalog.array_agg(slot.teacher_catalog_id order by slot.sort_order, slot.id))[1]
            as teacher_catalog_id,
          (pg_catalog.array_agg(slot.teacher_name order by slot.sort_order, slot.id))[1]
            as teacher_name,
          (pg_catalog.array_agg(slot.classroom_catalog_id order by slot.sort_order, slot.id))[1]
            as classroom_catalog_id,
          (pg_catalog.array_agg(slot.classroom_name order by slot.sort_order, slot.id))[1]
            as classroom_name
        from public.class_schedule_slots slot
        where slot.class_id = p_class_id
          and slot.weekday = extract(dow from dated.session_date)::smallint
      ) slot_fact
      cross join validation
      where not validation.legacy_invalid
        and dated.session_date between p_date_from and p_date_to
        and (
          slot_fact.slot_count <> 1
          or (dated.session_date + slot_fact.start_time) at time zone 'Asia/Seoul'
            > pg_catalog.now()
        )
      order by dated.session_date, dated.session_key
      limit 240
    ),
    parsed as materialized (
      select
        candidate.*,
        nullif(pg_catalog.btrim(coalesce(
          candidate.value ->> 'teacherCatalogId',
          candidate.value ->> 'teacher_catalog_id'
        )), '') as teacher_catalog_text,
        nullif(pg_catalog.btrim(coalesce(
          candidate.value ->> 'classroomCatalogId',
          candidate.value ->> 'classroom_catalog_id'
        )), '') as classroom_catalog_text,
        coalesce(
          nullif(pg_catalog.btrim(candidate.value ->> 'teacherName'), ''),
          nullif(pg_catalog.btrim(candidate.value ->> 'teacher_name'), ''),
          nullif(pg_catalog.btrim(candidate.teacher_name), ''),
          nullif(pg_catalog.btrim(v_class.teacher), '')
        ) as teacher_name_fallback,
        coalesce(
          nullif(pg_catalog.btrim(candidate.value ->> 'classroomName'), ''),
          nullif(pg_catalog.btrim(candidate.value ->> 'classroom_name'), ''),
          nullif(pg_catalog.btrim(candidate.classroom_name), ''),
          nullif(pg_catalog.btrim(v_class.room), '')
        ) as classroom_name_fallback,
        case
          when pg_catalog.jsonb_typeof(candidate.value -> 'textbookEntries') = 'array'
            then candidate.value -> 'textbookEntries'
          else '[]'::jsonb
        end as textbook_entries
      from candidates candidate
    ),
    typed as materialized (
      select
        parsed.*,
        parsed.teacher_catalog_text is not null
          and parsed.teacher_catalog_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          as teacher_catalog_invalid,
        parsed.classroom_catalog_text is not null
          and parsed.classroom_catalog_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          as classroom_catalog_invalid,
        case
          when parsed.teacher_catalog_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then parsed.teacher_catalog_text::uuid
          else parsed.teacher_catalog_id
        end as resolved_teacher_catalog_id,
        case
          when parsed.classroom_catalog_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then parsed.classroom_catalog_text::uuid
          else parsed.classroom_catalog_id
        end as resolved_classroom_catalog_id
      from parsed
    ),
    catalogued as materialized (
      select
        typed.*,
        teacher_pick.match_count as teacher_match_count,
        teacher.id as selected_teacher_catalog_id,
        teacher.profile_id as selected_teacher_profile_id,
        teacher.name as selected_teacher_name,
        classroom_pick.match_count as classroom_match_count,
        classroom.id as selected_classroom_catalog_id,
        classroom.name as selected_classroom_name,
        classroom.campus as selected_campus
      from typed
      left join lateral (
        select
          pg_catalog.count(*)::integer as match_count,
          pg_catalog.min(teacher.id::text)::uuid as selected_id
        from public.teacher_catalogs teacher
        where teacher.is_visible = true
          and teacher.profile_id is not null
          and (
            pg_catalog.cardinality(teacher.subjects) = 0
            or v_track.subject = any(teacher.subjects)
          )
          and (
            (typed.resolved_teacher_catalog_id is not null
              and teacher.id = typed.resolved_teacher_catalog_id)
            or
            (typed.resolved_teacher_catalog_id is null
              and pg_catalog.lower(teacher.name)
                = pg_catalog.lower(typed.teacher_name_fallback))
          )
      ) teacher_pick on true
      left join public.teacher_catalogs teacher
        on teacher.id = teacher_pick.selected_id
       and teacher_pick.match_count = 1
      left join lateral (
        select
          pg_catalog.count(*)::integer as match_count,
          pg_catalog.min(classroom.id::text)::uuid as selected_id
        from public.classroom_catalogs classroom
        where classroom.is_visible = true
          and classroom.campus in ('본관', '별관')
          and (
            pg_catalog.cardinality(classroom.subjects) = 0
            or v_track.subject = any(classroom.subjects)
          )
          and (
            (typed.resolved_classroom_catalog_id is not null
              and classroom.id = typed.resolved_classroom_catalog_id)
            or
            (typed.resolved_classroom_catalog_id is null
              and pg_catalog.lower(classroom.name)
                = pg_catalog.lower(typed.classroom_name_fallback))
          )
      ) classroom_pick on true
      left join public.classroom_catalogs classroom
        on classroom.id = classroom_pick.selected_id
       and classroom_pick.match_count = 1
    ),
    enriched as materialized (
      select
        catalogued.*,
        textbook_fact.output_textbooks,
        dashboard_private.continuous_class_schedule_content_hash_v1(
          pg_catalog.jsonb_build_object(
            'textbooks', coalesce((
              select pg_catalog.jsonb_agg(book.value order by book.ordinality)
              from pg_catalog.jsonb_array_elements(v_textbooks)
                with ordinality book(value, ordinality)
              where nullif(pg_catalog.btrim(book.value ->> 'textbookId'), '') in (
                select nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), '')
                from pg_catalog.jsonb_array_elements(catalogued.textbook_entries) entry(value)
              )
            ), '[]'::jsonb),
            'sessions', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
              'sessionKey', catalogued.session_key,
              'textbookEntries', catalogued.textbook_entries
            ))
          )
        ) as content_hash,
        coalesce(
          progress_fact.progress_value,
          nullif(pg_catalog.btrim(catalogued.value ->> 'publicNote'), ''),
          nullif(pg_catalog.btrim(catalogued.value ->> 'public_note'), ''),
          nullif(pg_catalog.btrim(catalogued.value ->> 'memo'), '')
        ) as progress_value
      from catalogued
      left join lateral (
        select coalesce(
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'textbookId', nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), ''),
              'title', coalesce(
                nullif(pg_catalog.btrim(book.value ->> 'title'), ''),
                nullif(pg_catalog.btrim(book.value ->> 'name'), ''),
                nullif(pg_catalog.btrim(entry.value ->> 'textbookTitle'), ''),
                '교재 ' || entry.ordinality::text
              ),
              'planLabel', coalesce(
                nullif(pg_catalog.btrim(entry.value -> 'plan' ->> 'label'), ''),
                nullif(pg_catalog.btrim(entry.value ->> 'planLabel'), ''),
                ''
              ),
              'memo', coalesce(
                nullif(pg_catalog.btrim(entry.value -> 'plan' ->> 'memo'), ''),
                nullif(pg_catalog.btrim(entry.value ->> 'memo'), ''),
                ''
              )
            )
            order by entry.ordinality
          ),
          '[]'::jsonb
        ) as output_textbooks
        from pg_catalog.jsonb_array_elements(catalogued.textbook_entries)
          with ordinality entry(value, ordinality)
        left join lateral (
          select source.value
          from pg_catalog.jsonb_array_elements(v_textbooks)
            with ordinality source(value, ordinality)
          where nullif(pg_catalog.btrim(source.value ->> 'textbookId'), '')
            = nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), '')
          order by source.ordinality
          limit 1
        ) book on true
      ) textbook_fact on true
      left join lateral (
        select nullif(pg_catalog.btrim(coalesce(
          nullif(progress.range_label, ''),
          nullif(progress.content, ''),
          nullif(progress.public_note, '')
        )), '') as progress_value
        from public.progress_logs progress
        where progress.class_id = p_class_id
          and progress.session_id = catalogued.session_key
        order by progress.updated_at desc nulls last, progress.id desc
        limit 1
      ) progress_fact on true
    ),
    resolved as materialized (
      select
        enriched.session_date,
        enriched.start_time,
        enriched.session_key,
        enriched.slot_count <> 1 as time_ambiguous,
        enriched.teacher_catalog_invalid
          or enriched.classroom_catalog_invalid as legacy_invalid,
        enriched.slot_count = 1
          and (
            enriched.start_time is null
            or enriched.end_time is null
            or enriched.start_time >= enriched.end_time
            or enriched.teacher_match_count <> 1
            or enriched.classroom_match_count <> 1
            or enriched.selected_teacher_catalog_id is null
            or not dashboard_private.notification_profile_is_active_v1(
              enriched.selected_teacher_profile_id
            )
            or enriched.selected_classroom_catalog_id is null
          ) as session_invalid,
        case
          when enriched.slot_count = 1
            and not enriched.teacher_catalog_invalid
            and not enriched.classroom_catalog_invalid
            and enriched.start_time is not null
            and enriched.end_time is not null
            and enriched.start_time < enriched.end_time
            and enriched.teacher_match_count = 1
            and enriched.classroom_match_count = 1
            and enriched.selected_teacher_catalog_id is not null
            and dashboard_private.notification_profile_is_active_v1(
              enriched.selected_teacher_profile_id
            )
            and enriched.selected_classroom_catalog_id is not null
          then pg_catalog.jsonb_build_object(
            'classId', p_class_id,
            'subject', v_track.subject,
            'sessionAuthority', 'legacy',
            'classLessonSessionId', null,
            'legacySessionKey', enriched.session_key,
            'sessionKey', enriched.session_key,
            'scheduleState', enriched.schedule_state,
            'sessionDate', enriched.session_date,
            'startsAt', (enriched.session_date + enriched.start_time) at time zone 'Asia/Seoul',
            'endsAt', (enriched.session_date + enriched.end_time) at time zone 'Asia/Seoul',
            'sessionSourceRevision', null,
            'legacySessionSourceHash', enriched.content_hash,
            'sourceRevision', pg_catalog.jsonb_build_object(
              'authority', 'legacy',
              'sessionKey', enriched.session_key,
              'contentHash', enriched.content_hash
            ),
            'teacherCatalogId', enriched.selected_teacher_catalog_id,
            'teacherProfileId', enriched.selected_teacher_profile_id,
            'teacherName', enriched.selected_teacher_name,
            'classroomCatalogId', enriched.selected_classroom_catalog_id,
            'classroomName', enriched.selected_classroom_name,
            'campus', enriched.selected_campus,
            'className', v_class.name,
            'textbooks', enriched.output_textbooks,
            'progress', case when enriched.progress_value is null
              then '진도: 미입력'
              else '진도: ' || enriched.progress_value
            end,
            'bookingFactHash', dashboard_private.registration_observation_booking_fact_hash_v1(
              pg_catalog.jsonb_build_object(
                'classId', p_class_id,
                'subject', v_track.subject,
                'sessionAuthority', 'legacy',
                'classLessonSessionId', null,
                'legacySessionKey', enriched.session_key,
                'sessionKey', enriched.session_key,
                'scheduleState', enriched.schedule_state,
                'sessionDate', enriched.session_date,
                'startsAt', (enriched.session_date + enriched.start_time) at time zone 'Asia/Seoul',
                'endsAt', (enriched.session_date + enriched.end_time) at time zone 'Asia/Seoul',
                'teacherCatalogId', enriched.selected_teacher_catalog_id,
                'teacherProfileId', enriched.selected_teacher_profile_id,
                'teacherName', enriched.selected_teacher_name,
                'classroomCatalogId', enriched.selected_classroom_catalog_id,
                'classroomName', enriched.selected_classroom_name,
                'campus', enriched.selected_campus
              )
            )
          )
          else null
        end as payload
      from enriched
    )
    select
      validation.legacy_invalid
        or coalesce(pg_catalog.bool_or(resolved.legacy_invalid), false),
      coalesce(pg_catalog.bool_or(resolved.time_ambiguous), false),
      coalesce(pg_catalog.bool_or(resolved.session_invalid), false),
      coalesce(
        pg_catalog.jsonb_agg(
          resolved.payload
          order by resolved.session_date, resolved.start_time, resolved.session_key
        ) filter (where resolved.payload is not null),
        '[]'::jsonb
      )
    into
      v_legacy_invalid,
      v_time_ambiguous,
      v_session_invalid,
      v_result
    from validation
    left join resolved on not validation.legacy_invalid
    group by validation.legacy_invalid;

    if v_legacy_invalid then
      raise exception 'registration_observation_legacy_session_invalid'
        using errcode = '22023';
    end if;
    if v_time_ambiguous then
      raise exception 'registration_observation_session_time_ambiguous'
        using errcode = '22023';
    end if;
    if v_session_invalid then
      raise exception 'registration_observation_session_invalid'
        using errcode = '22023';
    end if;
  else
    raise exception 'registration_observation_session_invalid'
      using errcode = '22023';
  end if;

  return v_result;
end;
$$;
alter function dashboard_private.list_registration_observation_sessions_v1_impl(uuid, uuid, date, date)
  owner to postgres;
revoke all on function dashboard_private.list_registration_observation_sessions_v1_impl(uuid, uuid, date, date)
  from public, anon, authenticated, service_role;
grant execute on function dashboard_private.list_registration_observation_sessions_v1_impl(uuid, uuid, date, date)
  to authenticated;
create or replace function dashboard_private.get_registration_observation_manager_detail_v1_impl(
  p_track_id uuid,
  p_attempt_limit integer default 20
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_result jsonb;
begin
  with manager_rows as materialized (
    select *
    from dashboard_private.registration_observation_manager_detail_rows_v1(
      p_track_id,
      p_attempt_limit
    )
  ),
  latest_decision_row(
    row_kind,
    payload,
    sort_created_at,
    sort_id,
    sort_name
  ) as materialized (
    select
      'latest_decision'::text,
      pg_catalog.jsonb_build_object(
        'observationId', observation.id,
        'decisionKind', observation.decision_kind,
        'observationRevision', observation.revision,
        'feedbackRevision', observation.feedback_revision
      ),
      observation.created_at,
      observation.id,
      null::text
    from public.ops_registration_observations observation
    where observation.track_id = p_track_id
      and observation.decision_kind is not null
    order by observation.created_at desc, observation.id desc
    limit 1
  ),
  shared_rows as materialized (
    select * from manager_rows
    union all
    select * from latest_decision_row
  )
  select pg_catalog.jsonb_build_object(
    'track', (
      select row.payload
      from shared_rows row
      where row.row_kind = 'track'
      limit 1
    ),
    'currentObservation', (
      select row.payload
      from shared_rows row
      where row.row_kind = 'current'
      limit 1
    ),
    'latestEnrollmentDecisionObservationId', (
      select row.payload
      from shared_rows row
      where row.row_kind = 'latest_enrollment'
      limit 1
    ),
    'latestDecisionObservation', (
      select row.payload
      from shared_rows row
      where row.row_kind = 'latest_decision'
      limit 1
    ),
    'attempts', coalesce((
      select pg_catalog.jsonb_agg(
        row.payload
        order by row.sort_created_at desc, row.sort_id desc
      )
      from shared_rows row
      where row.row_kind = 'attempt'
    ), '[]'::jsonb),
    'classes', coalesce((
      select pg_catalog.jsonb_agg(
        row.payload
        order by row.sort_name, row.sort_id
      )
      from shared_rows row
      where row.row_kind = 'class'
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;
alter function dashboard_private.get_registration_observation_manager_detail_v1_impl(uuid, integer)
  owner to postgres;
revoke all on function dashboard_private.get_registration_observation_manager_detail_v1_impl(uuid, integer)
  from public, anon, authenticated, service_role;
grant execute on function dashboard_private.get_registration_observation_manager_detail_v1_impl(uuid, integer)
  to authenticated;
commit;
begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
create or replace function dashboard_private.list_registration_observation_sessions_v1_impl(
  p_track_id uuid,
  p_class_id uuid,
  p_date_from date,
  p_date_to date
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_track public.ops_registration_subject_tracks%rowtype;
  v_class public.classes%rowtype;
  v_sessions jsonb;
  v_textbooks jsonb;
  v_legacy_invalid boolean := false;
  v_time_ambiguous boolean := false;
  v_session_invalid boolean := false;
  v_result jsonb;
begin
  v_track := dashboard_private.assert_registration_observation_manager_access_v1(
    p_track_id
  );
  if p_class_id is null
    or p_date_from is null
    or p_date_to is null
    or p_date_from < current_date
    or p_date_to < p_date_from
    or p_date_to - p_date_from > 120
  then
    raise exception 'registration_observation_date_range_invalid'
      using errcode = '22023';
  end if;

  select class.*
  into v_class
  from public.classes class
  where class.id = p_class_id
    and class.subject = v_track.subject
    and class.closed_at is null;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  if v_class.schedule_storage_mode = 'normalized'
    and public.continuous_class_schedule_runtime_version() = 1
  then
    with candidates as materialized (
      select
        lesson.id,
        lesson.session_date,
        lesson.start_time
      from public.class_lesson_sessions lesson
      where lesson.class_id = p_class_id
        and lesson.session_date between p_date_from and p_date_to
        and lesson.schedule_state in ('active', 'makeup')
        and lesson.start_time is not null
        and lesson.end_time is not null
        and lesson.start_time < lesson.end_time
        and (lesson.session_date + lesson.start_time) at time zone 'Asia/Seoul'
          > pg_catalog.now()
      order by lesson.session_date, lesson.start_time, lesson.id
      limit 240
    ),
    resolved as materialized (
      select
        candidate.session_date,
        candidate.start_time,
        candidate.id,
        dashboard_private.resolve_registration_observation_session_v1(
          p_track_id,
          p_class_id,
          'normalized',
          candidate.id,
          null
        ) as payload
      from candidates candidate
    )
    select coalesce(
      pg_catalog.jsonb_agg(
        resolved.payload
        order by resolved.session_date, resolved.start_time, resolved.id
      ),
      '[]'::jsonb
    )
    into v_result
    from resolved;
  elsif v_class.schedule_storage_mode in ('legacy', 'shadow') then
    v_sessions := case
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'sessions') = 'array'
        then v_class.schedule_plan -> 'sessions'
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'session_list') = 'array'
        then v_class.schedule_plan -> 'session_list'
      else '[]'::jsonb
    end;
    v_textbooks := case
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'textbooks') = 'array'
        then v_class.schedule_plan -> 'textbooks'
      else '[]'::jsonb
    end;

    with source_sessions as materialized (
      select session.value, session.ordinality
      from pg_catalog.jsonb_array_elements(v_sessions)
        with ordinality session(value, ordinality)
    ),
    canonical as materialized (
      select
        source.value,
        source.ordinality,
        coalesce(
          nullif(pg_catalog.btrim(source.value ->> 'sessionKey'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'session_key'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'id'), '')
        ) as session_key,
        coalesce(
          nullif(pg_catalog.btrim(source.value ->> 'date'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'sessionDate'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'session_date'), '')
        ) as session_date_text,
        case pg_catalog.lower(coalesce(
          nullif(pg_catalog.btrim(source.value ->> 'scheduleState'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'schedule_state'), ''),
          nullif(pg_catalog.btrim(source.value ->> 'state'), ''),
          'active'
        ))
          when 'normal' then 'active'
          else pg_catalog.lower(coalesce(
            nullif(pg_catalog.btrim(source.value ->> 'scheduleState'), ''),
            nullif(pg_catalog.btrim(source.value ->> 'schedule_state'), ''),
            nullif(pg_catalog.btrim(source.value ->> 'state'), ''),
            'active'
          ))
        end as schedule_state
      from source_sessions source
    ),
    duplicate_keys as materialized (
      select canonical.session_key
      from canonical
      where canonical.session_key is not null
      group by canonical.session_key having count(*) > 1
    ),
    validation as materialized (
      select
        exists(select 1 from canonical where canonical.session_key is null)
        or exists(select 1 from duplicate_keys) as legacy_invalid
    ),
    dated as materialized (
      select
        canonical.value,
        canonical.ordinality,
        canonical.session_key,
        canonical.schedule_state,
        case
          when canonical.session_date_text ~ '^\d{4}-\d{2}-\d{2}$'
            then canonical.session_date_text::date
          else null
        end as session_date
      from canonical
      where canonical.session_key is not null
        and canonical.schedule_state in ('active', 'makeup')
    ),
    candidates as materialized (
      select
        dated.*,
        slot_fact.slot_count,
        slot_fact.start_time,
        slot_fact.end_time,
        slot_fact.teacher_catalog_id,
        slot_fact.teacher_name,
        slot_fact.classroom_catalog_id,
        slot_fact.classroom_name
      from dated
      cross join lateral (
        select
          pg_catalog.count(*)::integer as slot_count,
          pg_catalog.min(slot.start_time) as start_time,
          pg_catalog.min(slot.end_time) as end_time,
          (pg_catalog.array_agg(slot.teacher_catalog_id order by slot.sort_order, slot.id))[1]
            as teacher_catalog_id,
          (pg_catalog.array_agg(slot.teacher_name order by slot.sort_order, slot.id))[1]
            as teacher_name,
          (pg_catalog.array_agg(slot.classroom_catalog_id order by slot.sort_order, slot.id))[1]
            as classroom_catalog_id,
          (pg_catalog.array_agg(slot.classroom_name order by slot.sort_order, slot.id))[1]
            as classroom_name
        from public.class_schedule_slots slot
        where slot.class_id = p_class_id
          and slot.weekday = extract(dow from dated.session_date)::smallint
      ) slot_fact
      cross join validation
      where not validation.legacy_invalid
        and dated.session_date between p_date_from and p_date_to
        and (
          slot_fact.slot_count <> 1
          or (dated.session_date + slot_fact.start_time) at time zone 'Asia/Seoul'
            > pg_catalog.now()
        )
      order by dated.session_date, dated.session_key
      limit 240
    ),
    parsed as materialized (
      select
        candidate.*,
        coalesce(
          nullif(pg_catalog.btrim(candidate.value ->> 'teacherCatalogId'), ''),
          nullif(pg_catalog.btrim(candidate.value ->> 'teacher_catalog_id'), '')
        ) as teacher_catalog_text,
        coalesce(
          nullif(pg_catalog.btrim(candidate.value ->> 'classroomCatalogId'), ''),
          nullif(pg_catalog.btrim(candidate.value ->> 'classroom_catalog_id'), '')
        ) as classroom_catalog_text,
        coalesce(
          nullif(pg_catalog.btrim(candidate.value ->> 'teacherName'), ''),
          nullif(pg_catalog.btrim(candidate.value ->> 'teacher_name'), ''),
          nullif(pg_catalog.btrim(candidate.teacher_name), ''),
          nullif(pg_catalog.btrim(v_class.teacher), '')
        ) as teacher_name_fallback,
        coalesce(
          nullif(pg_catalog.btrim(candidate.value ->> 'classroomName'), ''),
          nullif(pg_catalog.btrim(candidate.value ->> 'classroom_name'), ''),
          nullif(pg_catalog.btrim(candidate.classroom_name), ''),
          nullif(pg_catalog.btrim(v_class.room), '')
        ) as classroom_name_fallback,
        case
          when pg_catalog.jsonb_typeof(candidate.value -> 'textbookEntries') = 'array'
            then candidate.value -> 'textbookEntries'
          else '[]'::jsonb
        end as textbook_entries
      from candidates candidate
    ),
    typed as materialized (
      select
        parsed.*,
        parsed.teacher_catalog_text is not null
          and parsed.teacher_catalog_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          as teacher_catalog_invalid,
        parsed.classroom_catalog_text is not null
          and parsed.classroom_catalog_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          as classroom_catalog_invalid,
        case
          when parsed.teacher_catalog_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then parsed.teacher_catalog_text::uuid
          else parsed.teacher_catalog_id
        end as resolved_teacher_catalog_id,
        case
          when parsed.classroom_catalog_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then parsed.classroom_catalog_text::uuid
          else parsed.classroom_catalog_id
        end as resolved_classroom_catalog_id
      from parsed
    ),
    catalogued as materialized (
      select
        typed.*,
        teacher_pick.match_count as teacher_match_count,
        teacher.id as selected_teacher_catalog_id,
        teacher.profile_id as selected_teacher_profile_id,
        teacher.name as selected_teacher_name,
        classroom_pick.match_count as classroom_match_count,
        classroom.id as selected_classroom_catalog_id,
        classroom.name as selected_classroom_name,
        classroom.campus as selected_campus
      from typed
      left join lateral (
        select
          pg_catalog.count(*)::integer as match_count,
          pg_catalog.min(teacher.id::text)::uuid as selected_id
        from public.teacher_catalogs teacher
        where teacher.is_visible = true
          and teacher.profile_id is not null
          and (
            pg_catalog.cardinality(teacher.subjects) = 0
            or v_track.subject = any(teacher.subjects)
          )
          and (
            (typed.resolved_teacher_catalog_id is not null
              and teacher.id = typed.resolved_teacher_catalog_id)
            or
            (typed.resolved_teacher_catalog_id is null
              and pg_catalog.lower(teacher.name)
                = pg_catalog.lower(typed.teacher_name_fallback))
          )
      ) teacher_pick on true
      left join public.teacher_catalogs teacher
        on teacher.id = teacher_pick.selected_id
       and teacher_pick.match_count = 1
      left join lateral (
        select
          pg_catalog.count(*)::integer as match_count,
          pg_catalog.min(classroom.id::text)::uuid as selected_id
        from public.classroom_catalogs classroom
        where classroom.is_visible = true
          and classroom.campus in ('본관', '별관')
          and (
            pg_catalog.cardinality(classroom.subjects) = 0
            or v_track.subject = any(classroom.subjects)
          )
          and (
            (typed.resolved_classroom_catalog_id is not null
              and classroom.id = typed.resolved_classroom_catalog_id)
            or
            (typed.resolved_classroom_catalog_id is null
              and pg_catalog.lower(classroom.name)
                = pg_catalog.lower(typed.classroom_name_fallback))
          )
      ) classroom_pick on true
      left join public.classroom_catalogs classroom
        on classroom.id = classroom_pick.selected_id
       and classroom_pick.match_count = 1
    ),
    enriched as materialized (
      select
        catalogued.*,
        textbook_fact.output_textbooks,
        dashboard_private.continuous_class_schedule_content_hash_v1(
          pg_catalog.jsonb_build_object(
            'textbooks', coalesce((
              select pg_catalog.jsonb_agg(book.value order by book.ordinality)
              from pg_catalog.jsonb_array_elements(v_textbooks)
                with ordinality book(value, ordinality)
              where nullif(pg_catalog.btrim(book.value ->> 'textbookId'), '') in (
                select nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), '')
                from pg_catalog.jsonb_array_elements(catalogued.textbook_entries) entry(value)
              )
            ), '[]'::jsonb),
            'sessions', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
              'sessionKey', catalogued.session_key,
              'textbookEntries', catalogued.textbook_entries
            ))
          )
        ) as content_hash,
        coalesce(
          progress_fact.progress_value,
          nullif(pg_catalog.btrim(catalogued.value ->> 'publicNote'), ''),
          nullif(pg_catalog.btrim(catalogued.value ->> 'public_note'), ''),
          nullif(pg_catalog.btrim(catalogued.value ->> 'memo'), '')
        ) as progress_value
      from catalogued
      left join lateral (
        select coalesce(
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'textbookId', nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), ''),
              'title', coalesce(
                nullif(pg_catalog.btrim(book.value ->> 'title'), ''),
                nullif(pg_catalog.btrim(book.value ->> 'name'), ''),
                nullif(pg_catalog.btrim(entry.value ->> 'textbookTitle'), ''),
                '교재 ' || entry.ordinality::text
              ),
              'planLabel', coalesce(
                nullif(pg_catalog.btrim(entry.value -> 'plan' ->> 'label'), ''),
                nullif(pg_catalog.btrim(entry.value ->> 'planLabel'), ''),
                ''
              ),
              'memo', coalesce(
                nullif(pg_catalog.btrim(entry.value -> 'plan' ->> 'memo'), ''),
                nullif(pg_catalog.btrim(entry.value ->> 'memo'), ''),
                ''
              )
            )
            order by entry.ordinality
          ),
          '[]'::jsonb
        ) as output_textbooks
        from pg_catalog.jsonb_array_elements(catalogued.textbook_entries)
          with ordinality entry(value, ordinality)
        left join lateral (
          select source.value
          from pg_catalog.jsonb_array_elements(v_textbooks)
            with ordinality source(value, ordinality)
          where nullif(pg_catalog.btrim(source.value ->> 'textbookId'), '')
            = nullif(pg_catalog.btrim(entry.value ->> 'textbookId'), '')
          order by source.ordinality
          limit 1
        ) book on true
      ) textbook_fact on true
      left join lateral (
        select nullif(pg_catalog.btrim(coalesce(
          nullif(progress.range_label, ''),
          nullif(progress.content, ''),
          nullif(progress.public_note, '')
        )), '') as progress_value
        from public.progress_logs progress
        where progress.class_id = p_class_id
          and progress.session_id = catalogued.session_key
        order by progress.updated_at desc nulls last, progress.id desc
        limit 1
      ) progress_fact on true
    ),
    resolved as materialized (
      select
        enriched.session_date,
        enriched.start_time,
        enriched.session_key,
        enriched.slot_count <> 1 as time_ambiguous,
        enriched.teacher_catalog_invalid
          or enriched.classroom_catalog_invalid as legacy_invalid,
        enriched.slot_count = 1
          and (
            enriched.start_time is null
            or enriched.end_time is null
            or enriched.start_time >= enriched.end_time
            or enriched.teacher_match_count <> 1
            or enriched.classroom_match_count <> 1
            or enriched.selected_teacher_catalog_id is null
            or not dashboard_private.notification_profile_is_active_v1(
              enriched.selected_teacher_profile_id
            )
            or enriched.selected_classroom_catalog_id is null
          ) as session_invalid,
        case
          when enriched.slot_count = 1
            and not enriched.teacher_catalog_invalid
            and not enriched.classroom_catalog_invalid
            and enriched.start_time is not null
            and enriched.end_time is not null
            and enriched.start_time < enriched.end_time
            and enriched.teacher_match_count = 1
            and enriched.classroom_match_count = 1
            and enriched.selected_teacher_catalog_id is not null
            and dashboard_private.notification_profile_is_active_v1(
              enriched.selected_teacher_profile_id
            )
            and enriched.selected_classroom_catalog_id is not null
          then pg_catalog.jsonb_build_object(
            'classId', p_class_id,
            'subject', v_track.subject,
            'sessionAuthority', 'legacy',
            'classLessonSessionId', null,
            'legacySessionKey', enriched.session_key,
            'sessionKey', enriched.session_key,
            'scheduleState', enriched.schedule_state,
            'sessionDate', enriched.session_date,
            'startsAt', (enriched.session_date + enriched.start_time) at time zone 'Asia/Seoul',
            'endsAt', (enriched.session_date + enriched.end_time) at time zone 'Asia/Seoul',
            'sessionSourceRevision', null,
            'legacySessionSourceHash', enriched.content_hash,
            'sourceRevision', pg_catalog.jsonb_build_object(
              'authority', 'legacy',
              'sessionKey', enriched.session_key,
              'contentHash', enriched.content_hash
            ),
            'teacherCatalogId', enriched.selected_teacher_catalog_id,
            'teacherProfileId', enriched.selected_teacher_profile_id,
            'teacherName', enriched.selected_teacher_name,
            'classroomCatalogId', enriched.selected_classroom_catalog_id,
            'classroomName', enriched.selected_classroom_name,
            'campus', enriched.selected_campus,
            'className', v_class.name,
            'textbooks', enriched.output_textbooks,
            'progress', case when enriched.progress_value is null
              then '진도: 미입력'
              else '진도: ' || enriched.progress_value
            end,
            'bookingFactHash', dashboard_private.registration_observation_booking_fact_hash_v1(
              pg_catalog.jsonb_build_object(
                'classId', p_class_id,
                'subject', v_track.subject,
                'sessionAuthority', 'legacy',
                'classLessonSessionId', null,
                'legacySessionKey', enriched.session_key,
                'sessionKey', enriched.session_key,
                'scheduleState', enriched.schedule_state,
                'sessionDate', enriched.session_date,
                'startsAt', (enriched.session_date + enriched.start_time) at time zone 'Asia/Seoul',
                'endsAt', (enriched.session_date + enriched.end_time) at time zone 'Asia/Seoul',
                'teacherCatalogId', enriched.selected_teacher_catalog_id,
                'teacherProfileId', enriched.selected_teacher_profile_id,
                'teacherName', enriched.selected_teacher_name,
                'classroomCatalogId', enriched.selected_classroom_catalog_id,
                'classroomName', enriched.selected_classroom_name,
                'campus', enriched.selected_campus
              )
            )
          )
          else null
        end as payload
      from enriched
    )
    select
      validation.legacy_invalid
        or coalesce(pg_catalog.bool_or(resolved.legacy_invalid), false),
      coalesce(pg_catalog.bool_or(resolved.time_ambiguous), false),
      coalesce(pg_catalog.bool_or(resolved.session_invalid), false),
      coalesce(
        pg_catalog.jsonb_agg(
          resolved.payload
          order by resolved.session_date, resolved.start_time, resolved.session_key
        ) filter (where resolved.payload is not null),
        '[]'::jsonb
      )
    into
      v_legacy_invalid,
      v_time_ambiguous,
      v_session_invalid,
      v_result
    from validation
    left join resolved on not validation.legacy_invalid
    group by validation.legacy_invalid;

    if v_legacy_invalid then
      raise exception 'registration_observation_legacy_session_invalid'
        using errcode = '22023';
    end if;
    if v_time_ambiguous then
      raise exception 'registration_observation_session_time_ambiguous'
        using errcode = '22023';
    end if;
    if v_session_invalid then
      raise exception 'registration_observation_session_invalid'
        using errcode = '22023';
    end if;
  else
    raise exception 'registration_observation_session_invalid'
      using errcode = '22023';
  end if;

  return v_result;
end;
$$;
alter function dashboard_private.list_registration_observation_sessions_v1_impl(uuid, uuid, date, date)
  owner to postgres;
revoke all on function dashboard_private.list_registration_observation_sessions_v1_impl(uuid, uuid, date, date)
  from public, anon, authenticated, service_role;
grant execute on function dashboard_private.list_registration_observation_sessions_v1_impl(uuid, uuid, date, date)
  to authenticated;
commit;
begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
create function dashboard_private.assert_registration_observation_feedback_access_v1(
  p_observation_id uuid,
  p_access_kind text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_access jsonb;
begin
  if v_actor is null or p_access_kind is distinct from 'read' then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select pg_catalog.jsonb_build_object(
    'actorProfileId', actor.id,
    'accessKind', case
      when actor.role in ('admin', 'staff') then 'manager'
      when actor.id = observation.teacher_profile_id then 'assigned_teacher'
      else 'director'
    end
  )
  into v_access
  from public.ops_registration_observations observation
  join public.ops_registration_subject_tracks track
    on track.id = observation.track_id
   and track.task_id = observation.task_id
  join public.profiles actor
    on actor.id = v_actor
  join auth.users account
    on account.id = actor.id
   and account.deleted_at is null
   and (
     account.banned_until is null
     or account.banned_until <= pg_catalog.now()
   )
  where observation.id = p_observation_id
    and (
      actor.id = observation.teacher_profile_id
      or actor.role in ('admin', 'staff')
      or actor.id = track.director_profile_id
    )
  limit 1;

  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  return v_access;
end;
$$;
alter function dashboard_private.assert_registration_observation_feedback_access_v1(uuid, text) owner to postgres;
revoke all on function dashboard_private.assert_registration_observation_feedback_access_v1(uuid, text) from public, anon, authenticated, service_role;
create function dashboard_private.get_registration_observation_feedback_impl_v1(
  p_observation_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_result jsonb;
begin
  if v_actor is null
    or not exists (
      select 1
      from public.profiles actor
      join auth.users account
        on account.id = actor.id
       and account.deleted_at is null
       and (
         account.banned_until is null
         or account.banned_until <= pg_catalog.now()
       )
      where actor.id = v_actor
    )
  then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  perform dashboard_private.assert_registration_observation_feedback_access_v1(
    p_observation_id,
    'read'
  );

  select pg_catalog.jsonb_build_object(
    'observationId', observation.id,
    'taskId', observation.task_id,
    'trackId', observation.track_id,
    'appointmentId', observation.appointment_id,
    'studentName', task.student_name,
    'studentGrade', registration_detail.school_grade,
    'subject', observation.subject,
    'classId', observation.class_id,
    'className', observation.class_name_snapshot,
    'sessionAuthority', observation.session_authority,
    'sessionDate', observation.session_date,
    'sessionKey', case
      when observation.session_authority = 'normalized' then lesson.session_key
      else observation.legacy_session_key
    end,
    'classLessonSessionId', observation.class_lesson_session_id,
    'legacySessionKey', observation.legacy_session_key,
    'sourceRevision', observation.source_revision,
    'startsAt', observation.starts_at,
    'endsAt', observation.ends_at,
    'classroomName', observation.classroom_name_snapshot,
    'teacherName', observation.teacher_name_snapshot,
    'status', observation.status,
    'attendance', observation.attendance,
    'suitabilityResult', observation.suitability_result,
    'feedbackReason', observation.feedback_reason,
    'proxySubmitted', case
      when observation.feedback_submitted_by is null then false
      else observation.feedback_submitted_by <> observation.teacher_profile_id
    end,
    'feedbackSubmittedByName', feedback_submitter.name,
    'feedbackSubmittedAt', observation.feedback_submitted_at,
    'revision', observation.revision,
    'feedbackRevision', observation.feedback_revision,
    'appointmentNotificationRevision', appointment.notification_revision,
    'trackWorkflowRevision', track.workflow_revision,
    'decisionKind', observation.decision_kind
  )
  into v_result
  from public.ops_registration_observations observation
  join public.ops_registration_appointments appointment
    on appointment.id = observation.appointment_id
   and appointment.task_id = observation.task_id
   and appointment.kind = 'observation_class'
  join public.ops_registration_subject_tracks track
    on track.id = observation.track_id
   and track.task_id = observation.task_id
  join public.ops_tasks task
    on task.id = observation.task_id
   and task.type = 'registration'
  join public.ops_registration_details registration_detail
    on registration_detail.task_id = task.id
  join public.classes class
    on class.id = observation.class_id
   and class.subject = observation.subject
  join public.teacher_catalogs teacher
    on teacher.id = observation.teacher_catalog_id
  join public.profiles assigned_teacher
    on assigned_teacher.id = observation.teacher_profile_id
   and teacher.profile_id = assigned_teacher.id
  left join public.class_lesson_sessions lesson
    on lesson.id = observation.class_lesson_session_id
   and lesson.class_id = observation.class_id
  left join public.profiles feedback_submitter
    on feedback_submitter.id = observation.feedback_submitted_by
  left join auth.users feedback_submitter_account
    on feedback_submitter_account.id = feedback_submitter.id
   and feedback_submitter_account.deleted_at is null
   and (
     feedback_submitter_account.banned_until is null
     or feedback_submitter_account.banned_until <= pg_catalog.now()
   )
  where observation.id = p_observation_id
    and (
      (
        observation.session_authority = 'normalized'
        and nullif(pg_catalog.btrim(lesson.session_key), '') is not null
      )
      or (
        observation.session_authority = 'legacy'
        and lesson.id is null
        and nullif(pg_catalog.btrim(observation.legacy_session_key), '') is not null
      )
    )
    and (
      (
        observation.feedback_submitted_by is null
        and observation.feedback_submitted_at is null
      )
      or (
        observation.feedback_submitted_by is not null
        and observation.feedback_submitted_at is not null
        and feedback_submitter_account.id is not null
        and nullif(pg_catalog.btrim(feedback_submitter.name), '') is not null
      )
    );

  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;
alter function dashboard_private.get_registration_observation_feedback_impl_v1(uuid) owner to postgres;
revoke all on function dashboard_private.get_registration_observation_feedback_impl_v1(uuid) from public, anon, authenticated, service_role;
grant execute on function dashboard_private.get_registration_observation_feedback_impl_v1(uuid) to authenticated;
create function public.get_registration_observation_feedback_v1(p_observation_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select dashboard_private.get_registration_observation_feedback_impl_v1(
    p_observation_id
  );
$$;
alter function public.get_registration_observation_feedback_v1(uuid) owner to postgres;
revoke all on function public.get_registration_observation_feedback_v1(uuid) from public, anon, authenticated, service_role;
grant execute on function public.get_registration_observation_feedback_v1(uuid) to authenticated;
commit;
begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
create function dashboard_private.assert_registration_observation_current_session_v1(
  p_observation_id uuid,
  p_operation text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_actor uuid := dashboard_private.registration_observation_active_actor_v1();
  v_actor_role text;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_observation public.ops_registration_observations%rowtype;
  v_class public.classes%rowtype;
  v_lesson public.class_lesson_sessions%rowtype;
  v_slot public.class_schedule_slots%rowtype;
  v_teacher public.teacher_catalogs%rowtype;
  v_classroom public.classroom_catalogs%rowtype;
  v_sessions jsonb;
  v_selected_session jsonb := '{}'::jsonb;
  v_row record;
  v_row_key text;
  v_seen_keys text[] := array[]::text[];
  v_selected_count integer := 0;
  v_slot_count integer := 0;
  v_catalog_count integer := 0;
  v_session_key text;
  v_session_date date;
  v_schedule_state text;
  v_start_time time;
  v_end_time time;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_session_source_revision bigint;
  v_legacy_session_source_hash text;
  v_source_revision jsonb;
  v_teacher_catalog_id uuid;
  v_classroom_catalog_id uuid;
  v_teacher_name_fallback text;
  v_classroom_name_fallback text;
begin
  if p_observation_id is null
    or p_operation is null
    or p_operation not in ('record_attendance', 'submit_feedback')
  then
    raise exception 'registration_observation_session_source_dirty'
      using errcode = '55000';
  end if;

  select profile.role
  into v_actor_role
  from public.profiles profile
  where profile.id = v_actor;

  select observation.*
  into v_observation
  from public.ops_registration_observations observation
  where observation.id = p_observation_id;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = v_observation.track_id
    and track.task_id = v_observation.task_id;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  if p_operation = 'record_attendance' then
    if v_actor_role not in ('admin', 'staff') then
      raise exception 'registration_observation_attendance_access_denied'
        using errcode = '42501';
    end if;
  elsif not (
    v_actor_role in ('admin', 'staff')
    or (
      v_actor_role = 'teacher'
      and v_actor = v_observation.teacher_profile_id
    )
  ) then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select class.*
  into v_class
  from public.classes class
  where class.id = v_observation.class_id
    and class.subject = v_track.subject
    and class.closed_at is null
  for share;
  if not found then
    raise exception 'registration_observation_session_source_dirty'
      using errcode = '55000';
  end if;

  if v_observation.session_authority = 'normalized' then
    if public.continuous_class_schedule_runtime_version() <> 1
      or v_class.schedule_storage_mode <> 'normalized'
      or v_observation.class_lesson_session_id is null
      or v_observation.legacy_session_key is not null
    then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    select lesson.*
    into v_lesson
    from public.class_lesson_sessions lesson
    where lesson.id = v_observation.class_lesson_session_id
      and lesson.class_id = v_observation.class_id
    for share;
    if not found
      or nullif(pg_catalog.btrim(v_lesson.session_key), '') is null
      or v_lesson.schedule_state not in ('active', 'makeup')
      or v_lesson.start_time is null
      or v_lesson.end_time is null
      or v_lesson.start_time >= v_lesson.end_time
    then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    v_session_key := v_lesson.session_key;
    v_session_date := v_lesson.session_date;
    v_schedule_state := v_lesson.schedule_state;
    v_start_time := v_lesson.start_time;
    v_end_time := v_lesson.end_time;
    v_session_source_revision := v_lesson.revision;
    v_source_revision := pg_catalog.jsonb_build_object(
      'authority', 'normalized',
      'sessionId', v_lesson.id,
      'revision', v_lesson.revision
    );
    v_teacher_catalog_id := v_lesson.teacher_catalog_id;
    v_classroom_catalog_id := v_lesson.classroom_catalog_id;
    v_teacher_name_fallback := nullif(
      pg_catalog.btrim(v_lesson.teacher_name_snapshot), ''
    );
    v_classroom_name_fallback := nullif(
      pg_catalog.btrim(v_lesson.classroom_name_snapshot), ''
    );
  elsif v_observation.session_authority = 'legacy' then
    if v_class.schedule_storage_mode not in ('legacy', 'shadow')
      or v_observation.class_lesson_session_id is not null
      or nullif(pg_catalog.btrim(v_observation.legacy_session_key), '') is null
    then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    v_sessions := case
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'sessions') = 'array'
        then v_class.schedule_plan -> 'sessions'
      when pg_catalog.jsonb_typeof(v_class.schedule_plan -> 'session_list') = 'array'
        then v_class.schedule_plan -> 'session_list'
      else '[]'::jsonb
    end;
    for v_row in
      select session.value
      from pg_catalog.jsonb_array_elements(v_sessions) session(value)
    loop
      v_row_key := coalesce(
        nullif(pg_catalog.btrim(v_row.value ->> 'sessionKey'), ''),
        nullif(pg_catalog.btrim(v_row.value ->> 'session_key'), ''),
        nullif(pg_catalog.btrim(v_row.value ->> 'id'), '')
      );
      if v_row_key is null or v_row_key = any(v_seen_keys) then
        raise exception 'registration_observation_session_source_dirty'
          using errcode = '55000';
      end if;
      v_seen_keys := pg_catalog.array_append(v_seen_keys, v_row_key);
      if v_row_key = v_observation.legacy_session_key then
        v_selected_count := v_selected_count + 1;
        v_selected_session := v_row.value;
      end if;
    end loop;
    if v_selected_count <> 1 then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    v_session_key := v_observation.legacy_session_key;
    begin
      v_session_date := coalesce(
        nullif(pg_catalog.btrim(v_selected_session ->> 'date'), ''),
        nullif(pg_catalog.btrim(v_selected_session ->> 'sessionDate'), ''),
        nullif(pg_catalog.btrim(v_selected_session ->> 'session_date'), '')
      )::date;
    exception
      when invalid_datetime_format or datetime_field_overflow then
        raise exception 'registration_observation_session_source_dirty'
          using errcode = '55000';
    end;
    if v_session_date is null then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    v_schedule_state := pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_selected_session ->> 'scheduleState'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'schedule_state'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'state'), ''),
      'active'
    ));
    if v_schedule_state = 'normal' then
      v_schedule_state := 'active';
    end if;
    if v_schedule_state not in ('active', 'makeup') then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    select count(*)
    into v_slot_count
    from public.class_schedule_slots slot
    where slot.class_id = v_observation.class_id
      and slot.weekday = extract(dow from v_session_date)::smallint;
    if v_slot_count <> 1 then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    select slot.*
    into v_slot
    from public.class_schedule_slots slot
    where slot.class_id = v_observation.class_id
      and slot.weekday = extract(dow from v_session_date)::smallint
    limit 1
    for share;
    v_start_time := v_slot.start_time;
    v_end_time := v_slot.end_time;
    if v_start_time is null
      or v_end_time is null
      or v_start_time >= v_end_time
    then
      raise exception 'registration_observation_session_source_dirty'
        using errcode = '55000';
    end if;

    begin
      v_teacher_catalog_id := coalesce(
        nullif(pg_catalog.btrim(v_selected_session ->> 'teacherCatalogId'), '')::uuid,
        nullif(pg_catalog.btrim(v_selected_session ->> 'teacher_catalog_id'), '')::uuid,
        v_slot.teacher_catalog_id
      );
      v_classroom_catalog_id := coalesce(
        nullif(pg_catalog.btrim(v_selected_session ->> 'classroomCatalogId'), '')::uuid,
        nullif(pg_catalog.btrim(v_selected_session ->> 'classroom_catalog_id'), '')::uuid,
        v_slot.classroom_catalog_id
      );
    exception
      when invalid_text_representation then
        raise exception 'registration_observation_session_source_dirty'
          using errcode = '55000';
    end;
    v_teacher_name_fallback := coalesce(
      nullif(pg_catalog.btrim(v_selected_session ->> 'teacherName'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'teacher_name'), ''),
      nullif(pg_catalog.btrim(v_slot.teacher_name), ''),
      nullif(pg_catalog.btrim(v_class.teacher), '')
    );
    v_classroom_name_fallback := coalesce(
      nullif(pg_catalog.btrim(v_selected_session ->> 'classroomName'), ''),
      nullif(pg_catalog.btrim(v_selected_session ->> 'classroom_name'), ''),
      nullif(pg_catalog.btrim(v_slot.classroom_name), ''),
      nullif(pg_catalog.btrim(v_class.room), '')
    );
    v_legacy_session_source_hash :=
      dashboard_private.registration_observation_legacy_session_content_hash_v1(
        v_class.schedule_plan,
        v_session_key
      );
    v_source_revision := pg_catalog.jsonb_build_object(
      'authority', 'legacy',
      'sessionKey', v_session_key,
      'contentHash', v_legacy_session_source_hash
    );
  else
    raise exception 'registration_observation_session_source_dirty'
      using errcode = '55000';
  end if;

  if v_teacher_catalog_id is not null then
    select teacher.*
    into v_teacher
    from public.teacher_catalogs teacher
    where teacher.id = v_teacher_catalog_id
      and teacher.is_visible = true
      and teacher.profile_id is not null
      and (
        pg_catalog.cardinality(teacher.subjects) = 0
        or v_track.subject = any(teacher.subjects)
      )
    for share;
  elsif v_observation.session_authority = 'legacy' then
    select count(*)
    into v_catalog_count
    from public.teacher_catalogs teacher
    where teacher.is_visible = true
      and teacher.profile_id is not null
      and pg_catalog.lower(teacher.name) = pg_catalog.lower(v_teacher_name_fallback)
      and (
        pg_catalog.cardinality(teacher.subjects) = 0
        or v_track.subject = any(teacher.subjects)
      );
    if v_catalog_count = 1 then
      select teacher.*
      into v_teacher
      from public.teacher_catalogs teacher
      where teacher.is_visible = true
        and teacher.profile_id is not null
        and pg_catalog.lower(teacher.name) = pg_catalog.lower(v_teacher_name_fallback)
        and (
          pg_catalog.cardinality(teacher.subjects) = 0
          or v_track.subject = any(teacher.subjects)
        )
      for share;
    end if;
  end if;
  if v_teacher.id is null
    or not dashboard_private.notification_profile_is_active_v1(
      v_teacher.profile_id
    )
  then
    raise exception 'registration_observation_session_source_dirty'
      using errcode = '55000';
  end if;

  v_catalog_count := 0;
  if v_classroom_catalog_id is not null then
    select classroom.*
    into v_classroom
    from public.classroom_catalogs classroom
    where classroom.id = v_classroom_catalog_id
      and classroom.is_visible = true
      and classroom.campus in ('본관', '별관')
      and (
        pg_catalog.cardinality(classroom.subjects) = 0
        or v_track.subject = any(classroom.subjects)
      )
    for share;
  elsif v_observation.session_authority = 'legacy' then
    select count(*)
    into v_catalog_count
    from public.classroom_catalogs classroom
    where classroom.is_visible = true
      and classroom.campus in ('본관', '별관')
      and pg_catalog.lower(classroom.name)
        = pg_catalog.lower(v_classroom_name_fallback)
      and (
        pg_catalog.cardinality(classroom.subjects) = 0
        or v_track.subject = any(classroom.subjects)
      );
    if v_catalog_count = 1 then
      select classroom.*
      into v_classroom
      from public.classroom_catalogs classroom
      where classroom.is_visible = true
        and classroom.campus in ('본관', '별관')
        and pg_catalog.lower(classroom.name)
          = pg_catalog.lower(v_classroom_name_fallback)
        and (
          pg_catalog.cardinality(classroom.subjects) = 0
          or v_track.subject = any(classroom.subjects)
        )
      for share;
    end if;
  end if;
  if v_classroom.id is null then
    raise exception 'registration_observation_session_source_dirty'
      using errcode = '55000';
  end if;

  v_starts_at := (v_session_date + v_start_time) at time zone 'Asia/Seoul';
  v_ends_at := (v_session_date + v_end_time) at time zone 'Asia/Seoul';
  if v_observation.session_date is distinct from v_session_date
    or v_observation.starts_at is distinct from v_starts_at
    or v_observation.ends_at is distinct from v_ends_at
    or v_observation.session_schedule_state is distinct from v_schedule_state
    or v_observation.session_source_revision
      is distinct from v_session_source_revision
    or v_observation.legacy_session_source_hash
      is distinct from v_legacy_session_source_hash
    or v_observation.source_revision is distinct from v_source_revision
    or v_observation.teacher_catalog_id is distinct from v_teacher.id
    or v_observation.teacher_profile_id is distinct from v_teacher.profile_id
    or v_observation.teacher_name_snapshot is distinct from v_teacher.name
    or v_observation.classroom_catalog_id is distinct from v_classroom.id
    or v_observation.classroom_name_snapshot is distinct from v_classroom.name
    or v_observation.campus is distinct from v_classroom.campus
  then
    raise exception 'registration_observation_session_source_dirty'
      using errcode = '55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'startsAt', v_starts_at,
    'endsAt', v_ends_at,
    'sourceRevision', v_source_revision
  );
end;
$$;
create function dashboard_private.record_registration_observation_attendance_v1_impl(
  p_observation_id uuid,
  p_expected_observation_revision bigint,
  p_expected_appointment_notification_revision integer,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := dashboard_private.registration_observation_active_actor_v1();
  v_actor_role text;
  v_fingerprint text;
  v_existing_operation text;
  v_existing_fingerprint text;
  v_existing_response jsonb;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_observation public.ops_registration_observations%rowtype;
  v_appointment public.ops_registration_appointments%rowtype;
  v_workflow_status_before text;
  v_workflow_revision_before integer;
  v_observation_revision_before bigint;
  v_current_session jsonb;
  v_response jsonb;
begin
  select profile.role
  into v_actor_role
  from public.profiles profile
  where profile.id = v_actor;

  if v_actor_role not in ('admin', 'staff') then
    raise exception 'registration_observation_attendance_access_denied'
      using errcode = '42501';
  end if;
  if p_observation_id is null
    or p_expected_observation_revision is null
    or p_expected_observation_revision < 1
    or p_expected_appointment_notification_revision is null
    or p_expected_appointment_notification_revision < 1
    or nullif(pg_catalog.btrim(p_request_key), '') is null
  then
    raise exception 'registration_observation_attendance_invalid'
      using errcode = '22023';
  end if;

  v_fingerprint :=
    dashboard_private.registration_observation_request_fingerprint_v1(
      pg_catalog.jsonb_build_object(
        'operation', 'record_attendance',
        'observationId', p_observation_id,
        'expectedObservationRevision', p_expected_observation_revision,
        'expectedAppointmentNotificationRevision',
          p_expected_appointment_notification_revision
      )
    );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || p_request_key, 0)
  );
  select
    request.operation,
    request.request_fingerprint,
    request.response_payload
  into
    v_existing_operation,
    v_existing_fingerprint,
    v_existing_response
  from dashboard_private.registration_observation_mutation_requests request
  where request.actor_profile_id = v_actor
    and request.request_key = p_request_key;
  if found then
    if v_existing_operation <> 'record_attendance'
      or v_existing_fingerprint <> v_fingerprint
    then
      raise exception 'registration_observation_request_key_conflict'
        using errcode = '23505';
    end if;
    return v_existing_response;
  end if;

  perform dashboard_private.assert_registration_observation_runtime_v1();

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = (
    select observation.track_id
    from public.ops_registration_observations observation
    where observation.id = p_observation_id
  )
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select observation.*
  into v_observation
  from public.ops_registration_observations observation
  where observation.id = p_observation_id
    and observation.track_id = v_track.id
    and observation.task_id = v_track.task_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select appointment.*
  into v_appointment
  from public.ops_registration_appointments appointment
  where appointment.id = v_observation.appointment_id
    and appointment.task_id = v_track.task_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  if v_observation.revision <> p_expected_observation_revision
    or v_appointment.notification_revision
      <> p_expected_appointment_notification_revision
  then
    raise exception 'registration_observation_stale_revision'
      using errcode = '40001';
  end if;
  if v_track.workflow_status <> 'observation_requested'
    or v_observation.status <> 'scheduled'
    or v_observation.decision_kind is not null
    or v_appointment.kind <> 'observation_class'
    or v_appointment.status <> 'scheduled'
  then
    raise exception 'registration_observation_transition_rejected'
      using errcode = '55000';
  end if;
  v_current_session :=
    dashboard_private.assert_registration_observation_current_session_v1(
      v_observation.id,
      'record_attendance'
    );
  if pg_catalog.now() < (v_current_session ->> 'startsAt')::timestamptz then
    raise exception 'registration_observation_time_boundary_rejected'
      using errcode = '55000';
  end if;

  v_workflow_status_before := v_track.workflow_status;
  v_workflow_revision_before := v_track.workflow_revision;
  v_observation_revision_before := v_observation.revision;

  update public.ops_registration_appointments appointment
  set status = 'completed',
      updated_at = pg_catalog.now()
  where appointment.id = v_appointment.id
  returning appointment.* into v_appointment;

  update public.ops_registration_observations observation
  set status = 'attended_feedback_pending',
      attendance = 'attended',
      attendance_recorded_by = v_actor,
      attendance_recorded_at = pg_catalog.now(),
      revision = observation.revision + 1,
      updated_by = v_actor,
      updated_at = pg_catalog.now()
  where observation.id = v_observation.id
  returning observation.* into v_observation;

  update public.ops_registration_subject_tracks track
  set workflow_status = 'observation_feedback_pending',
      workflow_revision = track.workflow_revision + 1,
      workflow_status_entered_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where track.id = v_track.id
  returning track.* into v_track;

  insert into dashboard_private.registration_observation_domain_events(
    observation_id,
    appointment_id,
    notification_revision,
    event_kind,
    booking_fact_hash,
    source_revision
  ) values (
    v_observation.id,
    v_appointment.id,
    v_appointment.notification_revision,
    'observation_attendance_recorded',
    v_observation.booking_fact_hash,
    v_observation.source_revision
  );

  perform dashboard_private.write_registration_track_event_v2(
    v_track.task_id,
    v_track.id,
    'registration_observation_attendance_recorded',
    v_workflow_status_before,
    v_track.workflow_status,
    null,
    pg_catalog.jsonb_build_object(
      'trackId', v_track.id,
      'observationId', v_observation.id,
      'appointmentId', v_appointment.id,
      'workflowRevisionBefore', v_workflow_revision_before,
      'workflowRevisionAfter', v_track.workflow_revision,
      'observationRevisionBefore', v_observation_revision_before,
      'observationRevisionAfter', v_observation.revision,
      'feedbackRevisionBefore', v_observation.feedback_revision,
      'feedbackRevisionAfter', v_observation.feedback_revision,
      'appointmentNotificationRevisionBefore',
        v_appointment.notification_revision,
      'appointmentNotificationRevisionAfter',
        v_appointment.notification_revision
    ),
    'user',
    null
  );

  v_response := dashboard_private.registration_observation_response_v1(
    'record_attendance',
    p_request_key,
    v_track,
    v_observation,
    v_appointment,
    true
  );
  insert into dashboard_private.registration_observation_mutation_requests(
    actor_profile_id,
    operation,
    request_key,
    track_id,
    request_fingerprint,
    response_payload
  ) values (
    v_actor,
    'record_attendance',
    p_request_key,
    v_track.id,
    v_fingerprint,
    v_response
  );

  return v_response;
end;
$$;
create function dashboard_private.submit_registration_observation_feedback_v1_impl(
  p_observation_id uuid,
  p_attendance text,
  p_suitability_result text,
  p_feedback_reason text,
  p_expected_observation_revision bigint,
  p_expected_feedback_revision bigint,
  p_expected_appointment_notification_revision integer,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := dashboard_private.registration_observation_active_actor_v1();
  v_actor_role text;
  v_attendance text := pg_catalog.btrim(p_attendance);
  v_suitability_result text := pg_catalog.btrim(p_suitability_result);
  v_feedback_reason text :=
    nullif(pg_catalog.btrim(p_feedback_reason), '');
  v_fingerprint text;
  v_existing_operation text;
  v_existing_fingerprint text;
  v_existing_response jsonb;
  v_existing_track_id uuid;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_observation public.ops_registration_observations%rowtype;
  v_appointment public.ops_registration_appointments%rowtype;
  v_event_kind text;
  v_audit_event_type text;
  v_workflow_status_before text;
  v_workflow_revision_before integer;
  v_observation_revision_before bigint;
  v_feedback_revision_before bigint;
  v_current_session jsonb;
  v_response jsonb;
begin
  if p_observation_id is null
    or p_expected_observation_revision is null
    or p_expected_observation_revision < 1
    or p_expected_feedback_revision is null
    or p_expected_feedback_revision < 0
    or p_expected_appointment_notification_revision is null
    or p_expected_appointment_notification_revision < 1
    or nullif(pg_catalog.btrim(p_request_key), '') is null
    or v_attendance is null
    or v_attendance not in ('attended', 'no_show')
    or (
      v_attendance = 'attended'
      and (
        v_suitability_result is null
        or v_suitability_result not in ('fit', 'unfit')
        or v_feedback_reason is null
      )
    )
    or (
      v_attendance = 'no_show'
      and (
        p_suitability_result is not null
        or p_feedback_reason is not null
      )
    )
  then
    raise exception 'registration_observation_feedback_invalid'
      using errcode = '22023';
  end if;

  select profile.role
  into v_actor_role
  from public.profiles profile
  where profile.id = v_actor;

  v_fingerprint :=
    dashboard_private.registration_observation_request_fingerprint_v1(
      pg_catalog.jsonb_build_object(
        'operation', 'submit_feedback',
        'observationId', p_observation_id,
        'attendance', v_attendance,
        'suitabilityResult', case
          when v_attendance = 'attended' then v_suitability_result
          else null
        end,
        'feedbackReason', case
          when v_attendance = 'attended' then v_feedback_reason
          else null
        end,
        'expectedObservationRevision', p_expected_observation_revision,
        'expectedFeedbackRevision', p_expected_feedback_revision,
        'expectedAppointmentNotificationRevision',
          p_expected_appointment_notification_revision
      )
    );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || p_request_key, 0)
  );
  select
    request.operation,
    request.request_fingerprint,
    request.response_payload,
    request.track_id
  into
    v_existing_operation,
    v_existing_fingerprint,
    v_existing_response,
    v_existing_track_id
  from dashboard_private.registration_observation_mutation_requests request
  where request.actor_profile_id = v_actor
    and request.request_key = p_request_key;
  if found then
    if v_existing_operation <> 'submit_feedback'
      or v_existing_fingerprint <> v_fingerprint
    then
      raise exception 'registration_observation_request_key_conflict'
        using errcode = '23505';
    end if;
    if not exists (
      select 1
      from public.ops_registration_observations observation
      join public.ops_registration_subject_tracks track
        on track.id = observation.track_id
       and track.task_id = observation.task_id
      where observation.id = p_observation_id
        and observation.track_id = v_existing_track_id
        and (
          v_actor_role in ('admin', 'staff')
          or (
            v_actor_role = 'teacher'
            and v_actor = observation.teacher_profile_id
          )
        )
    ) then
      raise exception 'registration_observation_not_found'
        using errcode = 'P0002';
    end if;
    return v_existing_response;
  end if;

  perform dashboard_private.assert_registration_observation_runtime_v1();

  select track.*
  into v_track
  from public.ops_registration_subject_tracks track
  where track.id = (
    select observation.track_id
    from public.ops_registration_observations observation
    where observation.id = p_observation_id
  )
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select observation.*
  into v_observation
  from public.ops_registration_observations observation
  where observation.id = p_observation_id
    and observation.track_id = v_track.id
    and observation.task_id = v_track.task_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  select appointment.*
  into v_appointment
  from public.ops_registration_appointments appointment
  where appointment.id = v_observation.appointment_id
    and appointment.task_id = v_track.task_id
  for update;
  if not found then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;

  if not (
    v_actor_role in ('admin', 'staff')
    or (
      v_actor_role = 'teacher'
      and v_actor = v_observation.teacher_profile_id
    )
  ) then
    raise exception 'registration_observation_not_found'
      using errcode = 'P0002';
  end if;
  if v_observation.revision <> p_expected_observation_revision
    or v_observation.feedback_revision <> p_expected_feedback_revision
    or v_appointment.notification_revision
      <> p_expected_appointment_notification_revision
  then
    raise exception 'registration_observation_stale_revision'
      using errcode = '40001';
  end if;
  if v_observation.decision_kind is not null
    or v_appointment.kind <> 'observation_class'
  then
    raise exception 'registration_observation_transition_rejected'
      using errcode = '55000';
  end if;

  if v_attendance = 'attended' then
    if not (
      (
        v_track.workflow_status = 'observation_requested'
        and v_observation.status = 'scheduled'
        and v_appointment.status = 'scheduled'
      )
      or (
        v_track.workflow_status = 'observation_feedback_pending'
        and v_observation.status = 'attended_feedback_pending'
        and v_observation.attendance = 'attended'
        and v_appointment.status = 'completed'
      )
    ) then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;
    v_current_session :=
      dashboard_private.assert_registration_observation_current_session_v1(
        v_observation.id,
        'submit_feedback'
      );
    if pg_catalog.now() < (v_current_session ->> 'endsAt')::timestamptz then
      raise exception 'registration_observation_time_boundary_rejected'
        using errcode = '55000';
    end if;
    v_event_kind := 'observation_feedback_submitted';
    v_audit_event_type := 'registration_observation_feedback_submitted';
  else
    if v_track.workflow_status <> 'observation_requested'
      or v_observation.status <> 'scheduled'
      or v_appointment.status <> 'scheduled'
    then
      raise exception 'registration_observation_transition_rejected'
        using errcode = '55000';
    end if;
    v_current_session :=
      dashboard_private.assert_registration_observation_current_session_v1(
        v_observation.id,
        'submit_feedback'
      );
    if pg_catalog.now() < (v_current_session ->> 'startsAt')::timestamptz then
      raise exception 'registration_observation_time_boundary_rejected'
        using errcode = '55000';
    end if;
    v_event_kind := 'observation_no_show';
    v_audit_event_type := 'registration_observation_no_show';
  end if;

  v_workflow_status_before := v_track.workflow_status;
  v_workflow_revision_before := v_track.workflow_revision;
  v_observation_revision_before := v_observation.revision;
  v_feedback_revision_before := v_observation.feedback_revision;

  update public.ops_registration_appointments appointment
  set status = 'completed',
      updated_at = pg_catalog.now()
  where appointment.id = v_appointment.id
  returning appointment.* into v_appointment;

  if v_attendance = 'attended' then
    update public.ops_registration_observations observation
    set status = 'completed',
        attendance = 'attended',
        attendance_recorded_by = case
          when observation.status = 'scheduled' then v_actor
          else observation.attendance_recorded_by
        end,
        attendance_recorded_at = case
          when observation.status = 'scheduled' then pg_catalog.now()
          else observation.attendance_recorded_at
        end,
        suitability_result = v_suitability_result,
        feedback_reason = v_feedback_reason,
        feedback_submitted_by = v_actor,
        feedback_submitted_at = pg_catalog.now(),
        feedback_revision = observation.feedback_revision + 1,
        revision = observation.revision + 1,
        updated_by = v_actor,
        updated_at = pg_catalog.now()
    where observation.id = v_observation.id
    returning observation.* into v_observation;
  else
    update public.ops_registration_observations observation
    set status = 'no_show',
        attendance = 'no_show',
        attendance_recorded_by = v_actor,
        attendance_recorded_at = pg_catalog.now(),
        revision = observation.revision + 1,
        updated_by = v_actor,
        updated_at = pg_catalog.now()
    where observation.id = v_observation.id
    returning observation.* into v_observation;
  end if;

  update public.ops_registration_subject_tracks track
  set workflow_status = 'observation_completed',
      workflow_revision = track.workflow_revision + 1,
      workflow_status_entered_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where track.id = v_track.id
  returning track.* into v_track;

  insert into dashboard_private.registration_observation_domain_events(
    observation_id,
    appointment_id,
    notification_revision,
    event_kind,
    booking_fact_hash,
    source_revision
  ) values (
    v_observation.id,
    v_appointment.id,
    v_appointment.notification_revision,
    v_event_kind,
    v_observation.booking_fact_hash,
    v_observation.source_revision
  );

  perform dashboard_private.write_registration_track_event_v2(
    v_track.task_id,
    v_track.id,
    v_audit_event_type,
    v_workflow_status_before,
    v_track.workflow_status,
    null,
    pg_catalog.jsonb_build_object(
      'trackId', v_track.id,
      'observationId', v_observation.id,
      'appointmentId', v_appointment.id,
      'attendance', v_observation.attendance,
      'suitabilityResult', v_observation.suitability_result,
      'proxySubmitted', v_actor <> v_observation.teacher_profile_id,
      'assignedTeacherProfileId', v_observation.teacher_profile_id,
      'submittedByProfileId', v_actor,
      'workflowRevisionBefore', v_workflow_revision_before,
      'workflowRevisionAfter', v_track.workflow_revision,
      'observationRevisionBefore', v_observation_revision_before,
      'observationRevisionAfter', v_observation.revision,
      'feedbackRevisionBefore', v_feedback_revision_before,
      'feedbackRevisionAfter', v_observation.feedback_revision,
      'appointmentNotificationRevisionBefore',
        v_appointment.notification_revision,
      'appointmentNotificationRevisionAfter',
        v_appointment.notification_revision
    ),
    'user',
    null
  );

  v_response := dashboard_private.registration_observation_response_v1(
    'submit_feedback',
    p_request_key,
    v_track,
    v_observation,
    v_appointment,
    true
  );
  insert into dashboard_private.registration_observation_mutation_requests(
    actor_profile_id,
    operation,
    request_key,
    track_id,
    request_fingerprint,
    response_payload
  ) values (
    v_actor,
    'submit_feedback',
    p_request_key,
    v_track.id,
    v_fingerprint,
    v_response
  );

  return v_response;
end;
$$;
