create table public.science_consultation_requests (
  id uuid primary key default gen_random_uuid(),
  parent_name text not null,
  phone text not null,
  student_grade text not null,
  interest_area text not null,
  preferred_time text,
  message text,
  privacy_consent boolean not null,
  consent_version text not null default '2026-08-11',
  source_domain text not null default 'science.tipsedu.co.kr',
  status text not null default 'new',
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '6 months'),

  constraint science_consultation_parent_name_check
    check (parent_name = btrim(parent_name) and char_length(parent_name) between 2 and 40),
  constraint science_consultation_phone_check
    check (phone ~ '^0[0-9]{8,10}$'),
  constraint science_consultation_grade_check
    check (student_grade = btrim(student_grade) and char_length(student_grade) between 1 and 30),
  constraint science_consultation_interest_check
    check (interest_area = btrim(interest_area) and char_length(interest_area) between 1 and 50),
  constraint science_consultation_preferred_time_check
    check (preferred_time is null or (preferred_time = btrim(preferred_time) and char_length(preferred_time) between 1 and 100)),
  constraint science_consultation_message_check
    check (message is null or char_length(message) <= 2000),
  constraint science_consultation_consent_check
    check (privacy_consent is true),
  constraint science_consultation_source_check
    check (source_domain = 'science.tipsedu.co.kr'),
  constraint science_consultation_status_check
    check (status in ('new', 'contacted', 'closed'))
);
comment on table public.science_consultation_requests is
  'Parent consultation requests submitted from science.tipsedu.co.kr. Retained for six months.';
comment on column public.science_consultation_requests.phone is
  'Normalized Korean contact number containing digits only.';
comment on column public.science_consultation_requests.expires_at is
  'Automatic deletion deadline: six calendar months after submission.';
create index science_consultation_requests_created_at_idx
  on public.science_consultation_requests (created_at desc);
create index science_consultation_requests_status_created_at_idx
  on public.science_consultation_requests (status, created_at desc);
create index science_consultation_requests_expires_at_idx
  on public.science_consultation_requests (expires_at);
alter table public.science_consultation_requests enable row level security;
revoke all on table public.science_consultation_requests from public, anon, authenticated;
grant select, insert, update, delete on table public.science_consultation_requests to service_role;
create policy "No direct client access"
on public.science_consultation_requests
as restrictive
for all
to anon, authenticated
using (false)
with check (false);
create table public.science_consultation_rate_limits (
  fingerprint text primary key,
  window_started_at timestamptz not null default now(),
  request_count integer not null default 0,
  blocked_until timestamptz,
  last_seen_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '2 days'),

  constraint science_consultation_rate_fingerprint_check
    check (fingerprint ~ '^[a-f0-9]{64}$'),
  constraint science_consultation_rate_count_check
    check (request_count between 0 and 1000)
);
comment on table public.science_consultation_rate_limits is
  'Short-lived, irreversible request fingerprints used only to rate-limit the public science consultation endpoint.';
create index science_consultation_rate_limits_expires_at_idx
  on public.science_consultation_rate_limits (expires_at);
alter table public.science_consultation_rate_limits enable row level security;
revoke all on table public.science_consultation_rate_limits from public, anon, authenticated;
grant select, insert, update, delete on table public.science_consultation_rate_limits to service_role;
create policy "No direct client access"
on public.science_consultation_rate_limits
as restrictive
for all
to anon, authenticated
using (false)
with check (false);
begin;
create table dashboard_private.notification_cutover_owners (
  scope_key text primary key,
  workflow_key text not null,
  dispatch_flag_key text not null unique
    references dashboard_private.notification_runtime_flags(flag_key),
  owner_kind text not null,
  constraint notification_cutover_owners_scope_key_check check (
    scope_key in (
      'tasks',
      'word_retests',
      'approvals',
      'transfer',
      'withdrawal',
      'makeup_requests',
      'registration',
      'registration_phone',
      'registration_visit',
      'registration_solapi'
    )
  ),
  constraint notification_cutover_owners_owner_kind_check check (
    owner_kind in ('legacy', 'canonical')
  ),
  constraint notification_cutover_owners_identity_check check (
    (scope_key = 'tasks'
      and workflow_key = 'tasks'
      and dispatch_flag_key = 'notification_control_plane_dispatch_tasks_enabled')
    or (scope_key = 'word_retests'
      and workflow_key = 'word_retests'
      and dispatch_flag_key = 'notification_control_plane_dispatch_word_retests_enabled')
    or (scope_key = 'approvals'
      and workflow_key = 'approvals'
      and dispatch_flag_key = 'notification_control_plane_dispatch_approvals_enabled')
    or (scope_key = 'transfer'
      and workflow_key = 'transfer'
      and dispatch_flag_key = 'notification_control_plane_dispatch_transfer_enabled')
    or (scope_key = 'withdrawal'
      and workflow_key = 'withdrawal'
      and dispatch_flag_key = 'notification_control_plane_dispatch_withdrawal_enabled')
    or (scope_key = 'makeup_requests'
      and workflow_key = 'makeup_requests'
      and dispatch_flag_key = 'notification_control_plane_dispatch_makeup_requests_enabled')
    or (scope_key = 'registration'
      and workflow_key = 'registration'
      and dispatch_flag_key = 'notification_control_plane_dispatch_registration_enabled')
    or (scope_key = 'registration_phone'
      and workflow_key = 'registration'
      and dispatch_flag_key = 'notification_control_plane_registration_phone_adapter_enabled')
    or (scope_key = 'registration_visit'
      and workflow_key = 'registration'
      and dispatch_flag_key = 'notification_control_plane_registration_visit_adapter_enabled')
    or (scope_key = 'registration_solapi'
      and workflow_key = 'registration'
      and dispatch_flag_key = 'notification_control_plane_registration_solapi_adapter_enabled')
  )
);
alter table dashboard_private.notification_cutover_owners owner to postgres;
alter table dashboard_private.notification_cutover_owners enable row level security;
