begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
create schema if not exists dashboard_private;
create function dashboard_private.academic_class_status_v1(
  p_status text,
  p_start_date date,
  p_end_date date
)
returns text
language sql
stable
security invoker
set search_path = ''
as $$
  select case
    when pg_catalog.btrim(coalesce(p_status, '')) in ('개강', '수업 진행 중', '수강') then '수강'
    when pg_catalog.btrim(coalesce(p_status, '')) in ('개강 예정', '개강 준비 중', '개강 준비') then '개강 준비'
    when pg_catalog.btrim(coalesce(p_status, '')) = '종강' then '종강'
    when p_start_date is not null and p_start_date > current_date then '개강 준비'
    when p_end_date is not null and p_end_date < current_date then '종강'
    else '수강'
  end;
$$;
create function dashboard_private.academic_classroom_name_v1(p_value text)
returns text
language sql
immutable
security invoker
set search_path = ''
as $$
  select case pg_catalog.regexp_replace(pg_catalog.btrim(coalesce(p_value, '')), '\s+', '', 'g')
    when '본2' then '본관 2강'
    when '본2강' then '본관 2강'
    when '본3' then '본관 3강'
    when '본3강' then '본관 3강'
    when '본5' then '본관 5강'
    when '본5강' then '본관 5강'
    when '별3' then '별관 3강'
    when '별3강' then '별관 3강'
    when '별4' then '별관 4강'
    when '별4강' then '별관 4강'
    when '별관4강' then '별관 4강'
    when '별5' then '별관 5강'
    when '별5강' then '별관 5강'
    when '별7' then '별관 5강'
    when '별7강' then '별관 5강'
    else pg_catalog.btrim(coalesce(p_value, ''))
  end;
$$;
create function public.get_academic_timetable_range_v1(
  p_date_from date,
  p_date_to date,
  p_class_group_id text default null,
  p_status text default null,
  p_subject text default null
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_rows jsonb := '[]'::jsonb;
  v_class_summaries jsonb := '[]'::jsonb;
  v_terms jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
  v_members jsonb := '[]'::jsonb;
  v_teachers jsonb := '[]'::jsonb;
  v_classrooms jsonb := '[]'::jsonb;
  v_status_options jsonb := '[]'::jsonb;
  v_subject_options jsonb := '[]'::jsonb;
  v_collection text;
  v_class_group_id text;
begin
  if (select auth.uid()) is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  if p_date_from is null or p_date_to is null or p_date_to < p_date_from
     or (p_date_to - p_date_from) > 13 then
    raise exception 'academic_timetable_range_invalid' using errcode = '22023';
  end if;
  select coalesce(
    nullif(pg_catalog.btrim(p_class_group_id), ''),
    (
      select group_row.id::text
      from public.class_schedule_sync_groups group_row
      order by group_row.is_default desc, group_row.sort_order, group_row.name collate dashboard_private.ko_numeric, group_row.id
      limit 1
    )
  ) into v_class_group_id;

  with eligible as materialized (
    select
      class.id,
      class.name,
      class.subject,
      class.subject_area_key,
      class.grade,
      class.teacher,
      class.room,
      class.schedule,
      class.status,
      class.start_date,
      class.end_date,
      class.term_id,
      class.period,
      coalesce(term.academic_year, nullif(pg_catalog.substring(class.period, '([0-9]{4})'), '')::integer, pg_catalog.date_part('year', current_date)::integer) as academic_year,
      coalesce(nullif(pg_catalog.btrim(class.period), ''), nullif(pg_catalog.btrim(term.name), '')) as term_name,
      dashboard_private.academic_class_status_v1(class.status, nullif(pg_catalog.btrim(class.start_date), '')::date, nullif(pg_catalog.btrim(class.end_date), '')::date) as normalized_status
    from public.classes class
    left join public.class_terms term on term.id = class.term_id
    where (nullif(pg_catalog.btrim(class.start_date), '') is null or nullif(pg_catalog.btrim(class.start_date), '')::date <= p_date_to)
      and (nullif(pg_catalog.btrim(class.end_date), '') is null or nullif(pg_catalog.btrim(class.end_date), '')::date >= p_date_from)
      and (nullif(pg_catalog.btrim(p_status), '') is null
        or dashboard_private.academic_class_status_v1(class.status, nullif(pg_catalog.btrim(class.start_date), '')::date, nullif(pg_catalog.btrim(class.end_date), '')::date) = pg_catalog.btrim(p_status))
      and (nullif(pg_catalog.btrim(p_subject), '') is null or pg_catalog.btrim(class.subject) = pg_catalog.btrim(p_subject))
      and (
        nullif(pg_catalog.btrim(v_class_group_id), '') is null
        or exists (
          select 1
          from public.class_schedule_sync_group_members member
          join public.class_schedule_sync_groups group_row on group_row.id = member.group_id
          where member.class_id = class.id
            and (member.group_id::text = v_class_group_id or group_row.name = v_class_group_id)
        )
        or (
          not exists (
            select 1 from public.class_schedule_sync_group_members member
            where member.class_id = class.id
          )
          and (
            ('term:' || coalesce(term.academic_year::text, nullif(pg_catalog.substring(class.period, '([0-9]{4})'), ''), pg_catalog.date_part('year', current_date)::integer::text)
              || ':' || coalesce(nullif(pg_catalog.btrim(class.period), ''), nullif(pg_catalog.btrim(term.name), ''), 'term')) = v_class_group_id
            or pg_catalog.btrim(pg_catalog.concat_ws(' ', term.academic_year::text, coalesce(nullif(pg_catalog.btrim(class.period), ''), nullif(pg_catalog.btrim(term.name), '')))) = v_class_group_id
          )
        )
      )
  ), group_context as materialized (
    select
      class.id as class_id,
      coalesce(
        pg_catalog.jsonb_agg(group_row.id::text order by member.sort_order, group_row.sort_order, group_row.name)
          filter (where group_row.id is not null),
        pg_catalog.jsonb_build_array(
          'term:' || class.academic_year::text || ':' || coalesce(class.term_name, 'term')
        )
      ) as group_ids,
      coalesce(
        pg_catalog.jsonb_agg(group_row.name order by member.sort_order, group_row.sort_order, group_row.name)
          filter (where group_row.id is not null),
        pg_catalog.jsonb_build_array(
          pg_catalog.btrim(pg_catalog.concat_ws(' ', class.academic_year::text, class.term_name))
        )
      ) as group_names
    from eligible class
    left join public.class_schedule_sync_group_members member on member.class_id = class.id
    left join public.class_schedule_sync_groups group_row on group_row.id = member.group_id
    group by class.id, class.academic_year, class.term_name
  ), parsed as materialized (
    select
      class.*,
      context.group_ids,
      context.group_names,
      matched.parts,
      day_value.day,
      coalesce(
        nullif(pg_catalog.btrim((
          select token
          from pg_catalog.regexp_split_to_table(coalesce(matched.parts[4], ''), '[,/&·]+') token
          where pg_catalog.btrim(token) <> ''
            and pg_catalog.btrim(token) !~* '(강의실|교실|랩|홀|센터|스튜디오|room|본관|별관|^(본|별)[0-9]+(강)?$|^[0-9]+(강|실|관)$)'
          limit 1
        )), ''),
        nullif(pg_catalog.btrim(pg_catalog.split_part(pg_catalog.regexp_replace(coalesce(class.teacher, ''), '[&/·]', ',', 'g'), ',', 1)), ''),
        ''
      ) as row_teacher,
      dashboard_private.academic_classroom_name_v1(coalesce(
        nullif(pg_catalog.btrim((
          select token
          from pg_catalog.regexp_split_to_table(coalesce(matched.parts[4], ''), '[,/&·]+') token
          where pg_catalog.btrim(token) ~* '(강의실|교실|랩|홀|센터|스튜디오|room|본관|별관|^(본|별)[0-9]+(강)?$|^[0-9]+(강|실|관)$)'
          limit 1
        )), ''),
        nullif(pg_catalog.btrim(pg_catalog.split_part(pg_catalog.regexp_replace(coalesce(class.room, ''), '[&/·]', ',', 'g'), ',', 1)), ''),
        ''
      )) as row_classroom
    from eligible class
    join group_context context on context.class_id = class.id
    cross join lateral pg_catalog.regexp_matches(
      coalesce(class.schedule, ''),
      '([월화수목금토일]+)\s*([0-9]{1,2}:[0-9]{2})\s*-\s*([0-9]{1,2}:[0-9]{2})(?:\s*\(([^)]+)\))?',
      'g'
    ) matched(parts)
    cross join lateral pg_catalog.regexp_split_to_table(matched.parts[1], '') day_value(day)
    where day_value.day in ('월','화','수','목','금','토','일')
  ), row_limited as materialized (
    select pg_catalog.jsonb_build_object(
      'id', parsed.id::text || ':' || parsed.day || ':' || parsed.parts[2] || ':' || parsed.parts[3],
      'classId', parsed.id,
      'title', pg_catalog.regexp_replace(coalesce(parsed.name, ''), '^\[[^]]+\]\s*', ''),
      'fullTitle', coalesce(parsed.name, ''),
      'academicYear', parsed.academic_year::text,
      'subject', coalesce(parsed.subject, ''),
      'subjectAreaKey', coalesce(parsed.subject_area_key, ''),
      'grade', coalesce(parsed.grade, ''),
      'teacher', parsed.row_teacher,
      'classroom', parsed.row_classroom,
      'term', coalesce(parsed.term_name, ''),
      'schedule', coalesce(parsed.schedule, ''),
      'status', parsed.normalized_status,
      'statusFilter', parsed.normalized_status,
      'classGroupIds', parsed.group_ids,
      'classGroupNames', parsed.group_names,
      'classGroupLabel', coalesce((select pg_catalog.string_agg(value, ', ') from pg_catalog.jsonb_array_elements_text(parsed.group_names) value), '미분류'),
      'day', parsed.day,
      'dayIndex', case parsed.day when '월' then 0 when '화' then 1 when '수' then 2 when '목' then 3 when '금' then 4 when '토' then 5 else 6 end,
      'start', parsed.parts[2],
      'end', parsed.parts[3],
      'startMinutes', pg_catalog.split_part(parsed.parts[2], ':', 1)::integer * 60 + pg_catalog.split_part(parsed.parts[2], ':', 2)::integer,
      'endMinutes', pg_catalog.split_part(parsed.parts[3], ':', 1)::integer * 60 + pg_catalog.split_part(parsed.parts[3], ':', 2)::integer,
      'durationMinutes', greatest(0,
        pg_catalog.split_part(parsed.parts[3], ':', 1)::integer * 60 + pg_catalog.split_part(parsed.parts[3], ':', 2)::integer
        - pg_catalog.split_part(parsed.parts[2], ':', 1)::integer * 60 - pg_catalog.split_part(parsed.parts[2], ':', 2)::integer),
      'searchText', pg_catalog.lower(pg_catalog.concat_ws(' ', pg_catalog.regexp_replace(coalesce(parsed.name, ''), '^\[[^]]+\]\s*', ''), parsed.subject, parsed.grade, parsed.row_teacher, parsed.row_classroom, parsed.normalized_status, parsed.term_name, parsed.schedule))
    ) as row_data,
    parsed.day,
    parsed.parts[2] as start_time,
    parsed.id
    from parsed
    order by case parsed.day when '월' then 0 when '화' then 1 when '수' then 2 when '목' then 3 when '금' then 4 when '토' then 5 else 6 end,
      parsed.parts[2], parsed.id
    limit 2001
  ), class_summary_limited as materialized (
    select pg_catalog.jsonb_build_object(
      'id', class.id,
      'subject', class.subject,
      'grade', class.grade,
      'term_id', class.term_id,
      'period', class.period,
      'academic_year', class.academic_year
    ) as row_data
    from eligible class order by class.name collate dashboard_private.ko_numeric, class.id limit 501
  ), term_limited as materialized (
    select bounded.row_data
    from (
      select distinct pg_catalog.jsonb_build_object(
        'id', term.id,
        'academic_year', term.academic_year,
        'name', term.name,
        'sort_order', term.sort_order
      ) as row_data
      from public.class_terms term join eligible class on class.term_id = term.id
    ) bounded
    order by bounded.row_data::text limit 501
  ), group_limited as materialized (
    select bounded.row_data
    from (
      select distinct pg_catalog.jsonb_build_object(
        'id', group_row.id,
        'name', group_row.name,
        'subject', group_row.subject,
        'sort_order', group_row.sort_order,
        'is_default', group_row.is_default
      ) as row_data
      from public.class_schedule_sync_groups group_row
      join public.class_schedule_sync_group_members member on member.group_id = group_row.id
      join eligible class on class.id = member.class_id
    ) bounded
    order by bounded.row_data::text limit 501
  ), member_limited as materialized (
    select pg_catalog.jsonb_build_object(
      'group_id', member.group_id,
      'class_id', member.class_id,
      'sort_order', member.sort_order
    ) as row_data
    from public.class_schedule_sync_group_members member join eligible class on class.id = member.class_id
    order by member.group_id, member.sort_order, member.class_id limit 501
  ), teacher_limited as materialized (
    select pg_catalog.jsonb_build_object(
      'name', catalog.name,
      'subjects', catalog.subjects,
      'is_visible', catalog.is_visible,
      'sort_order', catalog.sort_order
    ) as row_data
    from public.teacher_catalogs catalog
    where catalog.is_visible
      and exists (select 1 from eligible class where coalesce(class.teacher, '') ilike '%' || catalog.name || '%')
    order by catalog.sort_order, catalog.name collate dashboard_private.ko_numeric, catalog.id limit 501
  ), classroom_limited as materialized (
    select pg_catalog.jsonb_build_object(
      'name', catalog.name,
      'subjects', catalog.subjects,
      'is_visible', catalog.is_visible,
      'sort_order', catalog.sort_order
    ) as row_data
    from public.classroom_catalogs catalog
    where catalog.is_visible
      and exists (select 1 from eligible class where coalesce(class.room, '') ilike '%' || catalog.name || '%')
    order by catalog.sort_order, catalog.name collate dashboard_private.ko_numeric, catalog.id limit 501
  )
  select
    coalesce((select pg_catalog.jsonb_agg(row_data order by day, start_time, id) from row_limited), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(row_data) from class_summary_limited), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(row_data) from term_limited), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(row_data) from group_limited), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(row_data) from member_limited), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(row_data) from teacher_limited), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(row_data) from classroom_limited), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(distinct normalized_status order by normalized_status) from eligible), '[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(distinct subject order by subject) filter (where nullif(pg_catalog.btrim(subject), '') is not null) from eligible), '[]'::jsonb)
  into v_rows, v_class_summaries, v_terms, v_groups, v_members, v_teachers, v_classrooms, v_status_options, v_subject_options;

  if pg_catalog.jsonb_array_length(v_rows) > 2000 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'visible_range_too_dense',
      'range', pg_catalog.jsonb_build_object('dateFrom', p_date_from, 'dateTo', p_date_to),
      'rows', '[]'::jsonb, 'observedRowsAtLeast', 2001, 'suggestedDays', 7
    );
  end if;

  foreach v_collection in array array['class_summaries','class_terms','class_groups','class_group_members','teacher_catalogs','classroom_catalogs'] loop
    if pg_catalog.jsonb_array_length(case v_collection
      when 'class_summaries' then v_class_summaries when 'class_terms' then v_terms
      when 'class_groups' then v_groups when 'class_group_members' then v_members
      when 'teacher_catalogs' then v_teachers else v_classrooms end) > 500 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'timetable_collection_too_dense',
        'range', pg_catalog.jsonb_build_object('dateFrom', p_date_from, 'dateTo', p_date_to),
        'collection', v_collection, 'observedItemsAtLeast', 501,
        'action', 'narrow_filters', 'rows', '[]'::jsonb
      );
    end if;
  end loop;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'range', pg_catalog.jsonb_build_object('dateFrom', p_date_from, 'dateTo', p_date_to),
    'resolvedClassGroupId', v_class_group_id,
    'rows', v_rows,
    'classSummaries', v_class_summaries,
    'classTerms', v_terms,
    'classGroups', v_groups,
    'classGroupMembers', v_members,
    'teacherCatalogs', v_teachers,
    'classroomCatalogs', v_classrooms,
    'statusOptions', v_status_options,
    'subjectOptions', v_subject_options,
    'complete', true
  );
end;
$$;
create function public.get_academic_curriculum_page_v1(
  p_filters jsonb,
  p_cursor_sort_key text default null,
  p_cursor_id uuid default null,
  p_limit integer default 30,
  p_include_scope_metadata boolean default true
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_filters jsonb := coalesce(p_filters, '{}'::jsonb);
  v_result jsonb;
  v_default_period_id text;
begin
  if (select auth.uid()) is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  if p_limit <> 30 then
    raise exception 'academic_curriculum_page_limit_invalid' using errcode = '22023';
  end if;
  if p_include_scope_metadata is null then
    raise exception 'academic_curriculum_metadata_mode_invalid' using errcode = '22023';
  end if;
  if (p_cursor_sort_key is null) <> (p_cursor_id is null) then
    raise exception 'academic_curriculum_cursor_invalid' using errcode = '22023';
  end if;
  if pg_catalog.jsonb_typeof(v_filters) <> 'object'
     or exists (
       select 1 from pg_catalog.jsonb_object_keys(v_filters) key
       where key not in ('periodId','search','status','subject','grade','teacher','classroom','viewMode')
     ) then
    raise exception 'academic_curriculum_filters_invalid' using errcode = '22023';
  end if;
  if nullif(pg_catalog.btrim(v_filters ->> 'periodId'), '') is null then
    select group_row.id::text
    into v_default_period_id
    from public.class_schedule_sync_groups group_row
    order by group_row.is_default desc, group_row.sort_order, group_row.name collate dashboard_private.ko_numeric, group_row.id
    limit 1;
    if v_default_period_id is not null then
      v_filters := pg_catalog.jsonb_set(v_filters, '{periodId}', pg_catalog.to_jsonb(v_default_period_id), true);
    end if;
  end if;

  with eligible_classes as materialized (
    select
      class.id, class.name, class.subject, class.subject_area_key, class.grade,
      class.teacher, class.room, class.schedule, class.status, class.start_date,
      class.end_date, class.term_id, class.period, class.textbook_ids,
      dashboard_private.academic_class_status_v1(class.status, nullif(pg_catalog.btrim(class.start_date), '')::date, nullif(pg_catalog.btrim(class.end_date), '')::date) as normalized_status,
      coalesce(nullif(pg_catalog.btrim(class.period), ''), term.name, '') as term_name,
      pg_catalog.jsonb_array_length(coalesce(class.textbook_ids, '[]'::jsonb))::integer as textbook_count,
      coalesce(nullif(pg_catalog.btrim(class.name), ''), U&'\FFFF') collate dashboard_private.ko_numeric as sort_key
    from public.classes class
    left join public.class_terms term on term.id = class.term_id
    where (nullif(pg_catalog.btrim(v_filters ->> 'periodId'), '') is null or exists (
        select 1
        from public.class_schedule_sync_group_members member
        join public.class_schedule_sync_groups group_row on group_row.id = member.group_id
        where member.class_id = class.id
          and (member.group_id::text = v_filters ->> 'periodId' or group_row.name = v_filters ->> 'periodId')
      ))
      and (nullif(pg_catalog.btrim(v_filters ->> 'status'), '') is null
        or dashboard_private.academic_class_status_v1(class.status, nullif(pg_catalog.btrim(class.start_date), '')::date, nullif(pg_catalog.btrim(class.end_date), '')::date) = pg_catalog.btrim(v_filters ->> 'status'))
      and (nullif(pg_catalog.btrim(v_filters ->> 'subject'), '') is null or pg_catalog.btrim(class.subject) = pg_catalog.btrim(v_filters ->> 'subject'))
      and (nullif(pg_catalog.btrim(v_filters ->> 'grade'), '') is null or pg_catalog.btrim(class.grade) = pg_catalog.btrim(v_filters ->> 'grade'))
      and (nullif(pg_catalog.btrim(v_filters ->> 'teacher'), '') is null or coalesce(class.teacher, '') ilike '%' || pg_catalog.btrim(v_filters ->> 'teacher') || '%')
      and (
        nullif(pg_catalog.btrim(v_filters ->> 'classroom'), '') is null
        or exists (
          select 1
          from pg_catalog.regexp_split_to_table(coalesce(class.room, ''), '[,/&·]+') token
          where dashboard_private.academic_classroom_name_v1(pg_catalog.btrim(token))
            = dashboard_private.academic_classroom_name_v1(pg_catalog.btrim(v_filters ->> 'classroom'))
        )
      )
      and (nullif(pg_catalog.btrim(v_filters ->> 'search'), '') is null or pg_catalog.concat_ws(' ', class.name, class.subject, class.grade, class.teacher, class.room, class.schedule) ilike '%' || pg_catalog.btrim(v_filters ->> 'search') || '%')
  ), progress_agg as materialized (
    select log.class_id,
      pg_catalog.count(*)::integer as progress_count,
      pg_catalog.count(distinct coalesce(nullif(log.session_id, ''), nullif(log.progress_key, ''), log.id::text))
        filter (where coalesce(log.status, '') in ('partial','done'))::integer as planned_count,
      pg_catalog.max(log.updated_at) as last_updated_at
    from public.progress_logs log
    join eligible_classes eligible on eligible.id = log.class_id
    group by log.class_id
  ), session_agg as materialized (
    select session.class_id,
      pg_catalog.count(*) filter (where session.schedule_state <> 'skipped')::integer as session_count
    from public.class_lesson_sessions session
    join eligible_classes eligible on eligible.id = session.class_id
    group by session.class_id
  ), next_unplanned as materialized (
    select distinct on (session.class_id)
      session.class_id,
      session.id as next_session_id,
      session.session_key as next_session_key,
      session.session_date as next_session_date,
      session.start_time as next_start_time,
      session.end_time as next_end_time,
      session.schedule_state as next_schedule_state
    from public.class_lesson_sessions session
    join eligible_classes eligible on eligible.id = session.class_id
    where session.schedule_state <> 'skipped'
      and not exists (
        select 1
        from public.progress_logs log
        where log.class_id = session.class_id
          and (
            log.session_id in (session.id::text, session.session_key)
            or log.progress_key in (session.id::text, session.session_key)
          )
          and coalesce(log.status, '') in ('partial','done')
      )
    order by session.class_id, session.session_date, session.start_time nulls last, session.id
  ), base as materialized (
    select
      eligible.id, eligible.name, eligible.subject, eligible.subject_area_key,
      eligible.grade, eligible.teacher, eligible.room, eligible.schedule,
      eligible.status, eligible.start_date, eligible.end_date, eligible.term_id,
      eligible.period, eligible.textbook_ids, eligible.normalized_status,
      eligible.term_name, eligible.textbook_count,
      coalesce(session_agg.session_count, 0)::integer as session_count,
      coalesce(progress_agg.planned_count, 0)::integer as planned_count,
      progress_agg.last_updated_at,
      next_unplanned.next_session_id,
      next_unplanned.next_session_key,
      next_unplanned.next_session_date,
      next_unplanned.next_start_time,
      next_unplanned.next_end_time,
      next_unplanned.next_schedule_state,
      eligible.sort_key
    from eligible_classes eligible
    left join progress_agg on progress_agg.class_id = eligible.id
    left join session_agg on session_agg.class_id = eligible.id
    left join next_unplanned on next_unplanned.class_id = eligible.id
  ), classified as materialized (
    select
      base.id, base.name, base.subject, base.subject_area_key, base.grade,
      base.teacher, base.room, base.schedule, base.status, base.start_date,
      base.end_date, base.term_id, base.period, base.textbook_ids,
      base.normalized_status, base.term_name, base.textbook_count,
      base.session_count, base.planned_count, base.last_updated_at,
      base.next_session_id, base.next_session_key, base.next_session_date,
      base.next_start_time, base.next_end_time, base.next_schedule_state,
      base.sort_key,
      case
        when base.session_count = 0 then '회차 미생성'
        when base.textbook_count = 0 then '교재 미연결'
        when base.planned_count < base.session_count then '진도 미배정'
        else '계획 완료'
      end as state_label,
      case
        when base.session_count = 0 then 'unscheduled'
        when base.textbook_count = 0 then 'unlinked'
        when base.planned_count < base.session_count then 'update'
        else 'done'
      end as view_mode
    from base
  ), filtered as materialized (
    select
      classified.id, classified.name, classified.subject, classified.subject_area_key,
      classified.grade, classified.teacher, classified.room, classified.schedule,
      classified.status, classified.start_date, classified.end_date, classified.term_id,
      classified.period, classified.textbook_ids, classified.normalized_status,
      classified.term_name, classified.textbook_count, classified.session_count,
      classified.planned_count, classified.last_updated_at,
      classified.next_session_id, classified.next_session_key, classified.next_session_date,
      classified.next_start_time, classified.next_end_time, classified.next_schedule_state,
      classified.sort_key, classified.state_label, classified.view_mode
    from classified
    where coalesce(nullif(pg_catalog.btrim(v_filters ->> 'viewMode'), ''), 'all') = 'all'
       or view_mode = pg_catalog.btrim(v_filters ->> 'viewMode')
  ), page_candidates as materialized (
    select
      filtered.id, filtered.name, filtered.subject, filtered.subject_area_key,
      filtered.grade, filtered.teacher, filtered.room, filtered.schedule,
      filtered.status, filtered.start_date, filtered.end_date, filtered.term_id,
      filtered.period, filtered.textbook_ids, filtered.normalized_status,
      filtered.term_name, filtered.textbook_count, filtered.session_count,
      filtered.planned_count, filtered.last_updated_at,
      filtered.next_session_id, filtered.next_session_key, filtered.next_session_date,
      filtered.next_start_time, filtered.next_end_time, filtered.next_schedule_state,
      filtered.sort_key, filtered.state_label, filtered.view_mode
    from filtered
    where p_cursor_sort_key is null
       or sort_key > p_cursor_sort_key collate dashboard_private.ko_numeric
       or (sort_key = p_cursor_sort_key collate dashboard_private.ko_numeric and id > p_cursor_id)
    order by sort_key, id
    limit 31
  ), page_rows as materialized (
    select
      id,
      sort_key::text as sort_key,
      pg_catalog.jsonb_build_object(
        'id', id,
        'title', pg_catalog.regexp_replace(coalesce(name, ''), '^\[[^]]+\]\s*', ''),
        'fullTitle', coalesce(name, ''),
        'subject', coalesce(subject, ''),
        'subjectAreaKey', coalesce(subject_area_key, ''),
        'grade', coalesce(grade, ''),
        'term', term_name,
        'teacherNames', pg_catalog.to_jsonb(pg_catalog.regexp_split_to_array(coalesce(teacher, ''), '\s*[,/&·]\s*')),
        'teacherSummary', coalesce(teacher, ''),
        'classroomNames', pg_catalog.to_jsonb(pg_catalog.regexp_split_to_array(coalesce(room, ''), '\s*[,/&·]\s*')),
        'classroomSummary', coalesce(room, ''),
        'schedule', coalesce(schedule, ''),
        'status', normalized_status,
        'statusFilter', normalized_status,
        'classGroupIds', coalesce((select pg_catalog.jsonb_agg(member.group_id::text order by member.sort_order, member.group_id) from public.class_schedule_sync_group_members member where member.class_id = page_candidates.id), '[]'::jsonb),
        'classGroupNames', coalesce((select pg_catalog.jsonb_agg(group_row.name order by member.sort_order, group_row.name) from public.class_schedule_sync_group_members member join public.class_schedule_sync_groups group_row on group_row.id = member.group_id where member.class_id = page_candidates.id), '[]'::jsonb),
        'classGroupLabel', coalesce((select pg_catalog.string_agg(group_row.name, ', ' order by member.sort_order, group_row.name) from public.class_schedule_sync_group_members member join public.class_schedule_sync_groups group_row on group_row.id = member.group_id where member.class_id = page_candidates.id), '미분류'),
        'textbookCount', textbook_count,
        'textbookCatalog', '[]'::jsonb,
        'textbookTitles', '[]'::jsonb,
        'textbookSummary', case when textbook_count > 0 then textbook_count::text || '권 연결' else '교재 미연결' end,
        'textbookOverflowCount', 0,
        'textbookScopeLabels', '[]'::jsonb,
        'totalSessions', session_count,
        'completedSessions', planned_count,
        'updatedSessions', planned_count,
        'delayedSessions', greatest(session_count - planned_count, 0),
        'plannedSessions', planned_count,
        'progressTargetSessions', case when textbook_count > 0 then session_count else 0 end,
        'delayedProgressSessions', case when textbook_count > 0 then greatest(session_count - planned_count, 0) else 0 end,
        'plannedProgressSessions', planned_count,
        'progressPercent', case when session_count > 0 then pg_catalog.round(planned_count::numeric * 100 / session_count)::integer else 0 end,
        'progressTargetPercent', case when textbook_count > 0 and session_count > 0 then pg_catalog.round(planned_count::numeric * 100 / session_count)::integer else 0 end,
        'lastUpdatedAt', coalesce(last_updated_at::text, ''),
        'stateLabel', state_label,
        'latestNoteSummary', '',
        'latestNoteSessionLabel', '',
        'pendingSessionLabels', '[]'::jsonb,
        'nextSession', case when next_session_id is null then null else pg_catalog.jsonb_build_object(
          'sessionId', next_session_id,
          'sessionKey', next_session_key,
          'sessionOrder', 0,
          'label', pg_catalog.to_char(next_session_date, 'YYYY-MM-DD'),
          'progressStatus', 'pending',
          'hasActualContent', false,
          'updatedAt', '',
          'noteSummary', '',
          'dateValue', next_session_date,
          'dateLabel', next_session_date,
          'periodLabel', pg_catalog.concat_ws('~', next_start_time::text, next_end_time::text),
          'scheduleState', next_schedule_state,
          'scheduleMemo', '',
          'makeupMemo', '',
          'makeupDate', '',
          'hasPlanContent', false,
          'planSummary', '',
          'textbookEntryCount', 0,
          'textbookEntries', '[]'::jsonb
        ) end,
        'sessionSummaries', '[]'::jsonb,
        'searchText', pg_catalog.lower(pg_catalog.concat_ws(' ', name, subject, grade, teacher, room, schedule, state_label))
      ) as row_data
    from page_candidates
  ), stats as materialized (
    select pg_catalog.jsonb_build_object(
      'total', pg_catalog.count(*)::integer,
      'managedClassCount', pg_catalog.count(*) filter (where session_count > 0)::integer,
      'totalSessions', coalesce(pg_catalog.sum(session_count),0)::integer,
      'completedSessions', coalesce(pg_catalog.sum(planned_count),0)::integer,
      'pendingSessions', coalesce(pg_catalog.sum(greatest(session_count-planned_count,0)),0)::integer,
      'linkedTextbooks', coalesce(pg_catalog.sum(textbook_count),0)::integer,
      'unlinkedClassCount', pg_catalog.count(*) filter (where textbook_count=0)::integer,
      'noScheduleClassCount', pg_catalog.count(*) filter (where view_mode='unscheduled')::integer,
      'updateNeededClassCount', pg_catalog.count(*) filter (where state_label='진도 미배정')::integer,
      'completedClassCount', pg_catalog.count(*) filter (where state_label='계획 완료')::integer,
      'viewModeCounts', (
        select pg_catalog.jsonb_build_object(
          'all', pg_catalog.count(*)::integer,
          'unlinked', pg_catalog.count(*) filter (where view_mode='unlinked')::integer,
          'unscheduled', pg_catalog.count(*) filter (where view_mode='unscheduled')::integer,
          'update', pg_catalog.count(*) filter (where view_mode='update')::integer,
          'done', pg_catalog.count(*) filter (where view_mode='done')::integer
        )
        from classified
      )
    ) as data from filtered
    where p_include_scope_metadata
  ), filter_options as materialized (
    select pg_catalog.jsonb_build_object(
      'periods', coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('value',id,'label',name,'isDefault',is_default) order by sort_order,name) from (select id,name,is_default,sort_order from public.class_schedule_sync_groups order by sort_order,name limit 500) bounded), '[]'::jsonb),
      'statuses', pg_catalog.to_jsonb(array['수강','개강 준비','종강']),
      'subjects', coalesce((select pg_catalog.jsonb_agg(value order by value) from (select distinct subject as value from base where nullif(pg_catalog.btrim(subject),'') is not null order by subject limit 500) bounded), '[]'::jsonb),
      'grades', coalesce((select pg_catalog.jsonb_agg(value order by value) from (select distinct grade as value from base where nullif(pg_catalog.btrim(grade),'') is not null order by grade limit 500) bounded), '[]'::jsonb),
      'teachers', coalesce((select pg_catalog.jsonb_agg(value order by value) from (select distinct pg_catalog.btrim(token) as value from base cross join lateral pg_catalog.regexp_split_to_table(coalesce(teacher,''), '[,/&·]+') token where pg_catalog.btrim(token)<>'' order by value limit 500) bounded), '[]'::jsonb),
      'classrooms', coalesce((select pg_catalog.jsonb_agg(value order by value) from (select distinct dashboard_private.academic_classroom_name_v1(pg_catalog.btrim(token)) as value from base cross join lateral pg_catalog.regexp_split_to_table(coalesce(room,''), '[,/&·]+') token where pg_catalog.btrim(token)<>'' order by value limit 500) bounded), '[]'::jsonb)
    ) as data
    where p_include_scope_metadata
  )
  select pg_catalog.jsonb_build_object(
    'rows', coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',id,'sort_key',sort_key,'row_data',row_data) order by sort_key,id) from page_rows), '[]'::jsonb),
    'stats', case when p_include_scope_metadata then (select data from stats) else null end,
    'filterOptions', case when p_include_scope_metadata then (select data from filter_options) else null end,
    'resolvedPeriodId', v_filters ->> 'periodId'
  ) into v_result;

  return v_result;
end;
$$;
create function public.get_academic_curriculum_detail_v1(p_class_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_class jsonb;
  v_textbook_ids jsonb;
  v_schedule_count integer;
  v_progress_count integer;
  v_textbook_count integer;
  v_schedule jsonb;
  v_progress jsonb;
  v_textbooks jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  if p_class_id is null then
    raise exception 'academic_curriculum_class_id_required' using errcode = '22023';
  end if;
  select pg_catalog.jsonb_build_object(
    'id', class.id,
    'name', class.name,
    'className', class.name,
    'classType', class.class_type,
    'subject', class.subject,
    'subjectAreaKey', class.subject_area_key,
    'grade', class.grade,
    'teacher', class.teacher,
    'schedule', class.schedule,
    'room', class.room,
    'status', class.status,
    'termId', class.term_id,
    'period', class.period,
    'startDate', class.start_date,
    'endDate', class.end_date,
    'textbookIds', coalesce(class.textbook_ids, '[]'::jsonb),
    'scheduleStorageMode', class.schedule_storage_mode,
    'scheduleRevision', class.schedule_revision
  ), coalesce(class.textbook_ids, '[]'::jsonb)
  into v_class, v_textbook_ids
  from public.classes class where class.id = p_class_id;
  if not found then return null; end if;

  select pg_catalog.count(*) into v_schedule_count from public.class_lesson_sessions where class_id = p_class_id;
  select pg_catalog.count(*) into v_progress_count from public.progress_logs where class_id = p_class_id;
  select pg_catalog.jsonb_array_length(v_textbook_ids) into v_textbook_count;
  if v_schedule_count > 500 or v_progress_count > 500 or v_textbook_count > 500 then
    raise exception 'academic_curriculum_detail_too_dense' using errcode = '54000';
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id',id,'sessionKey',session_key,'sessionDate',session_date,'scheduleState',schedule_state,
    'startTime',start_time,'endTime',end_time,'teacherName',teacher_name_snapshot,
    'classroomName',classroom_name_snapshot,'memo',memo,'publicNote',public_note,'teacherNote',teacher_note,
    'revision',revision,'updatedAt',updated_at
  ) order by session_date,start_time,id), '[]'::jsonb)
  into v_schedule from public.class_lesson_sessions where class_id = p_class_id limit 501;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id',id,'classId',class_id,'textbookId',textbook_id,'progressKey',progress_key,
    'sessionId',session_id,'sessionOrder',session_order,'status',status,'rangeStart',range_start,
    'rangeEnd',range_end,'rangeLabel',range_label,'publicNote',public_note,'teacherNote',teacher_note,
    'updatedAt',updated_at
  ) order by updated_at desc,id), '[]'::jsonb)
  into v_progress from public.progress_logs where class_id = p_class_id limit 501;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id',book.id,'title',coalesce(book.title,book.name,''),'publisher',coalesce(book.publisher,''),
    'subject',coalesce(book.subject,''),'subjectAreaKey',coalesce(book.subject_area_key,''),
    'category',coalesce(book.category,'')
  ) order by coalesce(book.title,book.name,''),book.id), '[]'::jsonb)
  into v_textbooks
  from public.textbooks book
  where v_textbook_ids ? book.id::text
  limit 501;

  return pg_catalog.jsonb_build_object(
    'id', p_class_id,
    'classItem', v_class,
    'scheduleRows', v_schedule,
    'progressRows', v_progress,
    'textbookRows', v_textbooks
  );
end;
$$;
revoke all on function dashboard_private.academic_class_status_v1(text,date,date) from public, anon, authenticated;
revoke all on function dashboard_private.academic_classroom_name_v1(text) from public, anon, authenticated;
revoke all on function public.get_academic_timetable_range_v1(date,date,text,text,text) from public, anon, authenticated;
revoke all on function public.get_academic_curriculum_page_v1(jsonb,text,uuid,integer,boolean) from public, anon, authenticated;
revoke all on function public.get_academic_curriculum_detail_v1(uuid) from public, anon, authenticated;
grant usage on schema dashboard_private to authenticated;
grant execute on function dashboard_private.academic_class_status_v1(text,date,date) to authenticated;
grant execute on function dashboard_private.academic_classroom_name_v1(text) to authenticated;
grant execute on function public.get_academic_timetable_range_v1(date,date,text,text,text) to authenticated;
grant execute on function public.get_academic_curriculum_page_v1(jsonb,text,uuid,integer,boolean) to authenticated;
grant execute on function public.get_academic_curriculum_detail_v1(uuid) to authenticated;
commit;
begin;
create function public.list_current_registration_observation_customer_messages_v1(
  p_actor_profile_id uuid,
  p_task_id uuid,
  p_message_kind text,
  p_observation_id uuid,
  p_source_revision integer,
  p_source_fingerprint text,
  p_recipient_hash text,
  p_limit integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
set timezone = 'UTC'
as $$
declare
  v_actor_role text;
  v_result jsonb;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'registration_customer_message_access_denied' using errcode = '42501';
  end if;
  if p_message_kind not in ('observation_booking', 'observation_reminder')
    or p_task_id is null
    or p_observation_id is null
    or p_source_revision is null
    or p_source_revision < 1
    or p_source_fingerprint is null
    or p_source_fingerprint !~ '^[0-9a-f]{64}$'
    or p_recipient_hash is null
    or p_recipient_hash !~ '^[0-9a-f]{64}$'
    or p_limit is null
    or p_limit < 1
    or p_limit > 50 then
    raise exception 'registration_customer_message_history_input_invalid'
      using errcode = '22023';
  end if;

  v_actor_role := dashboard_private.registration_customer_message_assert_actor_v1(
    p_actor_profile_id,
    p_task_id,
    'history'
  );
  perform 1
  from public.ops_registration_observations observation
  where observation.id = p_observation_id
    and observation.task_id = p_task_id;
  if not found then
    raise exception 'registration_customer_message_source_not_found' using errcode = 'P0002';
  end if;

  if v_actor_role in ('admin', 'staff') then
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'messageId', message.id,
        'messageKind', message.message_kind,
        'currentStatus', message.status,
        'confirmedByName', case
          when message.delivery_origin = 'scheduled' then '자동 발송'
          else coalesce(nullif(pg_catalog.btrim(profile.name), ''), '담당자')
        end,
        'confirmedAt', message.confirmed_at,
        'updatedAt', message.updated_at,
        'recipientLast4', message.recipient_last4,
        'canCheck', (
          message.delivery_origin = 'manual'
          and message.provider_attempt_count = 1
          and message.provider_attempt_started_at <= pg_catalog.clock_timestamp() - interval '15 minutes'
          and message.status in ('pending', 'unknown')
        )
      ) order by message.created_at desc, message.id desc
    ), '[]'::jsonb)
    into v_result
    from (
      select outbox.*
      from public.ops_registration_customer_messages outbox
      where outbox.task_id = p_task_id
        and outbox.observation_id = p_observation_id
        and outbox.message_kind = p_message_kind
        and outbox.source_revision = p_source_revision
        and outbox.source_fingerprint = p_source_fingerprint
        and outbox.recipient_hash = p_recipient_hash
      order by outbox.created_at desc, outbox.id desc
      limit p_limit
    ) message
    left join public.profiles profile on profile.id = message.confirmed_by;
  else
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'messageKind', message.message_kind,
        'currentStatus', message.status,
        'confirmedByName', case
          when message.delivery_origin = 'scheduled' then '자동 발송'
          else coalesce(nullif(pg_catalog.btrim(profile.name), ''), '담당자')
        end,
        'confirmedAt', message.confirmed_at,
        'updatedAt', message.updated_at
      ) order by message.created_at desc, message.id desc
    ), '[]'::jsonb)
    into v_result
    from (
      select outbox.*
      from public.ops_registration_customer_messages outbox
      where outbox.task_id = p_task_id
        and outbox.observation_id = p_observation_id
        and outbox.message_kind = p_message_kind
        and outbox.source_revision = p_source_revision
        and outbox.source_fingerprint = p_source_fingerprint
        and outbox.recipient_hash = p_recipient_hash
      order by outbox.created_at desc, outbox.id desc
      limit p_limit
    ) message
    left join public.profiles profile on profile.id = message.confirmed_by;
  end if;
  return v_result;
end;
$$;
alter function public.list_current_registration_observation_customer_messages_v1(
  uuid, uuid, text, uuid, integer, text, text, integer
) owner to postgres;
revoke all on function public.list_current_registration_observation_customer_messages_v1(
  uuid, uuid, text, uuid, integer, text, text, integer
) from public, anon, authenticated, service_role;
grant execute on function public.list_current_registration_observation_customer_messages_v1(
  uuid, uuid, text, uuid, integer, text, text, integer
) to service_role;
commit;
begin;
set local lock_timeout = '5s';
set local statement_timeout = '120s';
create extension if not exists pg_cron with schema pg_catalog;
create table dashboard_private.lightweight_registration_alert_runtime_settings (
  singleton boolean primary key default true check (singleton),
  enabled boolean not null default false,
  updated_at timestamptz not null default statement_timestamp()
);
create table dashboard_private.lightweight_registration_alert_states (
  id uuid primary key default gen_random_uuid(),
  source_kind text not null
    check (source_kind in ('level_test', 'visit_consultation', 'observation_class')),
  source_id uuid not null,
  source_revision bigint not null check (source_revision > 0),
  event_kind text not null
    check (event_kind in ('booking_confirmed', 'same_day_reminder')),
  channel text not null
    check (channel in ('customer_alimtalk', 'google_chat')),
  event_key text not null check (nullif(btrim(event_key), '') is not null),
  result text not null default 'pending'
    check (result in ('pending', 'accepted', 'unknown', 'failed_hold')),
  last_processed_at timestamptz,
  created_at timestamptz not null default statement_timestamp(),
  updated_at timestamptz not null default statement_timestamp(),
  unique (source_kind, source_id, event_kind, channel, event_key)
);
create table dashboard_private.lightweight_registration_alert_deliveries (
  id uuid primary key default gen_random_uuid(),
  state_id uuid not null
    references dashboard_private.lightweight_registration_alert_states(id) on delete restrict,
  source_revision bigint not null check (source_revision > 0),
  status text not null default 'pending'
    check (status in ('pending', 'claimed', 'accepted', 'unknown', 'failed_hold')),
  claim_token uuid,
  claim_expires_at timestamptz,
  attempt_count integer not null default 0 check (attempt_count between 0 and 3),
  provider_http_status integer,
  provider_reference text,
  mention_resolution text not null default 'not_applicable'
    check (mention_resolution in ('not_applicable', 'resolved', 'mention_unresolved')),
  terminalized_at timestamptz,
  created_at timestamptz not null default statement_timestamp(),
  updated_at timestamptz not null default statement_timestamp(),
  unique (state_id),
  check (
    (status = 'claimed' and claim_token is not null and claim_expires_at is not null)
    or (status <> 'claimed' and claim_token is null and claim_expires_at is null)
  ),
  check (
    (status in ('accepted', 'unknown', 'failed_hold') and terminalized_at is not null)
    or (status in ('pending', 'claimed') and terminalized_at is null)
  ),
  check (provider_http_status is null or provider_http_status between 100 and 599),
  check (
    provider_reference is null
    or (
      char_length(provider_reference) = 64
      and provider_reference ~ '^[a-f0-9]{64}$'
    )
  )
);
create table dashboard_private.lightweight_registration_alert_daily_runs (
  kst_date date primary key,
  cutoff_at timestamptz not null,
  status text not null check (status in ('running', 'completed', 'failed')),
  candidate_count integer not null default 0 check (candidate_count >= 0),
  delivery_count integer not null default 0 check (delivery_count >= 0),
  started_at timestamptz not null default statement_timestamp(),
  finished_at timestamptz,
  error_code text,
  check (cutoff_at = ((kst_date + time '10:00') at time zone 'Asia/Seoul')),
  check (
    (status = 'running' and finished_at is null and error_code is null)
    or (status = 'completed' and finished_at is not null and error_code is null)
    or (status = 'failed' and finished_at is not null and nullif(btrim(error_code), '') is not null)
  )
);
create index lightweight_registration_alert_deliveries_pending_idx
  on dashboard_private.lightweight_registration_alert_deliveries(created_at, id)
  where status = 'pending';
create index lightweight_registration_alert_deliveries_retention_idx
  on dashboard_private.lightweight_registration_alert_deliveries(terminalized_at, id)
  where terminalized_at is not null;
alter table dashboard_private.lightweight_registration_alert_runtime_settings enable row level security;
alter table dashboard_private.lightweight_registration_alert_states enable row level security;
alter table dashboard_private.lightweight_registration_alert_deliveries enable row level security;
alter table dashboard_private.lightweight_registration_alert_daily_runs enable row level security;
revoke all on table dashboard_private.lightweight_registration_alert_runtime_settings
  from public, anon, authenticated, service_role;
revoke all on table dashboard_private.lightweight_registration_alert_states
  from public, anon, authenticated, service_role;
revoke all on table dashboard_private.lightweight_registration_alert_deliveries
  from public, anon, authenticated, service_role;
revoke all on table dashboard_private.lightweight_registration_alert_daily_runs
  from public, anon, authenticated, service_role;
create or replace function dashboard_private.enqueue_lightweight_registration_alerts_v1(
  p_source_kind text,
  p_source_id uuid,
  p_source_revision bigint,
  p_event_kind text,
  p_event_key text
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_channels text[] := case
    when p_source_kind = 'level_test' then array['customer_alimtalk']
    when p_source_kind in ('visit_consultation', 'observation_class')
      then array['customer_alimtalk', 'google_chat']
    else null
  end;
  v_channel text;
  v_state_id uuid;
  v_inserted integer := 0;
begin
  if p_source_id is null
    or p_source_revision is null
    or p_source_revision < 1
    or p_event_kind not in ('booking_confirmed', 'same_day_reminder')
    or nullif(pg_catalog.btrim(p_event_key), '') is null
    or v_channels is null
    or (p_event_kind = 'booking_confirmed' and p_event_key <> 'booking')
    or (
      p_event_kind = 'same_day_reminder'
      and p_event_key !~ '^\d{4}-\d{2}-\d{2}$'
    )
  then
    raise exception 'lightweight_registration_alert_invalid'
      using errcode = '22023';
  end if;

  if not coalesce((
    select settings.enabled
    from dashboard_private.lightweight_registration_alert_runtime_settings settings
    where settings.singleton
  ), false) then
    return 0;
  end if;

  foreach v_channel in array v_channels loop
    v_state_id := null;
    insert into dashboard_private.lightweight_registration_alert_states(
      source_kind,
      source_id,
      source_revision,
      event_kind,
      channel,
      event_key
    ) values (
      p_source_kind,
      p_source_id,
      p_source_revision,
      p_event_kind,
      v_channel,
      p_event_key
    )
    on conflict (source_kind, source_id, event_kind, channel, event_key)
      do nothing
    returning id into v_state_id;

    if v_state_id is not null then
      insert into dashboard_private.lightweight_registration_alert_deliveries(
        state_id,
        source_revision
      ) values (
        v_state_id,
        p_source_revision
      );
      v_inserted := v_inserted + 1;
    end if;
  end loop;

  return v_inserted;
end;
$$;
revoke all on function dashboard_private.enqueue_lightweight_registration_alerts_v1(
  text, uuid, bigint, text, text
) from public, anon, authenticated, service_role;
create or replace function public.enqueue_lightweight_registration_booking_alerts_v1(
  p_source_kind text,
  p_source_id uuid,
  p_source_revision bigint
)
returns integer
language sql
security definer
set search_path = ''
as $$
  select dashboard_private.enqueue_lightweight_registration_alerts_v1(
    p_source_kind,
    p_source_id,
    p_source_revision,
    'booking_confirmed',
    'booking'
  );
$$;
revoke all on function public.enqueue_lightweight_registration_booking_alerts_v1(
  text, uuid, bigint
) from public, anon, authenticated;
grant execute on function public.enqueue_lightweight_registration_booking_alerts_v1(
  text, uuid, bigint
) to service_role;
create or replace function dashboard_private.capture_lightweight_registration_booking_alerts_v1()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'scheduled'
    and new.kind in ('level_test', 'visit_consultation', 'observation_class')
  then
    perform dashboard_private.enqueue_lightweight_registration_alerts_v1(
      new.kind,
      new.id,
      new.notification_revision,
      'booking_confirmed',
      'booking'
    );
  end if;
  return new;
end;
$$;
revoke all on function dashboard_private.capture_lightweight_registration_booking_alerts_v1()
  from public, anon, authenticated, service_role;
create trigger capture_lightweight_registration_booking_alerts
after insert on public.ops_registration_appointments
for each row
execute function dashboard_private.capture_lightweight_registration_booking_alerts_v1();
create or replace function dashboard_private.lightweight_registration_alert_now_v1()
returns timestamptz
language sql
stable
security invoker
set search_path = ''
as $$
  select statement_timestamp()
$$;
revoke all on function dashboard_private.lightweight_registration_alert_now_v1()
  from public, anon, authenticated, service_role;
create or replace function public.enqueue_due_lightweight_registration_reminders_v1()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := dashboard_private.lightweight_registration_alert_now_v1();
  v_kst_date date := (v_now at time zone 'Asia/Seoul')::date;
  v_cutoff timestamptz := ((v_now at time zone 'Asia/Seoul')::date + time '10:00')
    at time zone 'Asia/Seoul';
  v_appointment record;
  v_candidate_count integer := 0;
  v_delivery_count integer := 0;
begin
  if v_now < v_cutoff then
    raise exception 'lightweight_registration_reminder_before_cutoff'
      using errcode = '55000';
  end if;

  insert into dashboard_private.lightweight_registration_alert_daily_runs(
    kst_date,
    cutoff_at,
    status
  ) values (
    v_kst_date,
    v_cutoff,
    'running'
  )
  on conflict (kst_date) do update
  set cutoff_at = excluded.cutoff_at,
      status = 'running',
      candidate_count = 0,
      delivery_count = 0,
      started_at = excluded.started_at,
      finished_at = null,
      error_code = null
  where dashboard_private.lightweight_registration_alert_daily_runs.status = 'failed';

  if not found then
    return pg_catalog.jsonb_build_object(
      'status', 'already_processed',
      'kstDate', v_kst_date,
      'candidateCount', 0,
      'deliveryCount', 0
    );
  end if;

  for v_appointment in
    select appointment.id,
           appointment.kind,
           appointment.notification_revision
    from public.ops_registration_appointments appointment
    where appointment.status = 'scheduled'
      and appointment.kind in ('level_test', 'visit_consultation', 'observation_class')
      and (appointment.scheduled_at at time zone 'Asia/Seoul')::date = v_kst_date
      and appointment.created_at <= v_cutoff
    order by appointment.scheduled_at, appointment.id
  loop
    v_candidate_count := v_candidate_count + 1;
    v_delivery_count := v_delivery_count
      + dashboard_private.enqueue_lightweight_registration_alerts_v1(
          v_appointment.kind,
          v_appointment.id,
          v_appointment.notification_revision,
          'same_day_reminder',
          v_kst_date::text
        );
  end loop;

  update dashboard_private.lightweight_registration_alert_daily_runs run
  set status = 'completed',
      candidate_count = v_candidate_count,
      delivery_count = v_delivery_count,
      finished_at = v_now
  where run.kst_date = v_kst_date;

  perform public.prune_lightweight_registration_alert_history_v1(100);

  return pg_catalog.jsonb_build_object(
    'status', 'completed',
    'kstDate', v_kst_date,
    'candidateCount', v_candidate_count,
    'deliveryCount', v_delivery_count
  );
exception
  when others then
    update dashboard_private.lightweight_registration_alert_daily_runs run
    set status = 'failed',
        finished_at = statement_timestamp(),
        error_code = 'daily_run_failed'
    where run.kst_date = v_kst_date
      and run.status = 'running';
    raise;
end;
$$;
revoke all on function public.enqueue_due_lightweight_registration_reminders_v1()
  from public, anon, authenticated;
grant execute on function public.enqueue_due_lightweight_registration_reminders_v1()
  to service_role;
create or replace function public.prune_lightweight_registration_alert_history_v1(
  p_limit integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := statement_timestamp();
  v_delivery_count integer := 0;
  v_run_count integer := 0;
  v_batch_count integer := 0;
begin
  if p_limit is null or not (p_limit between 1 and 500) then
    raise exception 'lightweight_registration_alert_prune_limit_invalid'
      using errcode = '22023';
  end if;

  update dashboard_private.lightweight_registration_alert_states state
  set result = 'failed_hold',
      last_processed_at = v_now,
      updated_at = v_now
  where exists (
    select 1
    from dashboard_private.lightweight_registration_alert_deliveries delivery
    where delivery.state_id = state.id
      and delivery.status in ('pending', 'claimed')
      and delivery.created_at <= v_now - interval '7 days'
  );

  update dashboard_private.lightweight_registration_alert_deliveries delivery
  set status = 'failed_hold',
      claim_token = null,
      claim_expires_at = null,
      terminalized_at = delivery.created_at,
      updated_at = v_now
  where delivery.status in ('pending', 'claimed')
    and delivery.created_at <= v_now - interval '7 days';

  loop
    with deleted as (
      delete from dashboard_private.lightweight_registration_alert_deliveries delivery
      where delivery.id in (
        select candidate.id
        from dashboard_private.lightweight_registration_alert_deliveries candidate
        where candidate.terminalized_at <= v_now - interval '7 days'
        order by candidate.terminalized_at, candidate.id
        limit p_limit
        for update skip locked
      )
      returning 1
    )
    select pg_catalog.count(*)::integer into v_batch_count from deleted;
    v_delivery_count := v_delivery_count + v_batch_count;
    exit when v_batch_count < p_limit;
  end loop;

  update dashboard_private.lightweight_registration_alert_daily_runs run
  set status = 'failed',
      finished_at = run.started_at,
      error_code = 'stale_run'
  where run.status = 'running'
    and run.started_at <= v_now - interval '7 days';

  loop
    with deleted as (
      delete from dashboard_private.lightweight_registration_alert_daily_runs run
      where run.kst_date in (
        select candidate.kst_date
        from dashboard_private.lightweight_registration_alert_daily_runs candidate
        where candidate.finished_at <= v_now - interval '7 days'
        order by candidate.finished_at, candidate.kst_date
        limit p_limit
        for update skip locked
      )
      returning 1
    )
    select pg_catalog.count(*)::integer into v_batch_count from deleted;
    v_run_count := v_run_count + v_batch_count;
    exit when v_batch_count < p_limit;
  end loop;

  return pg_catalog.jsonb_build_object(
    'deliveryReceiptsDeleted', v_delivery_count,
    'runDetailsDeleted', v_run_count
  );
end;
$$;
revoke all on function public.prune_lightweight_registration_alert_history_v1(integer)
  from public, anon, authenticated;
grant execute on function public.prune_lightweight_registration_alert_history_v1(integer)
  to service_role;
create or replace function public.manage_lightweight_registration_alert_schedule_v1(
  p_action text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job_id bigint;
  v_old_active integer;
begin
  if p_action not in ('install_inactive', 'activate', 'disable', 'remove') then
    raise exception 'lightweight_registration_alert_schedule_action_invalid'
      using errcode = '22023';
  end if;
  if pg_catalog.to_regclass('cron.job') is null
    or pg_catalog.to_regprocedure('cron.schedule(text,text,text)') is null
    or pg_catalog.to_regprocedure('cron.alter_job(bigint,text,text,text,text,boolean)') is null
  then
    raise exception 'lightweight_registration_alert_schedule_unavailable'
      using errcode = '55000';
  end if;

  execute $sql$
    select pg_catalog.count(*)::integer
    from cron.job
    where jobname in (
      'tips-notification-worker-v1',
      'tips-notification-cutover-watchdog-v1',
      'tips-registration-customer-reminder-v1'
    )
      and active
  $sql$ into v_old_active;
  if v_old_active <> 0 then
    raise exception 'lightweight_registration_alert_legacy_schedule_active'
      using errcode = '55000';
  end if;

  execute $sql$
    select jobid
    from cron.job
    where jobname = 'tips-lightweight-registration-reminder-v1'
  $sql$ into v_job_id;

  if p_action = 'install_inactive' then
    if v_job_id is null then
      v_job_id := cron.schedule(
        'tips-lightweight-registration-reminder-v1',
        '0 1 * * *',
        'select public.enqueue_due_lightweight_registration_reminders_v1();'
      );
    end if;
    perform cron.alter_job(v_job_id, active := false);
  elsif p_action = 'activate' then
    if v_job_id is null then
      raise exception 'lightweight_registration_alert_schedule_missing'
        using errcode = '55000';
    end if;
    if not coalesce((
      select settings.enabled
      from dashboard_private.lightweight_registration_alert_runtime_settings settings
      where settings.singleton
    ), false) then
      raise exception 'lightweight_registration_alert_runtime_inactive'
        using errcode = '55000';
    end if;
    perform cron.alter_job(v_job_id, active := true);
  elsif p_action = 'disable' then
    if v_job_id is not null then
      perform cron.alter_job(v_job_id, active := false);
    end if;
  elsif v_job_id is not null then
    perform cron.unschedule(v_job_id);
    v_job_id := null;
  end if;

  return pg_catalog.jsonb_build_object(
    'action', p_action,
    'jobId', v_job_id,
    'schedule', '0 1 * * *',
    'active', p_action = 'activate'
  );
end;
$$;
revoke all on function public.manage_lightweight_registration_alert_schedule_v1(text)
  from public, anon, authenticated;
grant execute on function public.manage_lightweight_registration_alert_schedule_v1(text)
  to service_role;
alter function dashboard_private.enqueue_lightweight_registration_alerts_v1(
  text, uuid, bigint, text, text
